import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { ChevronDown, Filter, Lightbulb } from "lucide-react";
import { getDocument, listActionPreviews } from "../../../db/boards";
import type { StructuredAction } from "../../../db/collections";
import { useCommand } from "../../../hooks/useCommand";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";

// ── Types ──────────────────────────────────────────────────

interface ActionPreview {
  id: string;
  previewType: string;
  sourceActionTitle: string;
  beforeSnapshot: string;
  afterPreview: string;
  bestPracticeSample: string;
  notes: string[];
}

// ── Labels ─────────────────────────────────────────────────

const CATEGORY_LABEL: Record<string, string> = {
  "geo-optimization": "GEO",
  "seo-technical": "SEO",
  content: "Content",
  "local-seo": "Local",
  naver: "Naver",
};

const PRIORITY_STYLE: Record<string, string> = {
  high: "bg-rose-500/12 text-rose-600 border border-rose-500/25",
  medium: "bg-amber-500/12 text-amber-600 border border-amber-500/25",
  low: "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] border border-[var(--shell-border)]",
};

const EFFORT_LABEL: Record<string, string> = { low: "Easy", medium: "Medium", high: "Hard" };
const CHANNEL_LABEL: Record<string, string> = {
  "customer-site": "Site",
  "customer-sns": "SNS",
  "external-trust": "External",
  marketplace: "Marketplace",
  measurement: "Measurement",
};
const DIRECTION_LABEL: Record<string, string> = { auto: "Auto", "semi-auto": "Semi-auto", manual: "Manual" };

const PREVIEW_TYPES = [
  { key: "schema", label: "Schema" },
  { key: "meta_og", label: "Meta/OG" },
  { key: "content_draft", label: "Content Draft" },
  { key: "ai_simulation", label: "AI Simulation" },
] as const;

// ── Component ──────────────────────────────────────────────

export function Recommended() {
  const { id } = useParams<{ id: string }>();
  const [actions, setActions] = useState<StructuredAction[]>([]);
  const [previews, setPreviews] = useState<ActionPreview[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterCategory, setFilterCategory] = useState("all");
  const [filterPriority, setFilterPriority] = useState("all");
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    Promise.all([
      getDocument(id, "action-plan"),
      listActionPreviews(id),
    ]).then(([doc, pvs]) => {
      const data = (doc?.data ?? {}) as Record<string, unknown>;
      const acts = (data.structuredActions ?? data.actions ?? []) as StructuredAction[];
      setActions(acts);
      setPreviews(pvs as unknown as ActionPreview[]);
      setLoading(false);
    });
  }, [id]);

  const handleCreatePreview = async (previewType: string) => {
    const sourceActionTitle = actions[0]?.title || "Core GEO Action";
    await cmd.execute("create_action_preview", { previewType, sourceActionTitle });
    if (id) {
      const pvs = await listActionPreviews(id);
      setPreviews(pvs as unknown as ActionPreview[]);
    }
  };

  // ── Derived ──

  const allCategories = useMemo(() => [...new Set(actions.map((a) => a.category))], [actions]);

  const filtered = useMemo(() => {
    let result = actions;
    if (filterCategory !== "all") result = result.filter((a) => a.category === filterCategory);
    if (filterPriority !== "all") result = result.filter((a) => a.priority === filterPriority);
    return result;
  }, [actions, filterCategory, filterPriority]);

  const highCount = actions.filter((a) => a.priority === "high").length;
  const medCount = actions.filter((a) => a.priority === "medium").length;

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        Loading...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Lightbulb} label="Total Actions" value={String(actions.length)} color="text-blue-600" />
        <MetricCard icon={Lightbulb} label="High Priority" value={String(highCount)} color="text-rose-500" />
        <MetricCard icon={Lightbulb} label="Medium Priority" value={String(medCount)} color="text-amber-500" />
        <MetricCard icon={Lightbulb} label="Previews" value={String(previews.length)} color="text-teal-600" />
      </div>

      {/* Preview Generator */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h3 className="text-sm font-semibold text-[var(--shell-text)]">Action Preview</h3>
            <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">Generate before/after previews for schema, meta, content, and AI simulation</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {PREVIEW_TYPES.map((item) => (
              <button
                key={item.key}
                type="button"
                onClick={() => handleCreatePreview(item.key)}
                disabled={cmd.isRunning}
                className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text-muted)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>

        {cmd.isRunning && (
          <div className="mt-3 flex items-center gap-2 rounded-xl bg-[var(--shell-accent)]/10 px-3 py-2 text-xs font-medium text-[var(--shell-accent)]">
            <span className="inline-flex h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
            {cmd.message || "Generating preview..."}
          </div>
        )}

        {previews.length > 0 && (
          <div className="mt-4 space-y-3">
            {previews.slice(0, 4).map((preview) => (
              <PreviewCard key={preview.id} preview={preview} />
            ))}
          </div>
        )}
      </div>

      {/* Filters */}
      {actions.length > 0 && (
        <div className="flex flex-wrap items-center gap-2">
          <Filter className="h-3.5 w-3.5 text-[var(--shell-text-muted)]" />
          <FilterChip label="All" active={filterPriority === "all" && filterCategory === "all"} onClick={() => { setFilterPriority("all"); setFilterCategory("all"); }} />
          <FilterChip label="High" active={filterPriority === "high"} onClick={() => setFilterPriority(filterPriority === "high" ? "all" : "high")} />
          <FilterChip label="Medium" active={filterPriority === "medium"} onClick={() => setFilterPriority(filterPriority === "medium" ? "all" : "medium")} />
          <FilterChip label="Low" active={filterPriority === "low"} onClick={() => setFilterPriority(filterPriority === "low" ? "all" : "low")} />
          {allCategories.length > 1 && (
            <>
              <div className="h-4 w-px bg-[var(--shell-border)]" />
              {allCategories.map((cat) => (
                <FilterChip
                  key={cat}
                  label={CATEGORY_LABEL[cat] || cat}
                  active={filterCategory === cat}
                  onClick={() => setFilterCategory(filterCategory === cat ? "all" : cat)}
                />
              ))}
            </>
          )}
        </div>
      )}

      {/* Action list */}
      <div className="space-y-2">
        {filtered.length > 0 ? (
          filtered.map((action, idx) => (
            <ActionCard key={idx} action={action} />
          ))
        ) : actions.length > 0 ? (
          <div className="rounded-2xl border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
            현재 필터에 해당하는 액션이 없습니다
          </div>
        ) : (
          <EmptyState
            icon={Lightbulb}
            title="No actions yet"
            description="전체 분석을 실행하면 우선순위가 매겨진 액션 권고가 생성됩니다"
          />
        )}
      </div>
    </div>
  );
}

// ── Sub-components ──────────────────────────────────────────

function ActionCard({ action }: { action: StructuredAction }) {
  const [open, setOpen] = useState(false);
  const hasDetail = !!(
    action.contentBrief ||
    (action.steps && action.steps.length > 0) ||
    (action.targetQueries && action.targetQueries.length > 0) ||
    (action.relatedKeywords && action.relatedKeywords.length > 0)
  );

  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="flex w-full items-start gap-3 p-4 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
      >
        <ChevronDown className={`mt-0.5 h-4 w-4 shrink-0 text-[var(--shell-text-muted)] transition-transform ${open ? "" : "-rotate-90"}`} />
        <div className="min-w-0 flex-1">
          {/* Badges row */}
          <div className="flex flex-wrap items-center gap-1.5">
            <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-semibold ${PRIORITY_STYLE[action.priority] || PRIORITY_STYLE.medium}`}>
              {action.priority.toUpperCase()}
            </span>
            <span className="rounded-md bg-[var(--shell-panel-soft)] border border-[var(--shell-border)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
              {CATEGORY_LABEL[action.category] || action.category}
            </span>
            {action.channel && (
              <span className="rounded-md bg-emerald-500/10 border border-emerald-500/20 px-1.5 py-0.5 text-[10px] text-emerald-600">
                {CHANNEL_LABEL[action.channel] || action.channel}
              </span>
            )}
            {action.direction && (
              <span className="rounded-md bg-blue-500/10 border border-blue-500/20 px-1.5 py-0.5 text-[10px] text-blue-600">
                {DIRECTION_LABEL[action.direction] || action.direction}
              </span>
            )}
            {action.customerApprovalRequired && (
              <span className="rounded-md bg-amber-500/10 border border-amber-500/20 px-1.5 py-0.5 text-[10px] text-amber-600">
                Approval needed
              </span>
            )}
          </div>

          {/* Title */}
          <p className="mt-2 text-sm font-medium text-[var(--shell-text)]">{action.title}</p>

          {/* Impact */}
          {action.impact && (
            <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{action.impact}</p>
          )}

          {/* Meta row */}
          <div className="mt-2 flex flex-wrap items-center gap-3 text-[11px] text-[var(--shell-text-muted)]">
            {action.estimatedHours != null && <span>~{action.estimatedHours}h</span>}
            {action.effort && <span>Effort: {EFFORT_LABEL[action.effort] || action.effort}</span>}
            {action.dataSource && <span>Source: {action.dataSource}</span>}
          </div>

          {/* Measurement row */}
          <div className="mt-2 grid grid-cols-2 gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] overflow-hidden sm:grid-cols-4">
            <MeasureCell label="Baseline" value="Pre-measure" />
            <MeasureCell label="vs. Yesterday" value="Awaiting" />
            <MeasureCell label="vs. Last week" value="Awaiting" />
            <MeasureCell label="Target" value={action.expectedMetric || "Mention rate"} highlight />
          </div>
        </div>
      </button>

      {open && hasDetail && (
        <div className="space-y-4 border-t border-[var(--shell-border)] p-4">
          {action.contentBrief && (
            <DetailSection title="Content Brief">
              <p className="text-sm font-medium text-[var(--shell-text)]">{action.contentBrief.workingTitle}</p>
              {action.contentBrief.targetKeywords.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1">
                  {action.contentBrief.targetKeywords.map((k) => (
                    <span key={k} className="rounded-md bg-teal-500/10 px-1.5 py-0.5 text-[10px] text-teal-600">{k}</span>
                  ))}
                </div>
              )}
              {action.contentBrief.outline.length > 0 && (
                <div className="mt-2">
                  <div className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)] mb-1">H2 Structure</div>
                  <ol className="list-inside list-decimal space-y-0.5 text-xs text-[var(--shell-text-muted)]">
                    {action.contentBrief.outline.map((o, i) => <li key={i}>{o}</li>)}
                  </ol>
                </div>
              )}
            </DetailSection>
          )}

          {action.targetQueries && action.targetQueries.length > 0 && (
            <DetailSection title="Target Queries">
              <ul className="list-inside list-disc space-y-0.5 text-xs text-[var(--shell-text-muted)]">
                {action.targetQueries.map((q, i) => <li key={i}>{q}</li>)}
              </ul>
            </DetailSection>
          )}

          {action.steps && action.steps.length > 0 && (
            <DetailSection title="Steps">
              <ol className="list-inside list-decimal space-y-0.5 text-xs text-[var(--shell-text-muted)]">
                {action.steps.map((s, i) => <li key={i}>{s}</li>)}
              </ol>
            </DetailSection>
          )}

          {action.relatedKeywords && action.relatedKeywords.length > 0 && (
            <div className="flex flex-wrap items-center gap-1 border-t border-[var(--shell-border)] pt-3">
              <span className="text-[10px] text-[var(--shell-text-muted)] mr-1">Keywords:</span>
              {action.relatedKeywords.map((k) => (
                <span key={k} className="rounded bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">{k}</span>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function PreviewCard({ preview }: { preview: ActionPreview }) {
  return (
    <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
      <div className="flex items-center justify-between gap-3">
        <span className="text-sm font-medium text-[var(--shell-text)]">
          {preview.sourceActionTitle || "Action Preview"}
        </span>
        <span className="rounded-md bg-[var(--shell-panel-soft)] border border-[var(--shell-border)] px-1.5 py-0.5 text-[10px] text-[var(--shell-text-muted)]">
          {preview.previewType}
        </span>
      </div>
      <div className="mt-3 grid gap-3 sm:grid-cols-2">
        <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-3">
          <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Before</div>
          <p className="text-sm text-[var(--shell-text-muted)]">{preview.beforeSnapshot || "Baseline snapshot"}</p>
        </div>
        <div className="rounded-xl border border-emerald-500/20 bg-emerald-500/5 p-3">
          <div className="mb-1 text-[10px] uppercase tracking-wider text-emerald-600">After</div>
          <p className="text-sm text-[var(--shell-text)]">{preview.afterPreview || "Improved result"}</p>
        </div>
      </div>
      {preview.bestPracticeSample && (
        <p className="mt-2 text-xs text-[var(--shell-text-muted)]">Best practice: {preview.bestPracticeSample}</p>
      )}
    </div>
  );
}

function MeasureCell({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
  return (
    <div className="px-2.5 py-2">
      <div className="text-[10px] text-[var(--shell-text-muted)]">{label}</div>
      <div className={`text-xs font-medium ${highlight ? "text-emerald-600" : "text-[var(--shell-text-muted)]"}`}>{value}</div>
    </div>
  );
}

function DetailSection({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div>
      <div className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)] mb-1.5">{title}</div>
      {children}
    </div>
  );
}

function FilterChip({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
        active
          ? "bg-[var(--shell-accent)]/15 text-[var(--shell-accent)]"
          : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
      }`}
    >
      {label}
    </button>
  );
}
