import { doc, collection } from "firebase/firestore";
import { db } from "../config/firebase";

// Single source of Firestore paths. All other modules must import ref
// factories from here — no Firestore path literals elsewhere. The layout
// follows §4 of docs/FIRESTORE_STRUCTURE_CONSISTENCY_PLAN.md:
//   raw/v1/<kind>/<id>          수집·입력 원본
//   analyses/<key>              해석 (단일 컬렉션 + 고정 doc id)
//   summaries/<key>             화면용 요약 (단일 컬렉션 + 고정 doc id)
//   actions/v1/<kind>/<id>      액션 플랜 네임스페이스
//   insights/{id}, reports/{id}, commands/{id}, runs/{id}, error_journal/{id}

export const paths = {
  users: () => collection(db, "users"),
  user: (uid: string) => doc(db, "users", uid),
  adminUser: (uid: string) => doc(db, "admin_users", uid),

  boards: () => collection(db, "boards"),
  board: (boardId: string) => doc(db, "boards", boardId),

  commands: (boardId: string) => collection(db, "boards", boardId, "commands"),
  command: (boardId: string, cmdId: string) =>
    doc(db, "boards", boardId, "commands", cmdId),

  runs: (boardId: string) => collection(db, "boards", boardId, "runs"),
  run: (boardId: string, runId: string) =>
    doc(db, "boards", boardId, "runs", runId),

  errorJournal: (boardId: string) =>
    collection(db, "boards", boardId, "error_journal"),

  liveEventsStatus: (boardId: string) =>
    doc(db, "boards", boardId, "live_events", "status"),

  // ── raw/v1/<kind>/<id> ─────────────────────────────────
  rawBrandTruth: (boardId: string) =>
    doc(db, "boards", boardId, "raw", "v1", "brand_truth", "default"),
  rawCustomerMaterials: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "customer_materials"),
  rawCustomerMaterial: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "raw", "v1", "customer_materials", id),
  rawCompetitors: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "competitors"),
  rawCompetitor: (boardId: string, slug: string) =>
    doc(db, "boards", boardId, "raw", "v1", "competitors", slug),
  rawCrawlPages: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "crawl_pages"),
  rawCrawlPage: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "raw", "v1", "crawl_pages", id),
  rawExternalSources: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "external_sources"),
  rawExternalSource: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "raw", "v1", "external_sources", id),
  rawGeoProbes: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "geo_probes"),
  rawGeoProbe: (boardId: string, probeId: string) =>
    doc(db, "boards", boardId, "raw", "v1", "geo_probes", probeId),
  rawBenchmarkDaily: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "benchmark_daily"),
  rawBenchmarkDailyDoc: (boardId: string, dateKey: string) =>
    doc(db, "boards", boardId, "raw", "v1", "benchmark_daily", dateKey),
  rawLlmRaw: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "llm_raw"),
  rawLlmRawDoc: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "raw", "v1", "llm_raw", id),

  rawLighthouse: (boardId: string, preset: "desktop" | "mobile") =>
    doc(db, "boards", boardId, "raw", "v1", "lighthouse", preset),

  // Evidence Collector v1 ─────────────────────────────────
  rawSitePolicyRobots: (boardId: string) =>
    doc(db, "boards", boardId, "raw", "v1", "site_policy", "robots"),
  rawLlmGuidanceLlmsTxt: (boardId: string) =>
    doc(db, "boards", boardId, "raw", "v1", "llm_guidance", "llms_txt"),
  rawLlmGuidanceLlmsFullTxt: (boardId: string) =>
    doc(db, "boards", boardId, "raw", "v1", "llm_guidance", "llms_full_txt"),
  rawUrlCandidates: (boardId: string) =>
    collection(db, "boards", boardId, "raw", "v1", "url_candidates"),

  // ── analyses/<key> ─────────────────────────────────────
  // Known keys: brand | seo-audit | geo-visibility | competitor-analysis |
  // external-sources | keyword-strategy | geo-strategy | action-plan | agent-harness |
  // website | ai-search | improvement-plan
  analyses: (boardId: string) => collection(db, "boards", boardId, "analyses"),
  analysis: (boardId: string, key: string) =>
    doc(db, "boards", boardId, "analyses", key),

  // ── summaries/<key> ────────────────────────────────────
  // Known keys (§4): dashboard | site-health | tracking-integrations | brand |
  // competitor-overview | geo-probes | benchmark-latest | engines |
  // keyword-clouds | demand-kpis | content-quality | external-signals |
  // domain-entity | next-actions | brand-gap | probe-sentiments |
  // measurement | measurement-schedule
  summaries: (boardId: string) => collection(db, "boards", boardId, "summaries"),
  summary: (boardId: string, key: string) =>
    doc(db, "boards", boardId, "summaries", key),

  insights: (boardId: string) => collection(db, "boards", boardId, "insights"),
  insight: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "insights", id),

  // ── actions/v1/<kind>/<id> ─────────────────────────────
  actionPlan: (boardId: string) =>
    doc(db, "boards", boardId, "actions", "v1", "plan", "default"),
  actionPreviews: (boardId: string) =>
    collection(db, "boards", boardId, "actions", "v1", "previews"),
  actionPreview: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "actions", "v1", "previews", id),
  actionRuns: (boardId: string) =>
    collection(db, "boards", boardId, "actions", "v1", "runs"),
  actionRun: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "actions", "v1", "runs", id),

  // ── analyses/v3/measurements/<runId> — V3 측정 분석 ──────────
  v3MeasurementAnalyses: (boardId: string) =>
    collection(db, "boards", boardId, "analyses", "v3", "measurements"),
  v3MeasurementAnalysis: (boardId: string, runId: string) =>
    doc(db, "boards", boardId, "analyses", "v3", "measurements", runId),
  v3MeasurementResults: (boardId: string, runId: string) =>
    collection(db, "boards", boardId, "analyses", "v3", "measurements", runId, "results"),

  // ── reports/v3/monthly/<yearMonth> — V3 월간 리포트 ───
  v3MonthlyReports: (boardId: string) =>
    collection(db, "boards", boardId, "reports", "v3", "monthly"),
  v3MonthlyReport: (boardId: string, yearMonth: string) =>
    doc(db, "boards", boardId, "reports", "v3", "monthly", yearMonth),
  // ── reports/v3/weekly/<yearWeek> — V3 주간 리포트 (누적, 예: 2026-W21) ──
  v3WeeklyReports: (boardId: string) =>
    collection(db, "boards", boardId, "reports", "v3", "weekly"),
  v3WeeklyReport: (boardId: string, yearWeek: string) =>
    doc(db, "boards", boardId, "reports", "v3", "weekly", yearWeek),

  // ── actions/v3/<kind>/<id> — V3 Actions 전용 ───────────
  v3Actions: (boardId: string) =>
    collection(db, "boards", boardId, "actions", "v3", "actions"),
  v3Action: (boardId: string, actionId: string) =>
    doc(db, "boards", boardId, "actions", "v3", "actions", actionId),
  v3Recommendations: (boardId: string) =>
    collection(db, "boards", boardId, "actions", "v3", "recommendations"),
  v3Recommendation: (boardId: string, recId: string) =>
    doc(db, "boards", boardId, "actions", "v3", "recommendations", recId),

  reports: (boardId: string) => collection(db, "boards", boardId, "reports"),
  report: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "reports", id),

  alerts: (boardId: string) => collection(db, "boards", boardId, "alerts"),

  snsConnections: (boardId: string) =>
    collection(db, "boards", boardId, "sns_connections"),
  snsConnection: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "sns_connections", id),
  snsDraftRuns: (boardId: string) =>
    collection(db, "boards", boardId, "sns_draft_runs"),
  snsDraftRun: (boardId: string, id: string) =>
    doc(db, "boards", boardId, "sns_draft_runs", id),

  gbpReviews: (boardId: string) =>
    collection(db, "boards", boardId, "gbp_reviews"),

  llmAnswers: (boardId: string) =>
    collection(db, "boards", boardId, "llm_answers"),

  // ── Back-compat aliases (map to §4 target paths) ──────
  /** @deprecated use paths.analysis(boardId, key) */
  document: (boardId: string, key: string) =>
    doc(db, "boards", boardId, "analyses", key),
} as const;

