import { useState } from "react";
import { useAuth } from "../contexts/AuthContext";
import { Code, LogIn } from "lucide-react";

const isDevelopment = import.meta.env.DEV;

export function LoginPage() {
  const { signInWithGoogle, signInWithEmail } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGoogleSignIn = async () => {
    setIsLoading(true);
    setError(null);
    try {
      await signInWithGoogle();
    } catch {
      setError("로그인에 실패했습니다. 다시 시도해주세요.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleDevLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      await signInWithEmail("just.look@jkai.app", "just.look");
    } catch {
      setError("개발 모드 로그인에 실패했습니다.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-[var(--shell-main)] p-4 text-[var(--shell-text)]">
      <div className="w-full max-w-md">
        <div className="shell-panel rounded-[28px] p-8">
          <div className="mb-8 flex flex-col items-center">
            <div className="mb-5 grid h-16 w-16 place-items-center rounded-2xl bg-[linear-gradient(135deg,#5B7CFF_0%,#7D5CFF_100%)] text-3xl font-semibold text-white shadow-[0_16px_32px_rgba(91,124,255,0.28)]">
              G
            </div>
            <h1 className="text-3xl font-semibold tracking-[-0.04em]">GEO Insight</h1>
            <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
              AI 기반 검색 답변 최적화 플랫폼
            </p>
          </div>

          <div className="space-y-4">
            <button
              onClick={handleGoogleSignIn}
              disabled={isLoading}
              className="shell-transition flex w-full items-center justify-center gap-3 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-6 py-4 text-sm font-medium hover:border-[var(--shell-accent)] hover:bg-[var(--shell-accent-soft)] disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isLoading ? (
                <div className="h-5 w-5 rounded-full border-2 border-[var(--shell-accent)] border-t-transparent animate-spin" />
              ) : (
                <>
                  <svg className="h-5 w-5" viewBox="0 0 24 24">
                    <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
                    <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
                    <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
                    <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
                  </svg>
                  <span>Google로 로그인</span>
                </>
              )}
            </button>

            {isDevelopment && (
              <>
                <div className="relative">
                  <div className="absolute inset-0 flex items-center">
                    <div className="w-full border-t border-[var(--shell-border)]" />
                  </div>
                  <div className="relative flex justify-center text-xs">
                    <span className="bg-[var(--shell-panel)] px-3 text-[var(--shell-text-soft)]">개발 모드</span>
                  </div>
                </div>

                <button
                  onClick={handleDevLogin}
                  disabled={isLoading}
                  className="shell-transition flex w-full items-center justify-center gap-3 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] px-6 py-4 text-sm font-medium text-[var(--shell-text-muted)] hover:border-[var(--shell-border-strong)] hover:text-[var(--shell-text)] disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {isLoading ? (
                    <div className="h-5 w-5 rounded-full border-2 border-[var(--shell-text-muted)] border-t-transparent animate-spin" />
                  ) : (
                    <>
                      <Code className="h-5 w-5" />
                      <span>개발용 로그인 (admin@example.com)</span>
                    </>
                  )}
                </button>
              </>
            )}

            {error && (
              <div className="rounded-2xl border border-[var(--shell-danger)]/30 bg-[var(--shell-danger)]/10 px-4 py-3 text-center text-sm text-[var(--shell-danger)]">
                {error}
              </div>
            )}
          </div>

          <div className="mt-8 border-t border-[var(--shell-border)] pt-6">
            <div className="flex items-start gap-2 text-sm text-[var(--shell-text-muted)]">
              <LogIn className="mt-0.5 h-4 w-4 shrink-0" />
              <p>
                로그인하여 검색 쿼리 분석, AI 답변 시뮬레이션, 콘텐츠 최적화 등
                모든 기능을 이용하실 수 있습니다.
              </p>
            </div>
          </div>
        </div>

        <p className="mt-6 text-center text-xs text-[var(--shell-text-soft)]">
          계속 진행하면 서비스 이용약관에 동의하는 것으로 간주됩니다.
        </p>
      </div>
    </div>
  );
}
