import {
  addDoc,
  doc,
  getDocs,
  limit,
  onSnapshot,
  query,
  serverTimestamp,
  updateDoc,
  where,
  type DocumentReference,
  type Unsubscribe,
} from "firebase/firestore";
import { paths } from "./paths";
import { type CommandType, type CommandDoc } from "./collections";

// Cloud Function timeout (540s) + buffer
const STALE_THRESHOLD_MS = 10 * 60 * 1000;

function isStaleDoc(data: Record<string, unknown>): boolean {
  const ts = (data.updatedAt ?? data.createdAt) as
    | { toDate?: () => Date }
    | string
    | undefined;
  if (!ts) return true;
  const date = typeof (ts as { toDate?: () => Date }).toDate === "function"
    ? (ts as { toDate: () => Date }).toDate()
    : new Date(ts as string);
  return Date.now() - date.getTime() > STALE_THRESHOLD_MS;
}

// 진행 중(pending/running)인 같은 type+userId 커맨드가 있으면 그걸 재사용해
// 빠른 더블클릭/네트워크 재시도가 중복 문서를 만들지 않도록 한다.
// Stale 커맨드(10분 이상 변화 없음)는 자동으로 failed 처리 후 새 문서를 생성.
export async function issueCommand(
  boardId: string,
  userId: string,
  type: CommandType,
  params: Record<string, unknown> = {},
): Promise<DocumentReference> {
  const col = paths.commands(boardId);

  for (const status of ["pending", "running"] as const) {
    const q = query(
      col,
      where("userId", "==", userId),
      where("type", "==", type),
      where("status", "==", status),
      limit(1),
    );
    const snap = await getDocs(q);
    if (!snap.empty) {
      const existing = snap.docs[0];
      if (isStaleDoc(existing.data())) {
        await forceFailCommand(boardId, existing.id);
        continue;
      }
      return doc(col, existing.id);
    }
  }

  return addDoc(col, {
    type,
    status: "pending",
    params,
    progress: 0,
    message: "",
    result: null,
    error: null,
    userId,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
  });
}

/**
 * 특정 command + 연결된 run 을 강제로 failed 처리.
 * Operations 에서 stuck 된 run 을 수동 정리하거나,
 * issueCommand 의 stale 자동 만료에서 사용.
 */
export async function forceFailCommand(
  boardId: string,
  cmdId: string,
): Promise<void> {
  const failPatch = {
    status: "failed",
    error: "Force-killed: stuck or stale",
    updatedAt: serverTimestamp(),
  };
  await Promise.all([
    updateDoc(paths.command(boardId, cmdId), failPatch),
    updateDoc(paths.run(boardId, cmdId), failPatch).catch(() => {
      // run 문서가 없을 수 있음
    }),
  ]);
}

export function subscribeCommand(
  boardId: string,
  cmdId: string,
  callback: (cmd: CommandDoc) => void,
): Unsubscribe {
  return onSnapshot(paths.command(boardId, cmdId), (snap) => {
    if (!snap.exists()) return;
    const data = snap.data();
    callback({
      id: snap.id,
      ...data,
      createdAt: data.createdAt?.toDate?.() ?? new Date(),
      updatedAt: data.updatedAt?.toDate?.() ?? new Date(),
    } as CommandDoc);
  });
}
