import {
  getV3Latest,
  getV3Runs,
  getV3BrandTruth,
  getV3Snapshots,
  getV3MeasurementResults,
  getV3Recommendations,
  getV3Actions,
  getV3AiSearchAnalysis,
  getV3ImprovementPlan,
  getV3WeeklyReport,
  getV3Dashboard,
  getV3WebsiteAnalysis,
  getV3Analysis,
  convertV3Recommendation,
  dismissV3Recommendation,
  snoozeV3Recommendation,
} from "../../../db/portalV3";
import type { RunDoc } from "../../../db/collections";
import type { DashboardRawResult, DashboardTrendResult, TrendPoint } from "./types";

export async function fetchExposureRaw(boardId: string) {
  const [latest, runs, brand, snapshots] = await Promise.all([
    getV3Latest(boardId),
    getV3Runs(boardId, 10),
    getV3BrandTruth(boardId),
    getV3Snapshots(boardId),
  ]);
  return { latest, runs: runs.runs, brand, snapshots };
}

export async function fetchDiagnosisRaw(boardId: string) {
  const latest = await getV3Latest(boardId);
  const runId = (latest.run?.id as string) || undefined;
  const [results, runs] = await Promise.all([
    runId
      ? getV3MeasurementResults(boardId, runId)
      : Promise.resolve({ results: [] as Record<string, unknown>[], limit: 0, offset: 0 }),
    getV3Runs(boardId, 10),
  ]);
  return { latest, results: results.results, runs: runs.runs, runId };
}

export async function fetchImprovementRaw(boardId: string) {
  const [recList, aiSearch, plan] = await Promise.all([
    getV3Recommendations(boardId),
    getV3AiSearchAnalysis(boardId),
    getV3ImprovementPlan(boardId),
  ]);
  return {
    recommendations: recList.recommendations,
    groups: recList.groups,
    counts: recList.counts,
    aiSearch,
    plan,
  };
}

export async function fetchTrackingRaw(boardId: string) {
  const [actionList, { runs }, weeklyReport] = await Promise.all([
    getV3Actions(boardId),
    getV3Runs(boardId, 20),
    getV3WeeklyReport(boardId),
  ]);

  const completedRuns = runs
    .filter((r: RunDoc) => r.status === "complete" || r.status === "partial")
    .sort((a: RunDoc, b: RunDoc) => (a.completedAt?.getTime() ?? a.startedAt?.getTime() ?? 0) - (b.completedAt?.getTime() ?? b.startedAt?.getTime() ?? 0));

  const perRunAnalyses: Record<string, Record<string, unknown>> = {};
  const perRunResults: Record<string, Record<string, unknown>[]> = {};

  await Promise.all(
    completedRuns.map(async (run: RunDoc) => {
      const [analysis, { results }] = await Promise.all([
        getV3Analysis(boardId, run.id),
        getV3MeasurementResults(boardId, run.id),
      ]);
      if (analysis) {
        perRunAnalyses[run.id] = analysis as unknown as Record<string, unknown>;
      }
      if (results.length > 0) {
        perRunResults[run.id] = results;
      }
    }),
  );

  return { actions: actionList, completedRuns, weeklyReport, perRunAnalyses, perRunResults };
}

export async function fetchReportRaw(boardId: string) {
  const [exposure, diagnosis, improvement, tracking] = await Promise.all([
    fetchExposureRaw(boardId),
    fetchDiagnosisRaw(boardId),
    fetchImprovementRaw(boardId),
    fetchTrackingRaw(boardId),
  ]);
  return { exposure, diagnosis, improvement, tracking };
}

export async function fetchDashboardRaw(boardId: string): Promise<DashboardRawResult> {
  const [latest, brand, recs, dashboard] = await Promise.all([
    getV3Latest(boardId),
    getV3BrandTruth(boardId),
    getV3Recommendations(boardId),
    getV3Dashboard(boardId),
  ]);
  return { latest, brand, recs, dashboard } as DashboardRawResult;
}

export async function fetchDashboardTrendRaw(boardId: string, count: number = 60): Promise<DashboardTrendResult> {
  const { runs } = await getV3Runs(boardId, count);
  const candidateRuns = runs
    .filter((r: any) => r.status !== "pending")
    .sort((a: any, b: any) => {
      const aTime = a.completedAt || a.startedAt || "";
      const bTime = b.completedAt || b.startedAt || "";
      return new Date(aTime).getTime() - new Date(bTime).getTime();
    });

  const points: TrendPoint[] = [];
  for (const run of candidateRuns) {
    const analysis = await getV3Analysis(boardId, run.id);
    if (!analysis) continue;
    const brandRate = parseFloat(analysis.brandMentionRate as any) || 0;
    const eb = analysis.engineBreakdown || {};
    const gptRate = (eb as any).gpt?.rate || 0;
    const geminiRate = (eb as any).gemini?.rate || 0;
    const engineTotal = Object.values(eb).reduce((sum: number, e: any) => sum + (e?.total || 0), 0);
    const wrdTotal = (analysis as any).weeklyReportData?.globalEngine?.totalQuestions || 0;
    const derivedTotal = (run as any).totalCalls || run.totalItems || engineTotal || wrdTotal || 1;
    points.push({
      date: String(run.completedAt || run.startedAt || ""),
      runId: run.id,
      totalCalls: derivedTotal,
      brandRate,
      gptRate,
      geminiRate,
    });
  }
  return { points };
}

export async function fetchWebsiteRaw(boardId: string) {
  return await getV3WebsiteAnalysis(boardId);
}

export async function fetchRunsRaw(boardId: string, limit: number = 50) {
  return await getV3Runs(boardId, limit);
}

export async function fetchRecommendationsRaw(boardId: string) {
  return await getV3Recommendations(boardId);
}

export { convertV3Recommendation, dismissV3Recommendation, snoozeV3Recommendation };
