import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { AlertTriangle, Globe, Lightbulb, Link2, Newspaper, Shield, Zap } from "lucide-react";
import { getDocument, subscribeBoard, subscribeInsights } from "../../../db/boards";
import type { Board, InsightDoc } from "../../../db/collections";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";
import { OpenInsightsList } from "../../../components/shared/OpenInsightsList";

// ── Types ──────────────────────────────────────────────────

interface ExternalSource {
  sourceType?: string;
  source_type?: string;
  sourceName?: string;
  source_name?: string;
  sourceUrl?: string;
  source_url?: string;
  exists: boolean;
  snippet?: string;
  type?: string;
  name?: string;
  url?: string;
  score?: number;
  summary?: string;
}

interface TrustAnalysis {
  trustScore?: number;
  sources?: ExternalSource[];
  strategies?: Array<{
    title: string;
    description: string;
    impact?: string;
  }>;
  analysis?: {
    trustScore?: number;
    priorityActions?: string[];
  };
  priorityActions?: string[];
}

// ── Helpers ────────────────────────────────────────────────

function getType(s: ExternalSource): string {
  return s.sourceType ?? s.source_type ?? s.type ?? "other";
}

function formatType(type: string): string {
  const map: Record<string, string> = {
    news: "News & Press",
    community: "Community",
    naver_blog: "Naver Blog",
    naver_place: "Naver Place",
    google_maps: "Google Maps",
    wikipedia: "Wikipedia",
    namuwiki: "Namuwiki",
    other: "Other",
  };
  return map[type] ?? type;
}

// ── Component ──────────────────────────────────────────────

export function TrustSignalsInsight() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [trustData, setTrustData] = useState<TrustAnalysis | null>(null);
  const [liveInsights, setLiveInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubIns = subscribeInsights(id, setLiveInsights, { type: "trust_signal" });
    Promise.all([
      getDocument(id, "external-sources-analysis"),
      getDocument(id, "external-analysis"),
    ]).then(([doc1, doc2]) => {
      const data = (doc1?.data ?? doc2?.data ?? null) as TrustAnalysis | null;
      setTrustData(data);
      setLoading(false);
    });
    return () => {
      unsubBoard();
      unsubIns();
    };
  }, [id]);

  // ── Derived: core metrics ──

  const sources = useMemo(() => trustData?.sources ?? [], [trustData]);
  const trustScore = trustData?.trustScore ?? trustData?.analysis?.trustScore ?? Math.min(100, sources.filter((s) => s.exists).length * 15);
  const newsCount = sources.filter((s) => getType(s) === "news" && s.exists).length;
  const communityCount = sources.filter((s) => getType(s) !== "news" && s.exists).length;
  const totalSources = sources.length;

  const groupedSources = useMemo(() => {
    const map = new Map<string, ExternalSource[]>();
    for (const s of sources) {
      const type = getType(s) || "other";
      const list = map.get(type) ?? [];
      list.push(s);
      map.set(type, list);
    }
    return map;
  }, [sources]);

  const socialLinks = board?.siteInfo?.socialLinks ?? {};
  const hasSocialLinks = Object.keys(socialLinks).length > 0;

  // ── Derived: priority actions (from TrustDiagnosis) ──

  const priorityActions = trustData?.priorityActions ?? trustData?.analysis?.priorityActions ?? [];

  // ── Derived: Diagnosis ──

  const diagnosis = useMemo(() => {
    const items: Array<{ severity: "high" | "medium" | "low"; title: string; detail: string }> = [];

    if (sources.length > 0) {
      const missing = sources.filter((s) => !s.exists);
      if (missing.length > sources.length * 0.5) {
        items.push({
          severity: "high",
          title: `${missing.length}/${sources.length} external sources missing`,
          detail: "More than half of tracked external sources could not be found. Focus on establishing presence on key platforms.",
        });
      }
    }

    if (newsCount === 0 && sources.length > 0) {
      items.push({
        severity: "medium",
        title: "No news or press coverage found",
        detail: "AI engines heavily weight news sources for trust. Consider press releases or media outreach.",
      });
    }

    const gbp = board?.siteInfo?.googleBusiness;
    if (gbp && !gbp.found) {
      items.push({
        severity: "medium",
        title: "Google Business Profile not found",
        detail: "A verified Google Business Profile is a key trust signal for local search and AI engines.",
      });
    }

    if (!hasSocialLinks) {
      items.push({
        severity: "low",
        title: "No social profiles detected on website",
        detail: "Linking social profiles helps AI engines verify entity identity and build trust.",
      });
    }

    if (sources.length === 0) {
      items.push({
        severity: "medium",
        title: "No external source data available",
        detail: "Run an external analysis to discover trust signals across news, communities, and directories.",
      });
    }

    return items;
  }, [sources, newsCount, board, hasSocialLinks]);

  // ── Derived: Generated Insights ──

  const insights = useMemo(() => {
    const result: Array<{ severity: "high" | "medium" | "low"; title: string; explanation: string }> = [];

    if (trustScore < 30 && sources.length > 0) {
      result.push({
        severity: "high",
        title: "Very low trust score",
        explanation: `Trust score is ${trustScore}/100. External trust signals are critical for AI engine recommendations.`,
      });
    }

    const typeGroups = new Map<string, number>();
    for (const s of sources) {
      const t = getType(s);
      if (s.exists) typeGroups.set(t, (typeGroups.get(t) ?? 0) + 1);
    }
    if (typeGroups.size === 1) {
      result.push({
        severity: "medium",
        title: "Trust signals concentrated in one channel",
        explanation: `All external presence is in "${formatType([...typeGroups.keys()][0])}". Diversify across news, communities, and directories.`,
      });
    }

    if (gbpScore(board) > 0 && gbpScore(board) < 50) {
      result.push({
        severity: "medium",
        title: "Google Business Profile needs improvement",
        explanation: `GBP diagnosis score is ${gbpScore(board)}/100. Complete your profile with photos, hours, and respond to reviews.`,
      });
    }

    return result;
  }, [trustScore, sources, board]);

  // ── Derived: Data Quality ──

  const dataQuality = useMemo(() => {
    const hasSources = sources.length > 0;
    const hasBoard = !!board;
    const hasStrategies = (trustData?.strategies ?? []).length > 0;
    const count = [hasSources, hasBoard, hasStrategies].filter(Boolean).length;
    const score = Math.round((count / 3) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes: string[] = [];
    if (!hasSources) notes.push("No external source analysis available");
    if (!hasBoard) notes.push("Board data not loaded");
    if (!hasStrategies) notes.push("No improvement strategies generated");
    return { score, status, notes };
  }, [sources, board, trustData]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Summary Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Shield} label="Trust Score" value={String(trustScore)} color="text-blue-600" />
        <MetricCard icon={Newspaper} label="News Mentions" value={String(newsCount)} color="text-teal-600" />
        <MetricCard icon={Globe} label="Community Presence" value={String(communityCount)} color="text-emerald-600" />
        <MetricCard icon={Link2} label="Total Sources" value={String(totalSources)} color="text-cyan-600" />
      </div>

      {/* Data Quality */}
      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {/* Raw Data: Improvement Strategies */}
      {trustData?.strategies && trustData.strategies.length > 0 && (
        <InsightSection title="Improvement Strategies" icon={Zap} count={trustData.strategies.length} defaultOpen>
          <div className="grid gap-3 sm:grid-cols-3">
            {trustData.strategies.slice(0, 3).map((s, i) => (
              <div key={i} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
                <p className="text-sm font-medium text-[var(--shell-text)]">{s.title}</p>
                <p className="mt-1.5 text-xs leading-relaxed text-[var(--shell-text-muted)]">{s.description}</p>
                {s.impact && (
                  <p className="mt-2 text-[11px] font-medium text-emerald-600">Impact: {s.impact}</p>
                )}
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {/* Raw Data: External Source Map */}
      <InsightSection title="External Source Map" icon={Globe} count={sources.length} defaultOpen={groupedSources.size > 0}>
        {groupedSources.size > 0 ? (
          <div className="space-y-5">
            {Array.from(groupedSources.entries()).map(([type, items]) => (
              <div key={type}>
                <div className="mb-2 flex items-center gap-2">
                  <span className="text-xs font-semibold capitalize text-[var(--shell-text)]">{formatType(type)}</span>
                  <span className="text-[10px] text-[var(--shell-text-muted)]">({items.length})</span>
                </div>
                <div className="grid gap-2 sm:grid-cols-2">
                  {items.slice(0, 6).map((source, i) => (
                    <SourceCard key={`${type}-${i}`} source={source} />
                  ))}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <EmptyState
            icon={Shield}
            title="No external trust data"
            description="분석을 실행하면 뉴스, 커뮤니티 등 외부 신뢰 신호를 발굴합니다"
          />
        )}
      </InsightSection>

      {/* Raw Data: Social Profiles */}
      {hasSocialLinks && (
        <InsightSection title="Connected Social Profiles" icon={Link2} count={Object.keys(socialLinks).length} defaultOpen>
          <div className="flex flex-wrap gap-2">
            {Object.entries(socialLinks).map(([platform, url]) => (
              <a
                key={platform}
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)]"
              >
                <Link2 className="h-3 w-3" />
                {platform}
              </a>
            ))}
          </div>
        </InsightSection>
      )}

      {/* Diagnosis (merged from TrustDiagnosis) */}
      <InsightSection title="Diagnosis" icon={AlertTriangle} count={diagnosis.length} defaultOpen={diagnosis.length > 0}>
        {diagnosis.length > 0 ? (
          <div className="space-y-2">
            {diagnosis.map((item, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={item.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No diagnostic issues found</p>
        )}
      </InsightSection>

      {/* Open Insights (from insights collection) */}
      <InsightSection
        title="Open Insights"
        icon={Lightbulb}
        count={liveInsights.filter((i) => i.status !== "resolved" && i.status !== "ignored").length}
        defaultOpen
      >
        <OpenInsightsList insights={liveInsights} />
      </InsightSection>

      {/* Generated Insights (legacy) */}
      <InsightSection title="Generated Insights (legacy)" icon={Lightbulb} count={insights.length} defaultOpen={false}>
        {insights.length > 0 ? (
          <div className="space-y-2">
            {insights.map((insight, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={insight.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{insight.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{insight.explanation}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No insights generated yet. External source data will produce insights here.</p>
        )}
      </InsightSection>

      {/* Suggested Actions (priority actions from analysis) */}
      <InsightSection title="Suggested Actions" icon={Zap} count={priorityActions.length} defaultOpen={false}>
        {priorityActions.length > 0 ? (
          <div className="space-y-2">
            {priorityActions.map((action, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <Zap className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[var(--shell-accent)]" />
                <p className="text-sm text-[var(--shell-text)]">{action}</p>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">Run an analysis to generate trust signal improvement actions</p>
        )}
      </InsightSection>
    </div>
  );
}

// ── Sub-components ──────────────────────────────────────────

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}

function SourceCard({ source }: { source: ExternalSource }) {
  const name = source.sourceName ?? source.source_name ?? source.name ?? "Source";
  const url = source.sourceUrl ?? source.source_url ?? source.url ?? "";

  return (
    <div className="flex items-start justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium text-[var(--shell-text)]">{name}</p>
        {url && <p className="mt-0.5 truncate text-xs text-[var(--shell-text-muted)]">{url}</p>}
        {source.snippet && <p className="mt-1 line-clamp-2 text-xs text-[var(--shell-text-muted)]">{source.snippet}</p>}
        {source.summary && <p className="mt-1 line-clamp-2 text-xs text-[var(--shell-text-muted)]">{source.summary}</p>}
      </div>
      <div className="ml-2 shrink-0">
        {source.score != null ? (
          <span className={`text-xs font-medium ${source.score >= 7 ? "text-emerald-600" : source.score >= 4 ? "text-amber-500" : "text-rose-500"}`}>
            {source.score}/10
          </span>
        ) : (
          <span className={`rounded-full px-2 py-0.5 text-[10px] font-medium ${
            source.exists ? "bg-emerald-500/10 text-emerald-600" : "bg-rose-500/10 text-rose-500"
          }`}>
            {source.exists ? "Found" : "Missing"}
          </span>
        )}
      </div>
    </div>
  );
}

function gbpScore(board: Board | null): number {
  return board?.gbpDiagnosis?.score ?? 0;
}
