import { Navigate, useLocation } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import { LoginPage } from "../components/LoginPage";

export function Login() {
  const { user, loading } = useAuth();
  const location = useLocation();
  const from = (location.state as { from?: string })?.from || "/";

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[var(--shell-main)] text-[var(--shell-text-muted)]">
        <div className="h-6 w-6 rounded-full border-2 border-[var(--shell-accent)] border-t-transparent animate-spin" />
      </div>
    );
  }
  if (user) return <Navigate to={from} replace />;
  return <LoginPage />;
}
