// Shared typed utilities for Portal V4 pages

export function num(v: unknown): number {
  const n = parseFloat(v as string);
  return isNaN(n) ? 0 : n;
}

export function pct1(v: unknown): string {
  return `${num(v).toFixed(1)}%`;
}

export function round(v: unknown): number {
  return Math.round(num(v));
}

export interface CatInfo {
  label: string;
  cls: string;
}

export const CAT: Record<string, CatInfo> = {
  DISCOVER: { label: "탐색", cls: "border border-sky-400/40 bg-sky-500/15 text-sky-300 shell-badge-sky" },
  CONSIDER: { label: "비교·검토", cls: "border border-amber-400/40 bg-amber-500/15 text-amber-300 shell-badge-amber" },
  DECIDE: { label: "선택", cls: "border border-emerald-400/40 bg-emerald-500/15 text-emerald-300 shell-badge-emerald" },
  ADVOCATE: { label: "추천·확산", cls: "border border-fuchsia-400/40 bg-fuchsia-500/15 text-fuchsia-300 shell-badge-fuchsia" },
};

export function catOf(item: Record<string, unknown> | null | undefined, brand: Record<string, unknown> | null | undefined): CatInfo {
  const raw = String(
    item?.category || (brand?.queryCategories as Record<string, string> | undefined)?.[item?.queryText as string] || ""
  ).trim();
  const up = raw.toUpperCase();
  if (CAT[up]) return CAT[up];
  if (/탐색|discover/i.test(raw)) return CAT.DISCOVER;
  if (/비교|검토|consider/i.test(raw)) return CAT.CONSIDER;
  if (/선택|결정|decide/i.test(raw)) return CAT.DECIDE;
  if (/추천|확산|advocate/i.test(raw)) return CAT.ADVOCATE;
  return { label: raw || "일반", cls: "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]" };
}

export const REC_CAT_LABEL: Record<string, string> = {
  technical: "기술 구조",
  content: "콘텐츠",
  common: "공통",
  marketing: "마케팅",
  other: "기타",
};

export function quickWin(r: { impactScore?: unknown; expectedDelta?: unknown; effortScore?: unknown }): number {
  return (num(r.impactScore) * 2) + (Math.max(0, num(r.expectedDelta)) * 0.6) + ((5 - num(r.effortScore)) * 0.8);
}
