import { paths, SUMMARY_KEYS, ANALYSIS_KEYS } from "./paths";
import type { RunDoc } from "./collections";
import type {
  V3Analysis,
  V3Schedule,
  V3Action,
  V3ActionList,
  V3Recommendation,
  V3RecList,
  V3MonthlyReport,
  BrandTruth,
  DashboardData,
  TrendSnapshot,
  WeeklyTrendReport,
  WebsiteAnalysis,
  AiSearchAnalysisData,
  ImprovementPlanData,
} from "../pages/portalV3/dataHub/types";

function asArray<T>(v: unknown): T[] {
  return Array.isArray(v) ? (v as T[]) : [];
}

function asRecord(v: unknown): Record<string, unknown> {
  return v && typeof v === "object" ? (v as Record<string, unknown>) : {};
}

// ── Dashboard ─────────────────────────────────────────────────────

export async function getV3Dashboard(boardId: string): Promise<DashboardData | null> {
  const [summarySnap, brandSnap] = await Promise.all([
    getDoc(paths.summary(boardId, SUMMARY_KEYS.dashboard)),
    getDoc(paths.rawBrandTruth(boardId)),
  ]);
  if (!summarySnap.exists() && !brandSnap.exists()) return null;

  const raw = summarySnap.exists() ? (summarySnap.data() as Record<string, unknown>) : {};
  const brand = brandSnap.exists() ? (brandSnap.data() as Record<string, unknown>) : null;

  // The dashboard aggregator writes flat top-level fields (genericEngine, siteHealth, etc.),
  // but the frontend reads them via data.executiveSummary.* wrapper.
  // Build executiveSummary from flat fields when the aggregator hasn't produced a nested version.
  const execFromServer = raw.executiveSummary as Record<string, unknown> | undefined;
  const genericEngine = asRecord(execFromServer?.genericEngine ?? raw.genericEngine);
  const sampleCount = (genericEngine.engineBreakdown as unknown[] || [])
    .reduce((s: number, e: any) => s + Number(e?.totalQuestions ?? 0), 0);

  const cadence = brand ? asRecord(brand.measurementCadence) : {};

  const executiveSummary = execFromServer ?? {
    siteHealth: raw.siteHealth ?? undefined,
    genericEngine: {
      ...genericEngine,
      hasMentionData: Number(genericEngine.mentionRate ?? 0) > 0 || sampleCount > 0,
      hasExposureData: Number(genericEngine.exposureRate ?? 0) > 0,
      source: "v1-probe",
      sampleCount,
      totalQuestions: sampleCount,
      lastMeasuredAt: null,
      measurement: {
        configured: !!cadence.frequency,
        status: sampleCount > 0 ? "active" : "waiting_first_run",
        frequency: cadence.frequency ?? null,
        runAt: cadence.runAt ?? null,
        lastRunAt: null,
      },
    },
    keywordClouds: raw.keywordClouds ?? undefined,
    externalSignals: raw.externalSignals ?? undefined,
    nextActions: raw.nextActions ?? undefined,
  };

  return {
    onboarding: (raw.onboarding as DashboardData["onboarding"]) ?? { id: boardId, url: "", domain: "", status: "unknown" },
    company: brand
      ? { name: String(brand.canonicalName ?? ""), status: "active", issuePrefix: String(brand.primaryCategory ?? "").slice(0, 3).toUpperCase() || "GEO" }
      : null,
    classifiedKeywords: raw.classifiedKeywords ?? undefined,
    documents: raw.documents ?? undefined,
    executiveSummary,
    activity: asArray(raw.activity),
    naverKeywords: raw.naverKeywords ?? undefined,
    issues: asArray(raw.issues),
    rawKeywords: asArray<string>(raw.rawKeywords),
  } as DashboardData;
}

// ── Brand Truth ───────────────────────────────────────────────────

export async function getV3BrandTruth(boardId: string): Promise<BrandTruth | null> {
  const snap = await getDoc(paths.rawBrandTruth(boardId));
  if (!snap.exists()) return null;
  return snap.data() as BrandTruth;
}

export async function saveV3BrandTruth(boardId: string, data: Partial<BrandTruth>): Promise<void> {
  await setDoc(paths.rawBrandTruth(boardId), { ...data, updatedAt: serverTimestamp() }, { merge: true });
}

// ── Trend Snapshots ───────────────────────────────────────────────

export async function getV3Snapshots(boardId: string): Promise<TrendSnapshot[]> {
  const snap = await getDocs(
    query(paths.rawBenchmarkDaily(boardId), orderBy("capturedAt", "desc")),
  );
  return snap.docs.map((d) => {
    const raw = d.data() as Record<string, unknown>;
    const metrics = asRecord(raw.metrics);

    // geoProbe writes flat fields; snapshot worker writes nested metrics block.
    const mentionRate = Number(metrics.mentionRate ?? raw.mentionRate ?? 0);
    const exposureRate = Number(metrics.exposureRate ?? raw.recommendedRate ?? raw.exposureRate ?? 0);
    const totalQuestions = Number(metrics.totalQuestions ?? raw.totalSamples ?? 0);

    // byEngine (geoProbe flat) → engineBreakdown array
    let engineBreakdown = asArray(raw.engineBreakdown);
    if (engineBreakdown.length === 0 && raw.byEngine && typeof raw.byEngine === "object") {
      engineBreakdown = Object.entries(raw.byEngine as Record<string, Record<string, unknown>>).map(
        ([engine, vals]) => ({
          engine,
          totalQuestions: Number(vals.samples ?? 0),
          exposedCount: 0,
          mentionedCount: Number(vals.mentions ?? 0),
          exposureRate: 0,
          mentionRate: Number(vals.mentionRate ?? 0),
          mentionCount: Number(vals.mentions ?? 0),
        }),
      );
    }

    return {
      id: d.id,
      runId: raw.runId ? String(raw.runId) : undefined,
      onboardingId: String(raw.onboardingId ?? boardId),
      capturedAt: String(raw.date ?? raw.capturedAt ?? ""),
      metrics: {
        mentionRate,
        exposureRate,
        weightedMentionRate: Number(metrics.weightedMentionRate ?? mentionRate),
        visibilityScore: Number(metrics.visibilityScore ?? mentionRate),
        totalQuestions,
        mentionCount: Number(metrics.mentionCount ?? Math.round(totalQuestions * mentionRate / 100)),
      },
      engineBreakdown,
      mentionRate,
      exposureRate,
      geoScore: Number(raw.geoScore ?? metrics.geoScore ?? 0),
      websiteScore: Number(raw.websiteScore ?? 0),
      externalScore: Number(raw.externalScore ?? 0),
      enginesMeasured: asArray<string>(raw.enginesMeasured).length > 0
        ? asArray<string>(raw.enginesMeasured)
        : engineBreakdown.map((e: any) => String(e.engine)),
      sampleCount: Number(raw.sampleCount ?? totalQuestions),
    } as TrendSnapshot;
  });
}

// ── Weekly Report — reports/v3/weekly/{yearWeek} (누적, 최신 1건 조회) ──

export async function getV3WeeklyReport(boardId: string): Promise<WeeklyTrendReport | null> {
  const q = query(
    paths.v3WeeklyReports(boardId),
    orderBy("periodEnd", "desc"),
    fbLimit(1),
  );
  const snaps = await getDocs(q);
  if (snaps.empty) return null;
  const snap = snaps.docs[0];
  const raw = snap.data() as Record<string, unknown>;
  const summary = asRecord(raw.summary);
  const weeklyChange = asRecord(raw.weeklyChange);
  const globalEngine = asRecord(raw.globalEngine);
  return {
    id: snap.id,
    onboardingId: String(raw.onboardingId ?? boardId),
    generatedAt: String(raw.generatedAt ?? ""),
    periodStart: String(raw.periodStart ?? ""),
    periodEnd: String(raw.periodEnd ?? ""),
    summary: {
      headline: String(summary.headline ?? ""),
      overview: asArray<string>(summary.overview),
    },
    weeklyChange: {
      mentionRateDelta: Number(weeklyChange.mentionRateDelta ?? 0),
      exposureRateDelta: Number(weeklyChange.exposureRateDelta ?? 0),
      weightedMentionRateDelta: Number(weeklyChange.weightedMentionRateDelta ?? 0),
      mentionCountDelta: Number(weeklyChange.mentionCountDelta ?? 0),
    },
    globalEngine: (() => {
      const engines = asArray<Record<string, any>>(globalEngine.engines);
      const totalQuestions = engines.reduce((s, e) => s + (Number(e.totalQuestions) || 0), 0);
      const mentionCount = engines.reduce((s, e) => s + (Number(e.mentionedCount) || 0), 0);
      const mentionRate = totalQuestions > 0 ? (mentionCount / totalQuestions) * 100 : 0;
      const exposureRate = engines.length > 0
        ? engines.reduce((s, e) => s + (Number(e.exposureRate) || 0), 0) / engines.length
        : 0;
      return {
        mentionRate: Number(globalEngine.mentionRate) || +mentionRate.toFixed(2),
        exposureRate: Number(globalEngine.exposureRate) || +exposureRate.toFixed(2),
        totalQuestions: Number(globalEngine.totalQuestions) || totalQuestions,
        mentionCount: Number(globalEngine.mentionCount) || mentionCount,
        engines,
      };
    })(),
    competitors: asArray(raw.competitors),
    actions: asArray(raw.executedActions),
    sentimentBreakdown: raw.sentimentBreakdown as WeeklyTrendReport["sentimentBreakdown"],
  } as WeeklyTrendReport;
}

// ── Website Analysis — analyses/website ──────────────────────────

export async function getV3WebsiteAnalysis(boardId: string): Promise<WebsiteAnalysis | null> {
  const [analysisSnap, dSnap, mSnap, healthSnap, seoAuditSnap] = await Promise.all([
    getDoc(paths.analysis(boardId, ANALYSIS_KEYS.website)),
    getDoc(paths.rawLighthouse(boardId, "desktop")),
    getDoc(paths.rawLighthouse(boardId, "mobile")),
    getDoc(paths.summary(boardId, SUMMARY_KEYS.siteHealth)),
    getDoc(paths.analysis(boardId, ANALYSIS_KEYS.seoAudit)),
  ]);

  const base = analysisSnap.exists() ? (analysisSnap.data() as WebsiteAnalysis) : null;
  const hasRawLh = dSnap.exists() || mSnap.exists();
  const hasHealth = healthSnap.exists();
  const hasSeoAudit = seoAuditSnap.exists();

  if (!base && !hasRawLh && !hasHealth && !hasSeoAudit) return null;

  const result: WebsiteAnalysis = base ? { ...base } : ({} as WebsiteAnalysis);

  const dScores: Record<string, number | null> = dSnap.exists() ? (dSnap.data() as any).scores ?? {} : {};
  const mScores: Record<string, number | null> = mSnap.exists() ? (mSnap.data() as any).scores ?? {} : {};

  // -- Lighthouse categories from raw/v1/lighthouse/{preset} --
  if (!result.lighthouse?.categories?.length && hasRawLh) {
    const CATEGORY_META: Record<string, { label: string; description: string }> = {
      performance: { label: "Performance", description: "페이지 로딩 속도 및 인터랙션 반응성" },
      accessibility: { label: "Accessibility", description: "접근성 표준 준수 수준" },
      "best-practices": { label: "Best Practices", description: "웹 표준 및 보안 모범 사례" },
      seo: { label: "SEO", description: "검색엔진 최적화 기본 요소" },
    };
    const toLhStatus = (v: number | null | undefined) => {
      if (v == null) return "unknown";
      const s = Math.round(v * 100);
      if (s >= 90) return "good";
      if (s >= 50) return "average";
      return "poor";
    };

    const allKeys = [...new Set([...Object.keys(dScores), ...Object.keys(mScores)])];
    result.lighthouse = {
      categories: allKeys
        .filter((k) => CATEGORY_META[k])
        .map((k) => ({
          id: k,
          label: CATEGORY_META[k].label,
          description: CATEGORY_META[k].description,
          desktop: { score: dScores[k] != null ? Math.round(dScores[k]! * 100) : null, status: toLhStatus(dScores[k]) },
          mobile: { score: mScores[k] != null ? Math.round(mScores[k]! * 100) : null, status: toLhStatus(mScores[k]) },
        })),
    };
  }

  // -- Core Web Vitals from summaries/site-health (CrUX) --
  if (!result.coreWebVitals?.metrics?.length && hasHealth) {
    const h = (healthSnap.data() as any).data ?? healthSnap.data();
    result.coreWebVitals = buildCoreWebVitals(h);
  }

  // -- Verdict from Lighthouse scores + seo-audit --
  if (!result.verdict?.headline) {
    result.verdict = buildVerdict(mScores, dScores, hasSeoAudit ? seoAuditSnap.data() as any : null, base as any);
  }

  // -- SEO / GEO analysis cards from seo-audit --
  if (hasSeoAudit) {
    const audit = seoAuditSnap.data() as any;
    if (!result.seoAnalysis && audit.seoScore != null) {
      result.seoAnalysis = buildSeoAnalysisCard(audit);
    }
    if (!result.geoAnalysis && audit.geoScore != null) {
      result.geoAnalysis = buildGeoAnalysisCard(audit);
    }
    if (!result.pageScores?.length && audit.pageScores?.length) {
      result.pageScores = audit.pageScores;
    }
  }

  // -- Priority Fixes from analyses/website.priorityActions --
  if (!result.priorityFixes?.length) {
    const actions = asArray<Record<string, unknown>>((base as any)?.priorityActions);
    if (actions.length) {
      result.priorityFixes = buildPriorityFixes(actions);
    }
  }

  return result;
}

function buildCoreWebVitals(health: Record<string, unknown>) {
  const cwvStatus = (v: number, good: number, poor: number) => {
    if (v <= good) return "good";
    if (v <= poor) return "needs-improvement";
    return "poor";
  };

  const parseNum = (raw: unknown): number | null => {
    if (raw == null) return null;
    if (typeof raw === "number") return raw;
    const s = String(raw).replace(/[^\d.]/g, "");
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const lcp = parseNum(health.lcp);
  const inp = parseNum(health.inp);
  const cls = parseNum(health.cls);

  const lcpUnit = typeof health.lcp === "string" && health.lcp.includes("ms") ? "ms" : "s";
  const lcpSec = lcp != null ? (lcpUnit === "ms" ? lcp / 1000 : lcp) : null;
  const inpMs = inp;
  const clsVal = cls;

  type Metric = {
    id: string; label: string; fullName: string; description: string;
    unit: string; target: number; targetLabel: string; rankingFactor: boolean;
    mobile: { value: number | null; status: string }; desktop: { value: number | null; status: string };
  };
  const metrics: Metric[] = [];

  if (lcpSec != null) {
    metrics.push({
      id: "lcp", label: "LCP", fullName: "Largest Contentful Paint",
      description: "가장 큰 콘텐츠가 표시되기까지의 시간",
      unit: "s", target: 2.5, targetLabel: "\u2264 2.5s", rankingFactor: true,
      mobile: { value: +lcpSec.toFixed(2), status: cwvStatus(lcpSec, 2.5, 4.0) },
      desktop: { value: null, status: "unknown" },
    });
  }
  if (inpMs != null) {
    metrics.push({
      id: "inp", label: "INP", fullName: "Interaction to Next Paint",
      description: "사용자 입력에 대한 응답 지연",
      unit: "ms", target: 200, targetLabel: "\u2264 200ms", rankingFactor: true,
      mobile: { value: Math.round(inpMs), status: cwvStatus(inpMs, 200, 500) },
      desktop: { value: null, status: "unknown" },
    });
  }
  if (clsVal != null) {
    metrics.push({
      id: "cls", label: "CLS", fullName: "Cumulative Layout Shift",
      description: "예기치 않은 레이아웃 이동 누적값",
      unit: "", target: 0.1, targetLabel: "\u2264 0.1", rankingFactor: true,
      mobile: { value: +clsVal.toFixed(2), status: cwvStatus(clsVal, 0.1, 0.25) },
      desktop: { value: null, status: "unknown" },
    });
  }

  return { metrics };
}

function buildVerdict(
  mScores: Record<string, number | null>,
  dScores: Record<string, number | null>,
  seoAudit: Record<string, unknown> | null,
  analysis: Record<string, unknown> | null,
) {
  const avg = (scores: Record<string, number | null>) => {
    const vals = Object.values(scores).filter((v): v is number => v != null);
    if (!vals.length) return null;
    return Math.round(vals.reduce((a, b) => a + b * 100, 0) / vals.length);
  };
  const mobileOverall = avg(mScores);
  const desktopOverall = avg(dScores);

  const seoScore = seoAudit?.seoScore as number | undefined;
  const geoScore = seoAudit?.geoScore as number | undefined;
  const pagesAnalyzed = seoAudit?.pagesAnalyzed as number | undefined;

  const parts: string[] = [];
  if (seoScore != null) parts.push(`SEO ${Math.round(seoScore)}점`);
  if (geoScore != null) parts.push(`GEO ${Math.round(geoScore)}점`);
  if (mobileOverall != null && desktopOverall != null && Math.abs(mobileOverall - desktopOverall) >= 10) {
    parts.push(`Mobile/Desktop ${Math.abs(mobileOverall - desktopOverall)}점 격차`);
  }

  const headline = (analysis?.overallGrade as string)
    || (analysis?.summary as string)?.slice(0, 60)
    || (parts.length ? parts.join(" / ") : "웹사이트 분석 완료");

  const subline = (analysis?.summary as string)
    || [
        seoScore != null ? `SEO ${Math.round(seoScore)}점` : null,
        geoScore != null ? `GEO ${Math.round(geoScore)}점` : null,
        mobileOverall != null ? `Mobile 종합 ${mobileOverall}점` : null,
        desktopOverall != null ? `Desktop 종합 ${desktopOverall}점` : null,
      ].filter(Boolean).join(" · ") || "";

  const anomalies: { severity: string; message: string }[] = [];
  if (mobileOverall != null && desktopOverall != null) {
    const gap = Math.abs(mobileOverall - desktopOverall);
    if (gap >= 10) {
      const lower = mobileOverall < desktopOverall ? "모바일" : "데스크톱";
      anomalies.push({ severity: "warning", message: `${lower} 성능이 ${gap}점 낮음 — 디바이스별 최적화 점검 필요` });
    }
  }
  if (geoScore != null && geoScore < 50) {
    anomalies.push({ severity: "critical", message: `GEO ${Math.round(geoScore)}점 — AI 답변 엔진 노출에 핵심 항목 보강 필요` });
  }

  const writtenAt = (analysis?.writtenAt as any)?.toDate?.()?.toISOString?.()
    || (seoAudit?.createdAt as any)?.toDate?.()?.toISOString?.();

  return {
    headline,
    subline,
    devices: {
      mobile: { overall: mobileOverall },
      desktop: { overall: desktopOverall },
    },
    pagesAnalyzed: pagesAnalyzed ?? null,
    measuredAt: writtenAt ?? new Date().toISOString(),
    anomalies,
  };
}

function buildSeoAnalysisCard(audit: Record<string, unknown>) {
  const score = Math.round(Number(audit.seoScore ?? 0));
  const statusOf = (n: number) => n >= 90 ? "good" : n >= 50 ? "needs-improvement" : "poor";
  const checks = asArray<Record<string, unknown>>(audit.checks);
  const recs = asArray<Record<string, unknown>>(audit.recommendations);
  const passCount = checks.filter((c) => c.status === "pass").length;
  const warnCount = checks.filter((c) => c.status === "warning").length;
  const failCount = checks.filter((c) => c.status === "fail" || c.status === "error").length;

  return {
    score,
    status: statusOf(score),
    summary: String(audit.body ?? ""),
    standpoint: "Google / Naver 검색 엔진 노출",
    passCount,
    warnCount,
    failCount,
    topInsights: recs.slice(0, 5).map((r, i) => ({
      rank: i + 1,
      type: r.priority === "high" ? "critical" : r.priority === "low" ? "opportunity" : "issue",
      title: String(r.label ?? ""),
      detail: String(r.description ?? ""),
    })),
    checks: checks.map((c) => ({
      id: String(c.checkId ?? c.ruleId ?? ""),
      label: String(c.title ?? c.label ?? ""),
      status: String(c.status ?? "pass"),
      message: String(c.message ?? c.detail ?? ""),
      impact: String(c.impact ?? "medium"),
    })),
  };
}

function buildGeoAnalysisCard(audit: Record<string, unknown>) {
  const score = Math.round(Number(audit.geoScore ?? 0));
  const statusOf = (n: number) => n >= 90 ? "good" : n >= 50 ? "needs-improvement" : "poor";
  const siteChecks = asRecord(audit.siteChecks);
  const recs = asArray<Record<string, unknown>>(audit.recommendations)
    .filter((r) => String(r.category ?? "").toLowerCase().includes("geo"));

  const geoChecks: { id: string; label: string; status: string; message: string; impact: string }[] = [];
  if (siteChecks.hasLlmsTxt != null) {
    geoChecks.push({ id: "llms-txt", label: "llms.txt 파일", status: siteChecks.hasLlmsTxt ? "pass" : "fail", message: siteChecks.hasLlmsTxt ? "llms.txt 정상 설정" : "AI 크롤러 안내 표준 파일 미설정", impact: "high" });
  }
  if (siteChecks.hasRobotsTxt != null) {
    geoChecks.push({ id: "robots-txt", label: "robots.txt", status: siteChecks.hasRobotsTxt ? "pass" : "fail", message: siteChecks.hasRobotsTxt ? "robots.txt 정상" : "robots.txt 미설정", impact: "high" });
  }
  if (siteChecks.hasSitemap != null) {
    geoChecks.push({ id: "sitemap", label: "sitemap.xml", status: siteChecks.hasSitemap ? "pass" : "warning", message: siteChecks.hasSitemap ? "sitemap 정상" : "sitemap 미설정", impact: "medium" });
  }
  if (siteChecks.hasFeed != null) {
    geoChecks.push({ id: "feed", label: "RSS/Atom 피드", status: siteChecks.hasFeed ? "pass" : "warning", message: siteChecks.hasFeed ? "피드 정상" : "피드 미설정", impact: "low" });
  }
  const passCount = geoChecks.filter((c) => c.status === "pass").length;
  const warnCount = geoChecks.filter((c) => c.status === "warning").length;
  const failCount = geoChecks.filter((c) => c.status === "fail").length;

  return {
    score,
    status: statusOf(score),
    summary: score < 50
      ? "AI 답변 엔진 노출에 필요한 핵심 항목 보강이 필요합니다."
      : score < 80
        ? "GEO 기본 요소는 갖추었으나 추가 최적화 여지가 있습니다."
        : "GEO 최적화가 잘 되어 있습니다.",
    standpoint: "ChatGPT / Claude / Gemini AI 답변 노출",
    passCount,
    warnCount,
    failCount,
    topInsights: recs.slice(0, 5).map((r, i) => ({
      rank: i + 1,
      type: r.priority === "high" ? "critical" : "issue",
      title: String(r.label ?? ""),
      detail: String(r.description ?? ""),
    })),
    checks: geoChecks,
  };
}

function buildPriorityFixes(actions: Record<string, unknown>[]) {
  const priorityToImpact: Record<string, string> = { P0: "high", P1: "high", P2: "medium", P3: "low" };
  const categoryMap: Record<string, string> = { technical: "Performance", content: "SEO", common: "GEO" };

  return actions.map((a, i) => {
    const priority = String(a.priority ?? "P1");
    const category = String(a.category ?? "common");
    const impact = priorityToImpact[priority] ?? "medium";
    const deltaMatch = String(a.estimatedImpact ?? "").match(/\+?(\d+)/);
    const expectedDelta = deltaMatch ? Number(deltaMatch[1]) : 0;

    return {
      id: `fix-${i + 1}`,
      rank: i + 1,
      title: String(a.title ?? ""),
      category: categoryMap[category] ?? category.toUpperCase(),
      impact,
      effort: priority === "P0" || priority === "P1" ? "low" : "medium",
      estimatedTime: a.estimatedTime ? String(a.estimatedTime) : impact === "high" ? "1-3일" : "1주",
      estimatedHours: a.estimatedHours ? Number(a.estimatedHours) : 0,
      expectedDelta,
      description: String(a.description ?? ""),
      action: String(a.action ?? a.title ?? ""),
      affectedPages: Number(a.affectedPages ?? 0),
      owner: String(a.owner ?? ""),
    };
  });
}

