// ── V3 Measurement Runs (unified — reads from runs collection) ───

function toDate(v: unknown): Date | null {
  if (!v) return null;
  if (v instanceof Date) return v;
  if (typeof v === "string") return new Date(v);
  if (typeof (v as { toDate?: unknown }).toDate === "function") {
    return (v as { toDate: () => Date }).toDate();
  }
  return null;
}

function snapToRunDoc(id: string, data: Record<string, unknown>): RunDoc {
  return {
    id,
    commandId: (data.commandId as string) ?? id,
    commandType: (data.commandType as RunDoc["commandType"]) ?? "start_v3_measurement",
    status: (data.status as RunDoc["status"]) ?? "running",
    steps: (data.steps ?? {}) as RunDoc["steps"],
    progress: (data.progress as number) ?? 0,
    message: (data.message as string) ?? "",
    errorCount: (data.errorCount as number) ?? 0,
    warningCount: (data.warningCount as number) ?? 0,
    userId: (data.userId as string) ?? "",
    startedAt: toDate(data.startedAt) ?? new Date(),
    completedAt: toDate(data.completedAt),
    durationMs: (data.durationMs as number) ?? null,
    params: (data.params as Record<string, unknown>) ?? undefined,
    totalItems: data.totalItems != null ? (data.totalItems as number) : undefined,
    completedItems: data.completedItems != null ? (data.completedItems as number) : undefined,
    failedItems: data.failedItems != null ? (data.failedItems as number) : undefined,
  };
}

const V3_COMMAND_TYPES = ["start_v3_measurement", "retry_v3_measurement"];

export async function getV3Runs(boardId: string, limit = 20): Promise<{ runs: RunDoc[] }> {
  try {
    const snap = await getDocs(
      query(
        paths.runs(boardId),
        where("commandType", "in", V3_COMMAND_TYPES),
        orderBy("startedAt", "desc"),
        fbLimit(limit),
      ),
    );
    const runs = snap.docs.map((d) => snapToRunDoc(d.id, d.data() as Record<string, unknown>));
    return { runs };
  } catch (_e) {
    // Fallback: composite index가 없을 때 클라이언트 필터/정렬
    const snap = await getDocs(query(paths.runs(boardId), fbLimit(100)));
    const runs = snap.docs
      .filter((d) => V3_COMMAND_TYPES.includes(d.data().commandType as string))
      .map((d) => snapToRunDoc(d.id, d.data() as Record<string, unknown>))
      .sort((a, b) => (b.startedAt?.getTime() ?? 0) - (a.startedAt?.getTime() ?? 0))
      .slice(0, limit);
    return { runs };
  }
}

/**
 * Firestore 실시간 리스너 — running/analyzing 상태인 V3 run 을 즉시 감지.
 * run 이 있으면 RunDoc 을, 없으면 null 을 콜백으로 전달.
 */
export function subscribeActiveV3Run(
  boardId: string,
  callback: (run: RunDoc | null) => void,
): Unsubscribe {
  const q = query(
    paths.runs(boardId),
    where("commandType", "in", V3_COMMAND_TYPES),
    where("status", "in", ["pending", "running", "analyzing"]),
    fbLimit(1),
  );
  return onSnapshot(q, (snap) => {
    if (snap.empty) {
      callback(null);
    } else {
      const d = snap.docs[0];
      callback(snapToRunDoc(d.id, d.data() as Record<string, unknown>));
    }
  });
}

