export async function getV3MeasurementResults(
  boardId: string,
  runId: string,
  opts?: { limit?: number; offset?: number; engine?: string },
): Promise<{ results: Record<string, unknown>[]; limit: number; offset: number }> {
  const limit = Math.min(opts?.limit ?? 100, 1000);
  const offset = opts?.offset ?? 0;

  let q;
  if (opts?.engine && (opts.engine === "gpt" || opts.engine === "gemini")) {
    q = query(paths.v3MeasurementResults(boardId, runId), where("engine", "==", opts.engine));
  } else {
    q = query(paths.v3MeasurementResults(boardId, runId));
  }

  const snap = await getDocs(q);
  const all = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
  all.sort((a, b) => parseInt(a.id) - parseInt(b.id));
  const sliced = all.slice(offset, offset + limit);
  return { results: sliced, limit, offset };
}

