export async function getV3Actions(boardId: string): Promise<V3ActionList> {
  const snap = await getDocs(paths.v3Actions(boardId));
  const actions: V3Action[] = snap.docs.map((d) => ({
    id: d.id,
    ...(d.data() as Omit<V3Action, "id">),
  }));
  const completed = actions.filter((a) => a.status === "completed");
  const inProgress = actions.filter((a) => a.status === "in_progress");
  const planned = actions.filter((a) => a.status === "planned");
  const cancelled = actions.filter((a) => a.status === "cancelled");
  return {
    actions,
    groups: { completed, inProgress, planned, cancelled },
    counts: {
      total: actions.length,
      completed: completed.length,
      inProgress: inProgress.length,
      planned: planned.length,
      cancelled: cancelled.length,
    },
  };
}

export async function createV3Action(boardId: string, data: Partial<V3Action>): Promise<V3Action> {
  const id = `v3a-${Date.now()}`;
  const now = new Date().toISOString();
  const action: V3Action = {
    id,
    onboardingId: boardId,
    title: data.title ?? "",
    description: data.description ?? "",
    status: data.status ?? "planned",
    priority: data.priority ?? "P2",
    category: data.category ?? "",
    progress: data.progress ?? 0,
    relatedQueries: data.relatedQueries ?? [],
    plannedStart: data.plannedStart ?? "",
    createdAt: now,
    updatedAt: now,
    ...data,
  } as V3Action;
  const cleaned = JSON.parse(JSON.stringify(action));
  await setDoc(paths.v3Action(boardId, id), cleaned);
  return action;
}

