export async function getV3Recommendations(boardId: string): Promise<V3RecList> {
  const snap = await getDocs(paths.v3Recommendations(boardId));
  const recommendations: V3Recommendation[] = snap.docs.map((d) => ({
    id: d.id,
    ...(d.data() as Omit<V3Recommendation, "id">),
  }));
  const pending = recommendations.filter((r) => r.status === "pending");
  const converted = recommendations.filter((r) => r.status === "converted");
  const dismissed = recommendations.filter((r) => r.status === "dismissed");
  return {
    recommendations,
    groups: { pending, converted, dismissed },
    counts: {
      total: recommendations.length,
      pending: pending.length,
      converted: converted.length,
      dismissed: dismissed.length,
    },
  };
}

export async function convertV3Recommendation(
  boardId: string,
  recId: string,
  actionOverride?: Partial<V3Action>,
): Promise<{ action: V3Action; recommendationId: string }> {
  const recSnap = await getDoc(paths.v3Recommendation(boardId, recId));
  const rec = recSnap.exists() ? (recSnap.data() as V3Recommendation) : null;

  const action = await createV3Action(boardId, {
    title: rec?.title ?? "Converted action",
    description: rec?.description,
    priority: rec?.priority ?? "P1",
    category: rec?.category,
    relatedQueries: rec?.relatedQueries,
    sourceRecommendationId: recId,
    ...actionOverride,
  });

  await setDoc(
    paths.v3Recommendation(boardId, recId),
    { status: "converted", convertedActionId: action.id, convertedAt: new Date().toISOString() },
    { merge: true },
  );

  return { action, recommendationId: recId };
}

export async function dismissV3Recommendation(boardId: string, recId: string): Promise<void> {
  await setDoc(
    paths.v3Recommendation(boardId, recId),
    { status: "dismissed", dismissedAt: new Date().toISOString() },
    { merge: true },
  );
}

export async function snoozeV3Recommendation(boardId: string, recId: string, days: number = 7): Promise<string> {
  const snoozedUntil = new Date(Date.now() + days * 86400000).toISOString();
  await setDoc(
    paths.v3Recommendation(boardId, recId),
    { snoozedUntil, updatedAt: new Date().toISOString() },
    { merge: true },
  );
  return snoozedUntil;
}

// ── Data Export — 보드 전체 데이터 추출 ─────────────────────────────

export interface ExportSection {
  key: string;
  label: string;
  path: string;
  type: "doc" | "collection";
  data: unknown;
  docCount: number;
}

function stripFirestoreTimestamps(obj: unknown): unknown {
  if (obj === null || obj === undefined) return obj;
  if (typeof obj !== "object") return obj;
  if (obj instanceof Date) return obj.toISOString();
  if (typeof (obj as any).toDate === "function") return (obj as any).toDate().toISOString();
  if (Array.isArray(obj)) return obj.map(stripFirestoreTimestamps);
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
    out[k] = stripFirestoreTimestamps(v);
  }
  return out;
}

async function readDoc(ref: DocumentReference): Promise<unknown> {
  const snap = await getDoc(ref);
  if (!snap.exists()) return null;
  return stripFirestoreTimestamps(snap.data());
}

async function readCollection(ref: any, sortField?: string, maxDocs = 50): Promise<unknown[]> {
  const q = sortField
    ? query(ref, orderBy(sortField, "desc"), fbLimit(maxDocs))
    : query(ref, fbLimit(maxDocs));
  const snap = await getDocs(q);
  return snap.docs.map((d: any) => stripFirestoreTimestamps({ id: d.id, ...d.data() }));
}

export async function extractBoardData(
  boardId: string,
  onProgress?: (done: number, total: number, label: string) => void,
): Promise<ExportSection[]> {
  const sections: Array<{
    key: string;
    label: string;
    path: string;
    type: "doc" | "collection";
    fn: () => Promise<unknown>;
  }> = [
    // Board document
    { key: "board", label: "Board Document", path: `boards/${boardId}`, type: "doc",
      fn: () => readDoc(paths.board(boardId)) },

    // raw/v1 — single docs
    { key: "brandTruth", label: "Brand Truth", path: `raw/v1/brand_truth/default`, type: "doc",
      fn: () => readDoc(paths.rawBrandTruth(boardId)) },
    { key: "sitePolicyRobots", label: "Site Policy (robots)", path: `raw/v1/site_policy/robots`, type: "doc",
      fn: () => readDoc(paths.rawSitePolicyRobots(boardId)) },
    { key: "llmGuidanceLlmsTxt", label: "LLM Guidance (llms.txt)", path: `raw/v1/llm_guidance/llms_txt`, type: "doc",
      fn: () => readDoc(paths.rawLlmGuidanceLlmsTxt(boardId)) },
    { key: "llmGuidanceLlmsFullTxt", label: "LLM Guidance (llms_full.txt)", path: `raw/v1/llm_guidance/llms_full_txt`, type: "doc",
      fn: () => readDoc(paths.rawLlmGuidanceLlmsFullTxt(boardId)) },

    // raw/v1 — collections
    { key: "crawlPages", label: "Crawl Pages", path: `raw/v1/crawl_pages`, type: "collection",
      fn: () => readCollection(paths.rawCrawlPages(boardId), undefined, 30) },
    { key: "competitors", label: "Competitors (raw)", path: `raw/v1/competitors`, type: "collection",
      fn: () => readCollection(paths.rawCompetitors(boardId)) },
    { key: "externalSources", label: "External Sources", path: `raw/v1/external_sources`, type: "collection",
      fn: () => readCollection(paths.rawExternalSources(boardId)) },
    { key: "geoProbes", label: "GEO Probes", path: `raw/v1/geo_probes`, type: "collection",
      fn: () => readCollection(paths.rawGeoProbes(boardId), undefined, 30) },
    { key: "benchmarkDaily", label: "Benchmark Daily", path: `raw/v1/benchmark_daily`, type: "collection",
      fn: () => readCollection(paths.rawBenchmarkDaily(boardId), undefined, 30) },
    { key: "customerMaterials", label: "Customer Materials", path: `raw/v1/customer_materials`, type: "collection",
      fn: () => readCollection(paths.rawCustomerMaterials(boardId)) },
    { key: "urlCandidates", label: "URL Candidates", path: `raw/v1/url_candidates`, type: "collection",
      fn: () => readCollection(paths.rawUrlCandidates(boardId), undefined, 30) },

    // analyses (v1)
    ...Object.entries(ANALYSIS_KEYS).map(([k, v]) => ({
      key: `analysis_${k}`, label: `Analysis: ${v}`, path: `analyses/${v}`, type: "doc" as const,
      fn: () => readDoc(paths.analysis(boardId, v)),
    })),

    // analyses/v3/measurements
    { key: "v3MeasurementAnalyses", label: "V3 Measurement Analyses", path: `analyses/v3/measurements`, type: "collection",
      fn: () => readCollection(paths.v3MeasurementAnalyses(boardId), undefined, 10) },

    // summaries (v1)
    ...Object.entries(SUMMARY_KEYS).map(([k, v]) => ({
      key: `summary_${k}`, label: `Summary: ${v}`, path: `summaries/${v}`, type: "doc" as const,
      fn: () => readDoc(paths.summary(boardId, v)),
    })),

    // actions/v1
    { key: "actionPlan", label: "Action Plan (v1)", path: `actions/v1/plan/default`, type: "doc",
      fn: () => readDoc(paths.actionPlan(boardId)) },
    { key: "actionPreviews", label: "Action Previews (v1)", path: `actions/v1/previews`, type: "collection",
      fn: () => readCollection(paths.actionPreviews(boardId)) },

    // actions/v3
    { key: "v3Actions", label: "V3 Actions", path: `actions/v3/actions`, type: "collection",
      fn: () => readCollection(paths.v3Actions(boardId)) },
    { key: "v3Recommendations", label: "V3 Recommendations", path: `actions/v3/recommendations`, type: "collection",
      fn: () => readCollection(paths.v3Recommendations(boardId)) },

    // reports
    { key: "reports", label: "Reports (v1)", path: `reports`, type: "collection",
      fn: () => readCollection(paths.reports(boardId), undefined, 10) },
    { key: "v3WeeklyReports", label: "V3 Weekly Reports", path: `reports/v3/weekly`, type: "collection",
      fn: () => readCollection(paths.v3WeeklyReports(boardId), "periodEnd", 10) },
    { key: "v3MonthlyReports", label: "V3 Monthly Reports", path: `reports/v3/monthly`, type: "collection",
      fn: () => readCollection(paths.v3MonthlyReports(boardId), undefined, 10) },

    // insights, commands, runs, error_journal
    { key: "insights", label: "Insights", path: `insights`, type: "collection",
      fn: () => readCollection(paths.insights(boardId), undefined, 50) },
    { key: "commands", label: "Commands", path: `commands`, type: "collection",
      fn: () => readCollection(paths.commands(boardId), undefined, 20) },
    { key: "runs", label: "Runs", path: `runs`, type: "collection",
      fn: () => readCollection(paths.runs(boardId), undefined, 20) },
    { key: "errorJournal", label: "Error Journal", path: `error_journal`, type: "collection",
      fn: () => readCollection(paths.errorJournal(boardId), undefined, 20) },

    // sns
    { key: "snsConnections", label: "SNS Connections", path: `sns_connections`, type: "collection",
      fn: () => readCollection(paths.snsConnections(boardId)) },
  ];

  const results: ExportSection[] = [];
  for (let i = 0; i < sections.length; i++) {
    const s = sections[i];
    onProgress?.(i, sections.length, s.label);
    try {
      const data = await s.fn();
      const docCount = Array.isArray(data) ? data.length : (data ? 1 : 0);
      if (docCount > 0) {
        results.push({ key: s.key, label: s.label, path: s.path, type: s.type, data, docCount });
      }
    } catch {
      // skip inaccessible paths
    }
  }
  onProgress?.(sections.length, sections.length, "Done");
  return results;
}
