import { useState } from "react";
import { useParams } from "react-router-dom";
import { useWebsite } from "./dataHub";
import { HeaderV4DiagnosticButton } from "./V4DiagnosticPanel";
import { runWebsiteDiagnostics } from "./diagnostics/websiteDiagnostics";
import type { WebsiteAnalysisSection } from "./dataHub/types";

const statusColor = (s: string) =>
  s === "good" ? "text-emerald-400" : s === "needs-improvement" ? "text-amber-400" : "text-red-400";
const statusBg = (s: string) =>
  s === "good" ? "bg-emerald-400" : s === "needs-improvement" ? "bg-amber-400" : "bg-red-400";
const checkBadgeClass = (s: string) =>
  s === "pass"
    ? "bg-emerald-500/20 text-emerald-400 border-emerald-400/30"
    : s === "fail"
    ? "bg-rose-500/20 text-rose-400 border-rose-400/30"
    : "bg-amber-500/20 text-amber-400 border-amber-400/30";
const checkLabel = (s: string) => (s === "pass" ? "통과" : s === "fail" ? "실패" : "주의");
const insightIcon = (t: string) =>
  t === "strength" ? "text-emerald-400" : t === "critical" ? "text-red-400" : t === "issue" ? "text-rose-400" : "text-amber-400";

export function PortalV4Website() {
  const { id } = useParams();
  const q = useWebsite(id!);
  const data = q.data;
  const [device, setDevice] = useState<"mobile" | "desktop">("mobile");

  if (q.isLoading || !data) {
    return <div className="flex h-64 items-center justify-center text-[var(--shell-text-soft)]">로딩 중...</div>;
  }

  const verdict = data.verdict;
  const categories = data.lighthouse?.categories || [];
  const cwvMetrics = data.coreWebVitals?.metrics || [];
  const seo = data.seoAnalysis;
  const geo = data.geoAnalysis;
  const fixes = data.priorityFixes || [];

  return (
    <>
      {id && <HeaderV4DiagnosticButton boardId={id} title="V4 Website 진단" runner={runWebsiteDiagnostics} />}
      <div className="mx-auto max-w-5xl space-y-6 p-6">
      {/* Topbar */}
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div>
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-accent)]">GEO DASHBOARD</div>
          <h1 className="mt-1 text-xl font-extrabold text-[var(--shell-text)]">웹사이트 분석</h1>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            Lighthouse + GEO 체크리스트 + 콘텐츠 분석 — 사이트의 AI·검색 준비도를 점검합니다.
          </p>
        </div>
        <div className="flex flex-col items-end gap-1 text-right">
          <div className="text-xs text-[var(--shell-text-soft)]">
            {verdict?.measuredAt?.slice(0, 10).replace(/-/g, ".")} 기준 · {verdict?.pagesAnalyzed}개 페이지 분석
          </div>
          <div className="text-[11px] text-[var(--shell-text-soft)]">{verdict?.site}</div>
        </div>
      </div>

      {/* Section 1: Verdict */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">종합 분석 결과</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">사이트의 검색·AI 준비도를 한눈에 확인합니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">사이트의 AI·검색 준비도는 어떤가요?</span>
        </div>
        <div className="p-5 space-y-4">
          <div>
            <h3 className="text-base font-bold text-[var(--shell-text)]">{verdict?.headline}</h3>
            <p className="mt-1 text-xs text-[var(--shell-text-muted)] leading-relaxed">{verdict?.subline}</p>
          </div>

          {/* Device overall scores */}
          <div className="grid grid-cols-2 gap-3">
            {(["mobile", "desktop"] as const).map((d) => (
              <div key={d} className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 text-center">
                <div className="text-[11px] text-[var(--shell-text-soft)] uppercase">{d === "mobile" ? "Mobile" : "Desktop"}</div>
                <div className={`mt-1 text-3xl font-extrabold ${(verdict?.devices?.[d]?.overall ?? 0) >= 70 ? "text-amber-400" : "text-red-400"}`}>
                  {verdict?.devices?.[d]?.overall ?? 0}
                </div>
                <div className="text-[10px] text-[var(--shell-text-soft)]">/ 100</div>
              </div>
            ))}
          </div>

          {/* Anomalies */}
          {(verdict?.anomalies?.length ?? 0) > 0 && (
            <div className="space-y-2">
              {verdict.anomalies!.map((a, i) => (
                <div key={i} className={`flex items-start gap-2 rounded-lg border px-3 py-2 text-xs ${
                  a.severity === "critical"
                    ? "border-red-400/30 bg-red-500/10 text-red-300"
                    : "border-amber-400/30 bg-amber-500/10 text-amber-300"
                }`}>
                  <span className="mt-0.5 shrink-0 font-bold">{a.severity === "critical" ? "!" : "~"}</span>
                  <span>{a.message}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </article>

      {/* Section 2: Lighthouse Scores */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">카테고리별 점수</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">Lighthouse 4개 + GEO 1개 카테고리 점수를 Mobile / Desktop 비교합니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">카테고리별 점수 현황은 어떤가요?</span>
          <div className="flex gap-1">
            {(["mobile", "desktop"] as const).map((d) => (
              <button
                key={d}
                onClick={() => setDevice(d)}
                className={`rounded px-2.5 py-1 text-[10px] font-bold transition-colors ${
                  device === d ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]" : "text-[var(--shell-text-soft)] hover:text-[var(--shell-text)]"
                }`}
              >
                {d === "mobile" ? "Mobile" : "Desktop"}
              </button>
            ))}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-3 p-5 md:grid-cols-5">
          {categories.map((cat) => {
            const info = cat[device];
            return (
              <div key={cat.id} className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3 text-center">
                <div className="text-[11px] text-[var(--shell-text-soft)]">{cat.labelKo}</div>
                <div className={`mt-1 text-2xl font-extrabold ${statusColor(info.status)}`}>
                  {info.score}
                </div>
                <div className={`mx-auto mt-1.5 h-1 w-full rounded-full bg-[var(--shell-panel-soft)] overflow-hidden`}>
                  <div className={`h-full rounded-full ${statusBg(info.status)} transition-all`} style={{ width: `${info.score}%` }} />
                </div>
                <div className="mt-1.5 text-[10px] text-[var(--shell-text-soft)]">{cat.description}</div>
              </div>
            );
          })}
        </div>
      </article>

      {/* Section 3: Core Web Vitals */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">Core Web Vitals</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">Google 랭킹에 직접 영향하는 성능 지표를 Mobile / Desktop 비교합니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">Core Web Vitals 상태는 어떤가요?</span>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                <th className="px-4 py-3">지표</th>
                <th className="px-4 py-3">설명</th>
                <th className="px-4 py-3 text-right">Mobile</th>
                <th className="px-4 py-3 text-right">Desktop</th>
                <th className="px-4 py-3 text-right">목표</th>
              </tr>
            </thead>
            <tbody>
              {cwvMetrics.map((m) => (
                <tr key={m.id} className="border-b border-[var(--shell-border)]">
                  <td className="px-4 py-2.5 font-bold text-[var(--shell-text)]">
                    {m.label}
                    {m.rankingFactor && <span className="ml-1.5 text-[9px] text-[var(--shell-accent)] font-normal">Ranking</span>}
                  </td>
                  <td className="px-4 py-2.5 text-[var(--shell-text-soft)] max-w-[200px] truncate">{m.description}</td>
                  <td className={`px-4 py-2.5 text-right font-semibold ${statusColor(m.mobile.status)}`}>
                    {m.mobile.value}{m.unit}
                  </td>
                  <td className={`px-4 py-2.5 text-right font-semibold ${statusColor(m.desktop.status)}`}>
                    {m.desktop.value}{m.unit}
                  </td>
                  <td className="px-4 py-2.5 text-right text-[var(--shell-text-soft)]">{m.targetLabel}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </article>

      {/* Section 4: SEO Analysis */}
      {seo && <AnalysisCard title="SEO 분석" desc="Google·Naver 검색 엔진 관점에서 사이트를 평가합니다." analysis={seo} />}

      {/* Section 5: GEO Analysis */}
      {geo && <AnalysisCard title="GEO 분석 (AI 답변 엔진)" desc="ChatGPT·Claude·Gemini 답변에 노출되기 위한 준비도를 평가합니다." analysis={geo} />}

      {/* Section 6: Priority Fixes */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">우선 개선 과제</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">Impact x Effort 기준으로 정렬된 개선 항목입니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">가장 우선적으로 개선해야 할 사항은 무엇인가요?</span>
        </div>
        <div className="divide-y divide-[var(--shell-border)]">
          {fixes.map((fix) => (
            <div key={fix.id} className="px-5 py-4 space-y-1.5">
              <div className="flex items-center gap-3">
                <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[var(--shell-accent-soft)] text-[10px] font-bold text-[var(--shell-accent)]">
                  {fix.rank}
                </span>
                <h4 className="text-xs font-bold text-[var(--shell-text)]">{fix.title}</h4>
                <span className="ml-auto shrink-0 rounded px-2 py-0.5 text-[10px] font-bold bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]">
                  {fix.category}
                </span>
              </div>
              <p className="pl-8 text-[11px] text-[var(--shell-text-soft)] leading-relaxed">{fix.description}</p>
              <div className="pl-8 flex flex-wrap gap-3 text-[10px] text-[var(--shell-text-soft)]">
                <span>예상 시간: <strong className="text-[var(--shell-text)]">{fix.estimatedTime}</strong></span>
                <span>예상 점수: <strong className="text-emerald-400">+{fix.expectedDelta}점</strong></span>
                <span>영향: <strong className="text-[var(--shell-text)]">{fix.impact}</strong></span>
                <span>난이도: <strong className="text-[var(--shell-text)]">{fix.effort}</strong></span>
              </div>
            </div>
          ))}
        </div>
      </article>

      {/* Methodology footer */}
      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] p-5">
        <h3 className="mb-2 text-sm font-bold text-[var(--shell-text)]">분석 방법론</h3>
        <p className="text-xs leading-relaxed text-[var(--shell-text-soft)]">
          분석 대상: {verdict?.site} · {verdict?.pagesAnalyzed}개 페이지 ·
          분석 모델: {data.analysisModels?.map((m) => m.name).join(", ")} ·
          측정일: {verdict?.measuredAt?.slice(0, 10).replace(/-/g, ".")} ·
          기준: Google Lighthouse v12 + GEO 독자 체크리스트
        </p>
      </article>
    </div>
    </>
  );
}

function AnalysisCard({ title, desc, analysis }: { title: string; desc: string; analysis: WebsiteAnalysisSection }) {
  return (
    <>
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">{title}</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">{desc}</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">{title} 결과는 어떤가요?</span>
          <div className="flex items-center gap-2 text-[11px]">
            <span className="text-emerald-400">{analysis.passCount} 통과</span>
            <span className="text-amber-400">{analysis.warnCount} 주의</span>
            <span className="text-red-400">{analysis.failCount} 실패</span>
          </div>
        </div>

        <div className="p-5 space-y-5">
          {/* Score + Summary */}
          <div className="flex items-center gap-4">
            <div className={`text-4xl font-extrabold ${statusColor(analysis.status)}`}>{analysis.score}</div>
            <div>
              <div className="text-xs text-[var(--shell-text-muted)]">{analysis.standpoint}</div>
              <p className="mt-0.5 text-xs text-[var(--shell-text)]">{analysis.summary}</p>
            </div>
          </div>

          {/* Top Insights */}
          {(analysis.topInsights?.length ?? 0) > 0 && (
            <div className="space-y-2">
              <div className="text-[11px] font-semibold text-[var(--shell-text-soft)] uppercase">주요 분석 의견</div>
              {analysis.topInsights!.map((ins) => (
                <div key={ins.rank} className="flex gap-3 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
                  <span className={`shrink-0 text-sm font-bold ${insightIcon(ins.type)}`}>{ins.rank}</span>
                  <div>
                    <p className="text-xs font-bold text-[var(--shell-text)]">{ins.title}</p>
                    <p className="mt-0.5 text-[11px] text-[var(--shell-text-soft)] leading-relaxed">{ins.detail}</p>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Checks table */}
          {(analysis.checks?.length ?? 0) > 0 && (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                    <th className="px-3 py-2">항목</th>
                    <th className="px-3 py-2">상태</th>
                    <th className="px-3 py-2">설명</th>
                    <th className="px-3 py-2 text-right">영향도</th>
                  </tr>
                </thead>
                <tbody>
                  {analysis.checks!.map((c) => (
                    <tr key={c.id} className="border-b border-[var(--shell-border)]">
                      <td className="px-3 py-2 text-[var(--shell-text)]">{c.label}</td>
                      <td className="px-3 py-2">
                        <span className={`inline-block rounded-full border px-2 py-0.5 text-[10px] font-bold ${checkBadgeClass(c.status)}`}>
                          {checkLabel(c.status)}
                        </span>
                      </td>
                      <td className="px-3 py-2 text-[var(--shell-text-soft)] max-w-[260px]">{c.message}</td>
                      <td className="px-3 py-2 text-right text-[var(--shell-text-soft)]">{c.impact}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </article>
    </>
  );
}
