import { useParams } from "react-router-dom";
import { useExposure } from "./dataHub";
import { TrendChart } from "./components";
import { HeaderV4DiagnosticButton } from "./V4DiagnosticPanel";
import { runExposureDiagnostics } from "./diagnostics/exposureDiagnostics";

const gradeOf = (score: number) => {
  if (score >= 60) return { text: "우수", color: "text-emerald-400" };
  if (score >= 40) return { text: "보통", color: "text-amber-400" };
  if (score >= 20) return { text: "미흡", color: "text-orange-400" };
  return { text: "매우 낮음", color: "text-red-400" };
};

export function PortalV4Exposure() {
  const { id } = useParams();
  const { data, isLoading } = useExposure(id || "");

  if (isLoading || !data) {
    return <div className="flex h-64 items-center justify-center text-[var(--shell-text-soft)]">로딩 중...</div>;
  }

  const grade = gradeOf(data.geoScore);
  const totalMentions = data.competitorBreakdown.reduce((sum, c) => sum + c.mentionCount, 0);
  const sentTotal = data.sentimentBreakdown.positive + data.sentimentBreakdown.neutral + data.sentimentBreakdown.negative || 1;

  return (
    <>
      {id && <HeaderV4DiagnosticButton boardId={id} title="V4 Exposure 진단" runner={runExposureDiagnostics} />}
      <div className="mx-auto max-w-5xl space-y-6 p-6">
      {/* Topbar */}
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div>
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-accent)]">측정·노출 현황</div>
          <h1 className="mt-1 text-xl font-extrabold text-[var(--shell-text)]">AI 답변 내 브랜드 노출 측정</h1>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            ChatGPT·Gemini 답변 {data.totalCalls}건을 분석해 자사 언급률·언급 맥락·경쟁 현황을 수치로 확인합니다.
          </p>
        </div>
        <div className="flex flex-col items-end gap-1 text-right">
          <div className="text-xs text-[var(--shell-text-soft)]">
            측정 기간 {data.periodStart?.replace(/-/g, ".")} – {data.periodEnd?.replace(/-/g, ".")}
          </div>
        </div>
      </div>

      {/* Section: GEO 통합 스코어 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">GEO 통합 스코어</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">AI 추천 후보 진입 수준을 종합한 지표입니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">AI 답변 내 브랜드 노출 수준은 어떤가요?</span>
          <span className="text-[11px] text-[var(--shell-text-soft)]">{data.measuredAt.slice(0, 10).replace(/-/g, ".")} 기준</span>
        </div>
        <div className="grid gap-6 p-5 md:grid-cols-3">
          {/* Score Left */}
          <div>
            <h3 className="text-xs font-bold text-[var(--shell-text-muted)]">GEO 통합 스코어</h3>
            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-4xl font-extrabold text-[var(--shell-text)]">{Math.round(data.geoScore)}</span>
              <span className={`text-sm font-semibold ${grade.color}`}>/ 100 · {grade.text}</span>
            </div>
            <ul className="mt-3 space-y-1 text-xs text-[var(--shell-text-muted)]">
              {data.engineBreakdown.gpt.rate === 0 && (
                <li>ChatGPT에서는 추천 후보에 들어오지 못했습니다.</li>
              )}
              {data.engineBreakdown.gemini.rate > 0 && (
                <li>Gemini에서만 일부 질문에 제한적으로 노출됩니다.</li>
              )}
              {data.engineBreakdown.gpt.rate > 0 && data.engineBreakdown.gemini.rate > 0 && (
                <li>ChatGPT·Gemini 모두에서 일부 노출되고 있습니다.</li>
              )}
            </ul>
            <small className="mt-3 block text-[11px] text-[var(--shell-text-soft)]">
              측정: {data.measuredAt.slice(0, 10).replace(/-/g, ".")} · {data.totalCalls}개 AI 답변 · 자사 언급 {data.engineBreakdown.gpt.mentioned + data.engineBreakdown.gemini.mentioned}건
            </small>
          </div>

          {/* Divider Col: 자사 언급률 */}
          <div className="border-l border-[var(--shell-border)] pl-5">
            <div className="text-[11px] font-semibold text-[var(--shell-text-soft)]">자사 언급률</div>
            <div className="mt-1">
              <span className="text-2xl font-extrabold text-amber-400">{data.brandMentionRate.toFixed(1)}%</span>
            </div>
            <div className="mt-3 space-y-2.5">
              {(["gemini", "gpt"] as const).map((engine) => {
                const info = data.engineBreakdown[engine];
                const label = engine === "gpt" ? "ChatGPT" : "Gemini";
                const valColor = info.rate > 0 ? (info.rate >= 5 ? "text-emerald-400" : "text-emerald-400") : "text-red-400";
                return (
                  <div key={engine} className="flex items-center gap-3">
                    <strong className="w-16 text-xs text-[var(--shell-text)]">{label}</strong>
                    <span className={`text-sm font-bold ${valColor}`}>{info.rate.toFixed(1)}%</span>
                    <div className="text-[11px] text-[var(--shell-text-soft)]">
                      {info.mentioned}/{info.total}건
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Divider Col: 자사 언급 평가 (Sentiment) */}
          <div className="border-l border-[var(--shell-border)] pl-5">
            <h3 className="text-xs font-bold text-[var(--shell-text-muted)]">자사 언급 평가</h3>
            <p className="mt-0.5 text-[11px] text-[var(--shell-text-soft)]">AI 답변 분석 (샘플 {sentTotal}건)</p>
            <div className="mt-3 space-y-2">
              {[
                { label: "긍정", count: data.sentimentBreakdown.positive, color: "bg-emerald-400", textColor: "text-emerald-400" },
                { label: "중립", count: data.sentimentBreakdown.neutral, color: "bg-gray-400", textColor: "text-[var(--shell-text-muted)]" },
                { label: "부정", count: data.sentimentBreakdown.negative, color: "bg-rose-400", textColor: "text-rose-400" },
              ].map((seg) => {
                const pct = (seg.count / sentTotal) * 100;
                return (
                  <div key={seg.label} className="space-y-1">
                    <div className="flex items-center justify-between text-[11px]">
                      <span className={`font-medium ${seg.textColor}`}>{seg.label}</span>
                      <span className="text-[var(--shell-text-soft)]">{seg.count}건 ({pct.toFixed(1)}%)</span>
                    </div>
                    <div className="h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                      <div className={`h-full rounded-full ${seg.color} transition-all duration-500`} style={{ width: `${pct}%` }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </article>

      {/* Section: 추이 차트 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">AI 답변 내 자사 언급률 추이</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">4주간 ChatGPT·Gemini 답변에서 자사 언급률이 어떻게 변했는지 추적합니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">자사 언급률은 지난 4주 동안 어떻게 변했나요?</span>
          <div className="flex gap-1">
            {["4주", "8주", "12주"].map((r, i) => (
              <span key={r} className={`rounded px-2 py-0.5 text-[10px] font-bold ${i === 0 ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]" : "text-[var(--shell-text-soft)]"}`}>{r}</span>
            ))}
          </div>
        </div>
        <div className="p-5">
          <TrendChart points={data.trendPoints} />
        </div>
      </article>

      {/* Section: 경쟁사 비교 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">경쟁사 언급률 비교</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">동일 질문군에서 경쟁 브랜드 대비 노출 수준을 비교합니다.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        {/* Competitor frequency bars */}
        <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
          <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
            <span className="text-xs font-medium text-[var(--shell-text)]">경쟁사 대비 브랜드 언급 빈도는 어떻게 되나요?</span>
          </div>
          <div className="p-5">
            <p className="mb-3 text-[11px] text-[var(--shell-text-soft)]">{data.totalCalls}개 답변 기준 · ChatGPT + Gemini 통합</p>
            <div className="space-y-3">
              {data.competitorBreakdown.map((comp, i) => {
                const maxMention = Math.max(...data.competitorBreakdown.map(c => c.mentionCount));
                const width = maxMention > 0 ? (comp.mentionCount / maxMention) * 100 : 0;
                const isMe = i === 0;
                return (
                  <div key={comp.name}>
                    <div className="flex items-center justify-between text-[11px]">
                      <span className={`font-medium ${isMe ? "text-[var(--shell-accent)]" : "text-[var(--shell-text)]"}`}>
                        {comp.name}{isMe ? " (기준)" : ""}
                      </span>
                      <span className="text-[var(--shell-text-muted)]">{comp.mentionCount}회 ({comp.mentionRate.toFixed(1)}%)</span>
                    </div>
                    <div className="mt-1 h-2 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                      <div
                        className={`h-full rounded-full transition-all duration-500 ${isMe ? "bg-[var(--shell-accent)]" : "bg-rose-400"}`}
                        style={{ width: `${width}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </article>

        {/* SoV (Share of Voice) */}
        <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
          <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
            <span className="text-xs font-medium text-[var(--shell-text)]">AI 답변 내 점유율(SoV)은?</span>
          </div>
          <div className="p-5">
            <p className="mb-3 text-[11px] text-[var(--shell-text-soft)]">전체 언급 {totalMentions}건 대비 비율</p>
            <div className="flex items-center gap-5">
              <div className="relative h-36 w-36 shrink-0">
                <svg viewBox="0 0 100 100" className="h-full w-full -rotate-90">
                  {data.competitorBreakdown.map((comp, i) => {
                    const colors = ["#5fd39a", "#fb7185", "#f7bf58", "#3aa7d8", "#475569"];
                    const pct = totalMentions > 0 ? (comp.mentionCount / totalMentions) * 100 : 0;
                    const circ = 2 * Math.PI * 38;
                    const dashLen = (pct / 100) * circ;
                    const prevSum = data.competitorBreakdown.slice(0, i).reduce((s, c) => s + (totalMentions > 0 ? (c.mentionCount / totalMentions) * 100 : 0), 0);
                    const offset = -(prevSum / 100) * circ;
                    return (
                      <circle
                        key={comp.name}
                        cx="50" cy="50" r="38" fill="none"
                        stroke={colors[i % colors.length]}
                        strokeWidth="18"
                        strokeDasharray={`${dashLen} ${circ - dashLen}`}
                        strokeDashoffset={offset}
                      />
                    );
                  })}
                  <text x="50" y="46" textAnchor="middle" fill="#edf4ff" fontSize="9" fontWeight="800" className="rotate-90 origin-center">{data.competitorBreakdown[0]?.name}</text>
                  <text x="50" y="57" textAnchor="middle" fill="#5fd39a" fontSize="9" fontWeight="900" className="rotate-90 origin-center">
                    {totalMentions > 0 ? ((data.competitorBreakdown[0]?.mentionCount / totalMentions) * 100).toFixed(1) : 0}%
                  </text>
                </svg>
              </div>
              <ul className="space-y-1.5 text-xs">
                {data.competitorBreakdown.map((comp, i) => {
                  const colors = ["text-emerald-400", "text-rose-400", "text-amber-400", "text-sky-400", "text-[var(--shell-text-muted)]"];
                  const pct = totalMentions > 0 ? ((comp.mentionCount / totalMentions) * 100).toFixed(1) : "0.0";
                  return (
                    <li key={comp.name} className="flex items-center gap-2">
                      <span className="text-[var(--shell-text)]">{comp.name}</span>
                      <strong className={colors[i % colors.length]}>{pct}%</strong>
                    </li>
                  );
                })}
              </ul>
            </div>
          </div>
        </article>
      </div>

      {/* 측정 방법론 */}
      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] p-5">
        <h3 className="mb-2 text-sm font-bold text-[var(--shell-text)]">측정 방법론</h3>
        <p className="text-xs leading-relaxed text-[var(--shell-text-soft)]">
          측정 기간: {data.periodStart?.replace(/-/g, ".")} – {data.periodEnd?.replace(/-/g, ".")} ·
          분석 모델: ChatGPT-4o, Gemini 1.5 Pro ·
          질문 수: {data.queryBreakdown.length}개 대표 질문 ·
          총 답변 수: {data.totalCalls}건 ·
          언급 기준: 브랜드명 또는 제품명이 답변 본문에 포함된 경우
        </p>
      </article>
    </div>
    </>
  );
}
