import { useQuery } from "@tanstack/react-query";
import { fetchExposureRaw, fetchDiagnosisRaw, fetchImprovementRaw, fetchTrackingRaw, fetchReportRaw, fetchWebsiteRaw } from "./api";
import { toExposureData, toDiagnosisData, toImprovementData, toTrackingData, toReportData, toWebsiteData } from "./transforms";
import type { ExposureData, DiagnosisData, ImprovementData, TrackingData, ReportData, WebsiteData } from "./types";

export type { TrackingData } from "./types";

export function useExposure(boardId: string) {
  return useQuery<ExposureData>({
    queryKey: ["portalV4", "exposure", boardId],
    queryFn: async () => {
      const raw = await fetchExposureRaw(boardId);
      return toExposureData(raw);
    },
    staleTime: 60_000,
    enabled: !!boardId,
  });
}

