export function useTrackingRaw(boardId: string) {
  return useQuery({
    queryKey: ["portalV4", "tracking-raw", boardId],
    queryFn: () => fetchTrackingRaw(boardId),
    staleTime: 60_000,
    enabled: !!boardId,
  });
}
