import { getDoc, getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths, SUMMARY_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runExposureDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // 1. summaries/measurement
  try {
    const snap = await getDoc(paths.summary(boardId, SUMMARY_KEYS.measurement));
    if (!snap.exists()) {
      results.push({ id: "exp-meas", label: "summaries/measurement", status: "fail", detail: "문서 없음" });
    } else {
      const d = snap.data() as any;
      results.push({ id: "exp-meas", label: "summaries/measurement", status: "pass", detail: `geoScore: ${d?.analysis?.geoScore ?? "N/A"}, brandMentionRate: ${d?.analysis?.brandMentionRate ?? "N/A"}` });
      const hasComp = Array.isArray(d?.analysis?.competitorBreakdown) && d.analysis.competitorBreakdown.length > 0;
      results.push({ id: "exp-comp", label: "competitorBreakdown 배열", status: hasComp ? "pass" : "warn", detail: hasComp ? `${d.analysis.competitorBreakdown.length}개 항목` : "비어있음" });
      const hasSent = !!d?.analysis?.sentimentBreakdown;
      results.push({ id: "exp-sent", label: "sentimentBreakdown", status: hasSent ? "pass" : "warn", detail: hasSent ? JSON.stringify(d.analysis.sentimentBreakdown) : "없음" });
    }
  } catch (err: any) {
    results.push({ id: "exp-meas", label: "summaries/measurement", status: "fail", detail: err.message });
  }

  // 2. raw/v1/benchmark_daily
  try {
    const snap = await getDocs(query(paths.rawBenchmarkDaily(boardId), fbLimit(20)));
    const count = snap.docs.length;
    results.push({ id: "exp-bench", label: "raw/v1/benchmark_daily", status: count >= 2 ? "pass" : count > 0 ? "warn" : "fail", detail: `${count}개 문서 (추세 차트에 2개 이상 필요)` });
  } catch (err: any) {
    results.push({ id: "exp-bench", label: "raw/v1/benchmark_daily", status: "fail", detail: err.message });
  }

  // 3. raw/v1/brand_truth
  try {
    const snap = await getDoc(paths.rawBrandTruth(boardId));
    results.push({ id: "exp-brand", label: "raw/v1/brand_truth", status: snap.exists() ? "pass" : "fail", detail: snap.exists() ? "존재" : "문서 없음" });
  } catch (err: any) {
    results.push({ id: "exp-brand", label: "raw/v1/brand_truth", status: "fail", detail: err.message });
  }

  return results;
};
