import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { AlertTriangle, ChevronDown, Database, Lightbulb, Search, TrendingUp, Zap } from "lucide-react";
import {
  getGoogleKeywordAnalysis,
  getNaverKeywordAnalysis,
  getDocument,
  subscribeInsights,
} from "../../../db/boards";
import type {
  GoogleKeywordAnalysis,
  GoogleKeywordMetric,
  GoogleKeywordPresence,
  NaverKeywordAnalysis,
  NaverKeyword,
  ClassifiedKeywords,
  KeywordMetrics,
  BoardDocument,
  InsightDoc,
} from "../../../db/collections";
import { OpenInsightsList } from "../../../components/shared/OpenInsightsList";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";

// ── Types ──────────────────────────────────────────────────

type SubTab = "google" | "naver" | "strategy";

interface ActionItem {
  title: string;
  type?: string;
  category?: string;
  priority?: string;
  expectedImpact?: string;
  description?: string;
}

// ── Component ──────────────────────────────────────────────

export function SearchDemandInsight() {
  const { id } = useParams<{ id: string }>();
  const [google, setGoogle] = useState<GoogleKeywordAnalysis | null>(null);
  const [naver, setNaver] = useState<NaverKeywordAnalysis | null>(null);
  const [strategyDoc, setStrategyDoc] = useState<Record<string, unknown> | null>(null);
  const [actionPlanDoc, setActionPlanDoc] = useState<BoardDocument | null>(null);
  const [insights, setInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);
  const [subTab, setSubTab] = useState<SubTab>("google");

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsub = subscribeInsights(id, setInsights, { type: "search_demand" });
    Promise.all([
      getGoogleKeywordAnalysis(id),
      getNaverKeywordAnalysis(id),
      getDocument(id, "keyword-strategy"),
      getDocument(id, "action-plan").catch(() => null),
    ]).then(([g, n, s, ap]) => {
      setGoogle(g);
      setNaver(n);
      setStrategyDoc((s?.data ?? null) as Record<string, unknown> | null);
      setActionPlanDoc(ap);
      setLoading(false);
    });
    return unsub;
  }, [id]);

  const classified = useMemo(() => {
    const raw = strategyDoc?.classifiedKeywords ?? strategyDoc?.classified ?? null;
    if (!raw || typeof raw !== "object") return null;
    return raw as ClassifiedKeywords;
  }, [strategyDoc]);

  const totalGoogleKws = google?.metrics?.length ?? 0;
  const totalNaverKws = naver?.topKeywords?.length ?? 0;
  const googleScore = google?.googleScore ?? null;
  const naverScore = naver?.naverScore ?? null;

  // ── Derived: Diagnosis ──

  const diagnosis = useMemo(() => {
    const items: Array<{ severity: "high" | "medium" | "low"; title: string; detail: string }> = [];

    if (google?.presence) {
      const notFound = google.presence.filter((p) => !p.found);
      if (notFound.length > 0) {
        items.push({
          severity: notFound.length > google.presence.length * 0.5 ? "high" : "medium",
          title: `${notFound.length} keyword${notFound.length !== 1 ? "s" : ""} with no Google ranking`,
          detail: notFound.slice(0, 5).map((p) => p.keyword).join(", ") + (notFound.length > 5 ? ` +${notFound.length - 5} more` : ""),
        });
      }
    }

    if (naver?.presenceSummary) {
      const rate = naver.presenceSummary.exposureRate;
      if (rate < 30) {
        items.push({
          severity: "high",
          title: `Low Naver exposure rate: ${rate}%`,
          detail: `Only ${naver.presenceSummary.exposedKeywords}/${naver.presenceSummary.totalKeywords} keywords are visible on Naver.`,
        });
      }
    }

    if (naver?.topKeywords) {
      const highVolLowDiff = naver.topKeywords.filter(
        (kw) => (kw.monthlySearchVolume?.total ?? 0) > 1000 && (kw.difficultyGrade === "A" || kw.difficultyGrade === "B"),
      );
      if (highVolLowDiff.length > 0) {
        items.push({
          severity: "low",
          title: `${highVolLowDiff.length} high-volume, low-difficulty keywords found`,
          detail: highVolLowDiff.slice(0, 3).map((k) => k.keyword).join(", "),
        });
      }
    }

    if (!google && !naver) {
      items.push({
        severity: "medium",
        title: "No keyword data available",
        detail: "Run an analysis to collect search demand data from Google and Naver.",
      });
    }

    return items;
  }, [google, naver]);

  // ── Derived: Generated Insights ──

  const generatedInsights = useMemo(() => {
    const result: Array<{ severity: "high" | "medium" | "low"; title: string; explanation: string }> = [];

    if (google?.metrics && classified) {
      const allClassified = [
        ...(classified.site ?? []),
        ...(classified.recommended ?? []),
        ...(classified.competitor ?? []),
        ...(classified.local ?? []),
      ].map((k) => k.keyword.toLowerCase());

      const highVolUnclassified = google.metrics.filter(
        (m) => m.averageMonthlySearches > 500 && !allClassified.includes(m.keyword.toLowerCase()),
      );
      if (highVolUnclassified.length > 0) {
        result.push({
          severity: "medium",
          title: `${highVolUnclassified.length} high-volume keywords not in strategy`,
          explanation: `Keywords like "${highVolUnclassified[0].keyword}" have significant search volume but are not classified in your keyword strategy.`,
        });
      }
    }

    if (naver?.topKeywords) {
      const saturated = naver.topKeywords.filter((k) => (k.blogSaturation?.saturationRate ?? 0) > 80);
      if (saturated.length > 3) {
        result.push({
          severity: "medium",
          title: `${saturated.length} keywords have high blog saturation`,
          explanation: "Consider differentiating with structured data, expert content, or alternative formats for highly saturated keywords.",
        });
      }
    }

    if (google?.competitorDomains && google.competitorDomains.length > 0) {
      const topComp = google.competitorDomains[0];
      result.push({
        severity: "low",
        title: `Top competing domain: ${topComp.domain}`,
        explanation: `Appears in ${topComp.appearances} keyword results with avg position #${topComp.avgPosition.toFixed(1)}.`,
      });
    }

    return result;
  }, [google, naver, classified]);

  // ── Derived: Suggested Actions ──

  const suggestedActions = useMemo(() => {
    const planData = (actionPlanDoc?.data ?? {}) as Record<string, unknown>;
    const actions = (planData.actions ?? planData.items ?? []) as ActionItem[];
    return actions.filter((a) => {
      const cat = (a.category ?? a.type ?? "").toLowerCase();
      return cat.includes("content") || cat.includes("keyword") || cat.includes("seo") || cat.includes("search");
    }).slice(0, 5);
  }, [actionPlanDoc]);

  // ── Derived: Data Quality ──

  const dataQuality = useMemo(() => {
    const hasGoogle = !!google;
    const hasNaver = !!naver;
    const hasStrategy = !!classified;
    const sources = [hasGoogle, hasNaver, hasStrategy].filter(Boolean).length;
    const score = Math.round((sources / 3) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes: string[] = [];
    if (!hasGoogle) notes.push("No Google keyword analysis available");
    if (!hasNaver) notes.push("No Naver keyword analysis available");
    if (!hasStrategy) notes.push("No keyword strategy document");
    return { score, status, notes };
  }, [google, naver, classified]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Summary Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Search} label="Google Keywords" value={String(totalGoogleKws)} color="text-blue-600" />
        <MetricCard icon={Database} label="Naver Keywords" value={String(totalNaverKws)} color="text-emerald-600" />
        <MetricCard icon={TrendingUp} label="Google Score" value={googleScore != null ? String(googleScore) : "--"} color="text-blue-600" />
        <MetricCard icon={TrendingUp} label="Naver Score" value={naverScore != null ? String(naverScore) : "--"} color="text-emerald-600" />
      </div>

      {/* Data Quality */}
      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {/* Raw Data: Keyword tabs */}
      <InsightSection title="Keyword Data" icon={Search} defaultOpen>
        <div className="flex gap-1 border-b border-[var(--shell-border)]">
          {([
            { key: "google" as SubTab, label: "Google Keywords" },
            { key: "naver" as SubTab, label: "Naver Keywords" },
            { key: "strategy" as SubTab, label: "Strategy Keywords" },
          ]).map((t) => (
            <button
              key={t.key}
              onClick={() => setSubTab(t.key)}
              className={`border-b-2 px-4 py-2.5 text-xs font-medium transition-colors ${
                subTab === t.key
                  ? "border-[var(--shell-accent)] text-[var(--shell-accent)]"
                  : "border-transparent text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
        <div className="mt-4">
          {subTab === "google" && <GoogleTab data={google} />}
          {subTab === "naver" && <NaverTab data={naver} />}
          {subTab === "strategy" && <StrategyTab classified={classified} />}
        </div>
      </InsightSection>

      {/* Diagnosis */}
      <InsightSection title="Diagnosis" icon={AlertTriangle} count={diagnosis.length} defaultOpen={diagnosis.length > 0}>
        {diagnosis.length > 0 ? (
          <div className="space-y-2">
            {diagnosis.map((item, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={item.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No diagnostic issues found</p>
        )}
      </InsightSection>

      {/* Open Insights (from insights collection) */}
      <InsightSection
        title="Open Insights"
        icon={Lightbulb}
        count={insights.filter((i) => i.status !== "resolved" && i.status !== "ignored").length}
        defaultOpen
      >
        <OpenInsightsList insights={insights} />
      </InsightSection>

      {/* Generated Insights */}
      <InsightSection title="Generated Insights (legacy)" icon={Lightbulb} count={generatedInsights.length} defaultOpen={false}>
        {generatedInsights.length > 0 ? (
          <div className="space-y-2">
            {generatedInsights.map((insight, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={insight.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{insight.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{insight.explanation}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No insights generated yet. Keyword data will produce insights here.</p>
        )}
      </InsightSection>

      {/* Suggested Actions */}
      <InsightSection title="Suggested Actions" icon={Zap} count={suggestedActions.length} defaultOpen={false}>
        {suggestedActions.length > 0 ? (
          <div className="space-y-2">
            {suggestedActions.map((action, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <Zap className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[var(--shell-accent)]" />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{action.title}</p>
                  {action.description && <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{action.description}</p>}
                  {action.priority && (
                    <span className={`mt-1 inline-block rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                      action.priority === "high" ? "bg-rose-500/10 text-rose-500"
                        : action.priority === "medium" ? "bg-amber-500/10 text-amber-500"
                          : "bg-emerald-500/10 text-emerald-600"
                    }`}>{action.priority}</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">Run an analysis to generate action recommendations</p>
        )}
      </InsightSection>
    </div>
  );
}

// ── Sub-components ──────────────────────────────────────────

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}

// ── Google Keywords Tab ────────────────────────────────────

function GoogleTab({ data }: { data: GoogleKeywordAnalysis | null }) {
  if (!data || !data.metrics || data.metrics.length === 0) {
    return <EmptyState icon={Search} title="No Google keyword data" description="분석을 실행하면 Google 키워드 지표를 수집합니다" />;
  }

  const sorted = [...data.metrics].sort((a, b) => b.averageMonthlySearches - a.averageMonthlySearches);

  return (
    <div className="space-y-4">
      {data.presence && data.presence.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-text-muted)]">Ranking Presence</h4>
          <div className="mt-2 flex flex-wrap gap-2">
            {data.presence.slice(0, 12).map((p: GoogleKeywordPresence) => (
              <span
                key={p.keyword}
                className={`rounded-lg px-2.5 py-1 text-xs font-medium ${
                  p.found ? "bg-emerald-500/10 text-emerald-600" : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]"
                }`}
              >
                {p.keyword} {p.position != null ? `#${p.position}` : ""}
              </span>
            ))}
          </div>
        </div>
      )}

      <div className="overflow-x-auto rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b border-[var(--shell-border)] text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">
              <th className="px-4 py-3 font-medium">Keyword</th>
              <th className="px-4 py-3 text-right font-medium">Monthly Search</th>
              <th className="px-4 py-3 text-right font-medium">Competition</th>
              <th className="px-4 py-3 text-right font-medium">CPC (Low)</th>
              <th className="px-4 py-3 text-right font-medium">CPC (High)</th>
            </tr>
          </thead>
          <tbody>
            {sorted.slice(0, 30).map((m) => (
              <GoogleRow key={m.keyword} metric={m} />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function GoogleRow({ metric }: { metric: GoogleKeywordMetric }) {
  const compColor = metric.competition === "HIGH" ? "text-rose-500" : metric.competition === "MEDIUM" ? "text-amber-500" : "text-emerald-600";
  return (
    <tr className="border-b border-[var(--shell-border)]/50 transition-colors hover:bg-[var(--shell-panel-soft)]">
      <td className="px-4 py-2.5 font-medium text-[var(--shell-text)]">{metric.keyword}</td>
      <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">{metric.averageMonthlySearches.toLocaleString()}</td>
      <td className={`px-4 py-2.5 text-right text-xs font-medium ${compColor}`}>{metric.competition}</td>
      <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">{metric.lowTopOfPageBidKrw?.toLocaleString() ?? "--"}</td>
      <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">{metric.highTopOfPageBidKrw?.toLocaleString() ?? "--"}</td>
    </tr>
  );
}

// ── Naver Keywords Tab ─────────────────────────────────────

function NaverTab({ data }: { data: NaverKeywordAnalysis | null }) {
  if (!data || !data.topKeywords || data.topKeywords.length === 0) {
    return <EmptyState icon={Database} title="No Naver keyword data" description="분석을 실행하면 Naver 키워드 지표를 수집합니다" />;
  }

  const sorted = [...data.topKeywords].sort(
    (a, b) => (b.monthlySearchVolume?.total ?? 0) - (a.monthlySearchVolume?.total ?? 0),
  );

  return (
    <div className="space-y-4">
      {data.presenceSummary && (
        <div className="grid gap-3 sm:grid-cols-3">
          <MiniStat label="Exposed Keywords" value={`${data.presenceSummary.exposedKeywords}/${data.presenceSummary.totalKeywords}`} />
          <MiniStat label="Exposure Rate" value={`${data.presenceSummary.exposureRate}%`} />
          <MiniStat label="Avg Position" value={data.presenceSummary.avgPosition != null ? `#${data.presenceSummary.avgPosition}` : "--"} />
        </div>
      )}

      <div className="overflow-x-auto rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b border-[var(--shell-border)] text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">
              <th className="px-4 py-3 font-medium">Keyword</th>
              <th className="px-4 py-3 text-right font-medium">Monthly Search</th>
              <th className="px-4 py-3 text-right font-medium">Competition</th>
              <th className="px-4 py-3 text-right font-medium">Difficulty</th>
              <th className="px-4 py-3 text-right font-medium">Blog Saturation</th>
            </tr>
          </thead>
          <tbody>
            {sorted.slice(0, 30).map((kw) => (
              <NaverRow key={kw.keyword} kw={kw} />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function NaverRow({ kw }: { kw: NaverKeyword }) {
  const total = kw.monthlySearchVolume?.total ?? 0;
  const diffColor = kw.difficultyGrade === "A" ? "text-emerald-600" : kw.difficultyGrade === "B" ? "text-teal-600" : kw.difficultyGrade === "C" ? "text-amber-500" : "text-rose-500";
  return (
    <tr className="border-b border-[var(--shell-border)]/50 transition-colors hover:bg-[var(--shell-panel-soft)]">
      <td className="px-4 py-2.5 font-medium text-[var(--shell-text)]">{kw.keyword}</td>
      <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">{total.toLocaleString()}</td>
      <td className="px-4 py-2.5 text-right text-xs text-[var(--shell-text-muted)]">{kw.competition}</td>
      <td className={`px-4 py-2.5 text-right text-xs font-medium ${diffColor}`}>{kw.difficultyGrade}</td>
      <td className="px-4 py-2.5 text-right tabular-nums text-[var(--shell-text-muted)]">
        {kw.blogSaturation ? `${kw.blogSaturation.saturationRate}%` : "--"}
      </td>
    </tr>
  );
}

// ── Strategy Keywords Tab ──────────────────────────────────

function StrategyTab({ classified }: { classified: ClassifiedKeywords | null }) {
  if (!classified) {
    return <EmptyState icon={TrendingUp} title="No strategy keywords" description="분석 이후 키워드 전략이 생성됩니다" />;
  }

  const sections: { label: string; keywords: KeywordMetrics[] }[] = [
    { label: "Site Keywords", keywords: classified.site ?? [] },
    { label: "Recommended Keywords", keywords: classified.recommended ?? [] },
    { label: "Competitor Keywords", keywords: classified.competitor ?? [] },
    { label: "Local Keywords", keywords: classified.local ?? [] },
  ].filter((s) => s.keywords.length > 0);

  const strategy = classified.strategy;

  return (
    <div className="space-y-4">
      {strategy && (
        <div className="grid gap-4 sm:grid-cols-3">
          <StrategyTier label="Short Term" keywords={strategy.shortTerm} color="text-emerald-600" bg="bg-emerald-500/10" />
          <StrategyTier label="Mid Term" keywords={strategy.midTerm} color="text-blue-600" bg="bg-blue-500/10" />
          <StrategyTier label="Long Term" keywords={strategy.longTerm} color="text-amber-600" bg="bg-amber-500/10" />
        </div>
      )}

      {strategy?.highPriorityActions && strategy.highPriorityActions.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-text-muted)]">High Priority Actions</h4>
          <div className="mt-3 space-y-2">
            {strategy.highPriorityActions.slice(0, 8).map((a) => (
              <div key={a.keyword} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-2.5">
                <div>
                  <span className="text-sm font-medium text-[var(--shell-text)]">{a.keyword}</span>
                  <span className="ml-2 text-xs text-[var(--shell-text-muted)]">{a.reason}</span>
                </div>
                <div className="flex items-center gap-3 text-xs tabular-nums text-[var(--shell-text-muted)]">
                  <span>{a.totalMonthlyVolume.toLocaleString()}/mo</span>
                  <span>Difficulty {a.overallDifficulty}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {sections.map((section) => (
        <KeywordSection key={section.label} label={section.label} keywords={section.keywords} />
      ))}
    </div>
  );
}

function StrategyTier({ label, keywords, color, bg }: { label: string; keywords: string[]; color: string; bg: string }) {
  if (keywords.length === 0) return null;
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
      <h4 className={`text-xs font-semibold uppercase tracking-wider ${color}`}>{label}</h4>
      <div className="mt-2 flex flex-wrap gap-1.5">
        {keywords.map((kw) => (
          <span key={kw} className={`rounded-lg px-2.5 py-1 text-xs font-medium ${bg} ${color}`}>{kw}</span>
        ))}
      </div>
    </div>
  );
}

function KeywordSection({ label, keywords }: { label: string; keywords: KeywordMetrics[] }) {
  const [expanded, setExpanded] = useState(false);
  const visible = expanded ? keywords : keywords.slice(0, 10);

  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="flex w-full items-center justify-between"
      >
        <h4 className="text-sm font-semibold text-[var(--shell-text)]">{label} ({keywords.length})</h4>
        {keywords.length > 10 && (
          <ChevronDown className={`h-4 w-4 text-[var(--shell-text-muted)] transition-transform ${expanded ? "rotate-180" : ""}`} />
        )}
      </button>
      <div className="mt-3 space-y-1.5">
        {visible.map((kw) => (
          <div key={kw.keyword} className="flex items-center justify-between rounded-xl bg-[var(--shell-panel-soft)] px-3 py-2">
            <span className="text-sm text-[var(--shell-text)]">{kw.keyword}</span>
            <div className="flex items-center gap-3 text-xs tabular-nums text-[var(--shell-text-muted)]">
              {kw.google?.monthlySearchVolume != null && <span>G: {kw.google.monthlySearchVolume.toLocaleString()}</span>}
              {kw.naver?.monthlySearchVolume != null && <span>N: {kw.naver.monthlySearchVolume.toLocaleString()}</span>}
              {kw.overallDifficulty != null && <span>D: {kw.overallDifficulty}</span>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function MiniStat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-3">
      <div className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">{label}</div>
      <div className="mt-1 text-lg font-semibold text-[var(--shell-text)]">{value}</div>
    </div>
  );
}
