import { setDoc, updateDoc, getDoc, serverTimestamp } from "firebase/firestore";
import { paths } from "./paths";

export type UserRole = "pending" | "member";

export interface UserDoc {
  uid: string;
  email: string;
  displayName?: string | null;
  photoURL?: string | null;
  role?: UserRole | string;
  lastLoginAt?: unknown;
}

export function resolveUserRole(userDoc: UserDoc | null | undefined): UserRole {
  if (!userDoc) return "pending";
  if (userDoc.role === "member") return "member";
  return "pending";
}

export async function createOrUpdateUser(
  uid: string,
  email: string,
  displayName?: string,
  photoURL?: string,
) {
  await setDoc(
    paths.user(uid),
    {
      uid,
      email,
      displayName: displayName || null,
      photoURL: photoURL || null,
      lastLoginAt: serverTimestamp(),
    },
    { merge: true },
  );
}

export async function setUserRole(uid: string, role: UserRole) {
  await updateDoc(paths.user(uid), { role });
}

export async function isUserAdmin(uid: string): Promise<boolean> {
  const snap = await getDoc(paths.adminUser(uid));
  return snap.exists();
}
