import { getDoc, getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths, SUMMARY_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runDashboardDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // 1. summaries/measurement
  try {
    const snap = await getDoc(paths.summary(boardId, SUMMARY_KEYS.measurement));
    if (!snap.exists()) {
      results.push({ id: "dash-meas", label: "summaries/measurement", status: "fail", detail: "문서 없음" });
    } else {
      const d = snap.data() as any;
      results.push({ id: "dash-meas", label: "summaries/measurement", status: "pass", detail: `run.status: ${d?.run?.status ?? "N/A"}, analysis.brandMentionRate: ${d?.analysis?.brandMentionRate ?? "N/A"}` });
    }
  } catch (err: any) {
    results.push({ id: "dash-meas", label: "summaries/measurement", status: "fail", detail: err.message });
  }

  // 2. runs collection
  try {
    const snap = await getDocs(query(paths.runs(boardId), fbLimit(10)));
    results.push({ id: "dash-runs", label: "runs 컬렉션", status: snap.docs.length > 0 ? "pass" : "fail", detail: `${snap.docs.length}개` });
  } catch (err: any) {
    results.push({ id: "dash-runs", label: "runs 컬렉션", status: "fail", detail: err.message });
  }

  // 3. actions/v3/recommendations (for dashboard action summary)
  try {
    const snap = await getDocs(query(paths.v3Recommendations(boardId), fbLimit(10)));
    results.push({ id: "dash-recs", label: "actions/v3/recommendations", status: snap.docs.length > 0 ? "pass" : "warn", detail: `${snap.docs.length}개` });
  } catch (err: any) {
    results.push({ id: "dash-recs", label: "actions/v3/recommendations", status: "fail", detail: err.message });
  }

  // 4. raw/v1/benchmark_daily (trend)
  try {
    const snap = await getDocs(query(paths.rawBenchmarkDaily(boardId), fbLimit(10)));
    results.push({ id: "dash-trend", label: "raw/v1/benchmark_daily", status: snap.docs.length >= 2 ? "pass" : snap.docs.length > 0 ? "warn" : "fail", detail: `${snap.docs.length}개 (추세에 2개 이상 필요)` });
  } catch (err: any) {
    results.push({ id: "dash-trend", label: "raw/v1/benchmark_daily", status: "fail", detail: err.message });
  }

  return results;
};
