import { useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import {
  AlertTriangle, CheckCircle2, ChevronDown, Filter, GitCompare,
  RefreshCw, Search, XCircle,
} from "lucide-react";
import {
  subscribeBoard,
  listSeoAudits,
  getSummary,
  subscribeInsights,
  updateInsightStatus,
} from "../../../db/boards";
import type {
  Board,
  InsightDoc,
  InsightSeverity,
  InsightSource,
  InsightStatus,
} from "../../../db/collections";
import { useCommand } from "../../../hooks/useCommand";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";

// ── Types ──────────────────────────────────────────────────

type Severity = InsightSeverity;
type Source = InsightSource;
type Status = InsightStatus;

interface DiffDimension {
  dimension: string;
  gapSeverity: number;
  gapLevel: string;
  customerValue: string[];
  autoDetectedValue: string[];
  gapDescription?: string;
}

interface DiffData {
  overallGapScore: number;
  actionPlanSummary?: string;
  dimensions: DiffDimension[];
}

// ── Constants ──────────────────────────────────────────────

const SEVERITY_ORDER: Record<Severity, number> = { critical: 0, warning: 1, info: 2 };

const SOURCE_LABELS: Partial<Record<Source, string>> = {
  seo: "Website Health",
  geo: "AI Visibility",
  gbp: "Trust Signals",
  runtime: "Runtime",
  content: "Content",
  diff: "Brand Gap",
  competitors: "Competitors",
  external: "External Sources",
  keywords: "Search Demand",
  harness: "Red Team",
  "geo-probe": "GEO Probe",
  "geo-strategy": "GEO Strategy",
};

const STATUS_LABELS: Record<Status, string> = {
  "open": "Open",
  "in-review": "In Review",
  "action-created": "Action Created",
  "resolved": "Resolved",
  "ignored": "Ignored",
};

// ── Component ──────────────────────────────────────────────

export function InsightBoard() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [seoAudit, setSeoAudit] = useState<Record<string, unknown> | null>(null);
  const [diffData, setDiffData] = useState<DiffData | null>(null);
  const [insights, setInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  const [filterSeverity, setFilterSeverity] = useState<"all" | Severity>("all");
  const [filterSource, setFilterSource] = useState<"all" | Source>("all");
  const [filterStatus, setFilterStatus] = useState<"all" | Status>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const cmd = useCommand(id);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubInsights = subscribeInsights(id, setInsights);
    Promise.all([
      listSeoAudits(id, 1),
      getSummary(id, "brand-gap").catch(() => null),
    ]).then(([audits, diffDoc]) => {
      if (audits[0]) setSeoAudit(audits[0] as Record<string, unknown>);
      if (diffDoc) setDiffData(diffDoc as unknown as DiffData);
      setLoading(false);
    });
    return () => {
      unsubBoard();
      unsubInsights();
    };
  }, [id]);

  const allIssues = insights;

  const filteredIssues = useMemo(() => {
    let result = allIssues.filter((i) => i.status !== "resolved");
    if (filterStatus !== "all") {
      result = allIssues.filter((i) => i.status === filterStatus);
    }
    if (filterSeverity !== "all") result = result.filter((i) => i.severity === filterSeverity);
    if (filterSource !== "all") result = result.filter((i) => i.source === filterSource);
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        (i) => i.title.toLowerCase().includes(q) || (i.rule ?? "").toLowerCase().includes(q),
      );
    }
    result = [...result].sort(
      (a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity],
    );
    return result;
  }, [allIssues, filterSeverity, filterSource, filterStatus, searchQuery]);

  const openIssues = useMemo(
    () => allIssues.filter((i) => i.status !== "resolved" && i.status !== "ignored"),
    [allIssues],
  );
  const criticalCount = openIssues.filter((i) => i.severity === "critical").length;
  const warningCount = openIssues.filter((i) => i.severity === "warning").length;
  const seoScore = ((seoAudit as Record<string, unknown>)?.seoScore ?? (seoAudit as Record<string, unknown>)?.score) as number | undefined;
  const geoScore = (seoAudit as Record<string, unknown>)?.geoScore as number | undefined;

  const sourceCounts = useMemo(() => {
    const m = new Map<Source, number>();
    for (const i of openIssues) m.set(i.source, (m.get(i.source) ?? 0) + 1);
    return m;
  }, [openIssues]);

  // ── Derived: Data Quality ──

  const dataQuality = useMemo(() => {
    const hasAudit = !!seoAudit;
    const hasBoard = !!board;
    const hasDiff = !!diffData;
    const count = [hasAudit, hasBoard, hasDiff].filter(Boolean).length;
    const score = Math.round((count / 3) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes: string[] = [];
    if (!hasAudit) notes.push("No SEO/GEO audit data");
    if (!hasBoard) notes.push("Board data not loaded");
    if (!hasDiff) notes.push("No gap analysis data");
    return { score, status, notes };
  }, [seoAudit, board, diffData]);

  const handleReanalyze = async () => {
    await cmd.execute("run_seo_audit");
    if (id) {
      const audits = await listSeoAudits(id, 1);
      if (audits[0]) setSeoAudit(audits[0] as Record<string, unknown>);
    }
  };

  const handleStatusChange = async (insightId: string, next: Status) => {
    if (!id) return;
    try {
      await updateInsightStatus(id, insightId, next);
    } catch (err) {
      console.warn("[InsightBoard] updateInsightStatus failed", err);
    }
  };

  const [creatingFor, setCreatingFor] = useState<string | null>(null);

  const handleCreateAction = async (insightId: string) => {
    if (!id) return;
    setCreatingFor(insightId);
    try {
      await cmd.execute("create_action_from_insight", { insightId });
    } catch (err) {
      console.warn("[InsightBoard] create_action_from_insight failed", err);
    } finally {
      setCreatingFor(null);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Action bar */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          {cmd.isRunning && (
            <span className="flex items-center gap-2 rounded-xl bg-[var(--shell-accent)]/10 px-3 py-1.5 text-xs font-medium text-[var(--shell-accent)]">
              <span className="inline-flex h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
              {cmd.message || "Analyzing..."} {cmd.progress > 0 && `(${cmd.progress}%)`}
            </span>
          )}
        </div>
        <button
          type="button"
          onClick={handleReanalyze}
          disabled={cmd.isRunning}
          className="flex items-center gap-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
        >
          <RefreshCw className={`h-3.5 w-3.5 ${cmd.isRunning ? "animate-spin" : ""}`} />
          Re-analyze
        </button>
      </div>

      {/* Summary Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={XCircle} label="Critical Issues" value={String(criticalCount)} color="text-rose-500" />
        <MetricCard icon={AlertTriangle} label="Warnings" value={String(warningCount)} color="text-amber-500" />
        <MetricCard icon={Search} label="SEO Score" value={seoScore != null ? String(seoScore) : "--"} color="text-blue-600" />
        <MetricCard icon={CheckCircle2} label="GEO Score" value={geoScore != null ? String(geoScore) : "--"} color="text-teal-600" />
      </div>

      {/* Data Quality */}
      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {/* Gap Analysis Summary */}
      {diffData && (
        <InsightSection title="Gap Analysis Summary" icon={GitCompare} defaultOpen>
          <GapSummary data={diffData} />
        </InsightSection>
      )}

      {/* Filters: severity + source + status */}
      <div className="space-y-2">
        {/* Severity + source row */}
        <div className="flex flex-wrap items-center gap-2">
          <Filter className="h-3.5 w-3.5 text-[var(--shell-text-muted)]" />
          <FilterChip label={`All (${openIssues.length})`} active={filterSource === "all" && filterSeverity === "all" && filterStatus === "all"} onClick={() => { setFilterSource("all"); setFilterSeverity("all"); setFilterStatus("all"); }} />
          <FilterChip label={`Critical (${criticalCount})`} active={filterSeverity === "critical"} onClick={() => { setFilterSeverity(filterSeverity === "critical" ? "all" : "critical"); setFilterSource("all"); setFilterStatus("all"); }} color="text-rose-500" />
          <FilterChip label={`Warnings (${warningCount})`} active={filterSeverity === "warning"} onClick={() => { setFilterSeverity(filterSeverity === "warning" ? "all" : "warning"); setFilterSource("all"); setFilterStatus("all"); }} color="text-amber-500" />
          <div className="h-4 w-px bg-[var(--shell-border)]" />
          {(Object.keys(SOURCE_LABELS) as Source[]).filter((s) => sourceCounts.has(s)).map((s) => (
            <FilterChip
              key={s}
              label={`${SOURCE_LABELS[s]} (${sourceCounts.get(s)})`}
              active={filterSource === s}
              onClick={() => { setFilterSource(filterSource === s ? "all" : s); setFilterSeverity("all"); setFilterStatus("all"); }}
            />
          ))}
        </div>

        {/* Status row */}
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Status</span>
          {(["open", "in-review", "action-created", "resolved", "ignored"] as Status[]).map((s) => (
            <FilterChip
              key={s}
              label={STATUS_LABELS[s]}
              active={filterStatus === s}
              onClick={() => { setFilterStatus(filterStatus === s ? "all" : s); setFilterSeverity("all"); setFilterSource("all"); }}
            />
          ))}
        </div>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[var(--shell-text-muted)]" />
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search issues..."
          className="w-full rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] py-2.5 pl-10 pr-4 text-sm text-[var(--shell-text)] outline-none transition-colors focus:border-[var(--shell-accent)]"
        />
      </div>

      {/* Issue list */}
      <div className="space-y-2">
        {filteredIssues.length > 0 ? (
          filteredIssues.map((issue) => (
            <IssueRow
              key={issue.id}
              issue={issue}
              expanded={expandedId === issue.id}
              onToggle={() => setExpandedId(expandedId === issue.id ? null : issue.id)}
              boardId={id}
              onStatusChange={handleStatusChange}
              onCreateAction={handleCreateAction}
              creating={creatingFor === issue.id}
            />
          ))
        ) : allIssues.length > 0 ? (
          <div className="rounded-2xl border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel)] p-8 text-center text-sm text-[var(--shell-text-muted)]">
            현재 필터에 해당하는 이슈가 없습니다. 필터를 해제하거나 새로 분석을 실행해 인사이트를 생성해 보세요.
          </div>
        ) : (
          <EmptyState
            icon={CheckCircle2}
            title="No insights yet"
            description="인사이트는 분석 실행 중 서버 워커가 생성합니다. 새로 실행하면 SEO, GEO, 신뢰도, 경쟁 신호가 채워집니다."
            action={{ label: "Run Analysis", onClick: handleReanalyze }}
          />
        )}
      </div>
    </div>
  );
}

// ── Sub-components ──────────────────────────────────────────

function GapSummary({ data }: { data: DiffData }) {
  const dimensions = data.dimensions ?? [];
  const highGapCount = dimensions.filter((d) => d.gapLevel === "HIGH").length;
  const medGapCount = dimensions.filter((d) => d.gapLevel === "MEDIUM").length;

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-4">
        <div>
          <p className="text-xs text-[var(--shell-text-muted)]">Customer Perception vs Web Reality</p>
          <div className="mt-1 text-3xl font-bold text-[var(--shell-text)]">
            {data.overallGapScore}<span className="text-base text-[var(--shell-text-muted)]">/100</span>
          </div>
        </div>
        <div className="flex gap-4 text-xs">
          <span className="text-rose-500">{highGapCount} high gap{highGapCount !== 1 ? "s" : ""}</span>
          <span className="text-amber-500">{medGapCount} medium gap{medGapCount !== 1 ? "s" : ""}</span>
        </div>
      </div>

      {data.actionPlanSummary && (
        <p className="text-sm leading-relaxed text-[var(--shell-text-muted)]">{data.actionPlanSummary}</p>
      )}

      {dimensions.length > 0 && (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {dimensions.slice(0, 6).map((dim, i) => {
            const barColor = dim.gapSeverity >= 70 ? "bg-rose-500" : dim.gapSeverity >= 35 ? "bg-amber-500" : "bg-emerald-500";
            const levelStyle = dim.gapLevel === "HIGH"
              ? "bg-rose-500/10 text-rose-500"
              : dim.gapLevel === "MEDIUM"
                ? "bg-amber-500/10 text-amber-500"
                : "bg-emerald-500/10 text-emerald-600";
            return (
              <div key={i} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
                <div className="flex items-center justify-between gap-2">
                  <span className="text-xs font-medium text-[var(--shell-text)]">{dim.dimension}</span>
                  <span className={`rounded-md px-1.5 py-0.5 text-[9px] font-medium ${levelStyle}`}>{dim.gapLevel}</span>
                </div>
                <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel)]">
                  <div className={`h-full rounded-full ${barColor}`} style={{ width: `${dim.gapSeverity}%` }} />
                </div>
                {dim.gapDescription && (
                  <p className="mt-2 line-clamp-2 text-[10px] text-[var(--shell-text-muted)]">{dim.gapDescription}</p>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function IssueRow({
  issue,
  expanded,
  onToggle,
  boardId,
  onStatusChange,
  onCreateAction,
  creating,
}: {
  issue: InsightDoc;
  expanded: boolean;
  onToggle: () => void;
  boardId?: string;
  onStatusChange: (insightId: string, next: Status) => void;
  onCreateAction: (insightId: string) => void;
  creating: boolean;
}) {
  const severityDot = issue.severity === "critical" ? "bg-rose-500" : issue.severity === "warning" ? "bg-amber-500" : "bg-blue-400";
  const severityLabel = issue.severity === "critical" ? "Critical" : issue.severity === "warning" ? "Warning" : "Info";
  const severityBg = issue.severity === "critical" ? "bg-rose-500/10 text-rose-500" : issue.severity === "warning" ? "bg-amber-500/10 text-amber-500" : "bg-blue-400/10 text-blue-500";

  return (
    <div className="overflow-hidden rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
      <button
        type="button"
        className="flex w-full items-start gap-3 p-4 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
        onClick={onToggle}
      >
        <span className={`mt-1.5 inline-block h-2 w-2 flex-shrink-0 rounded-full ${severityDot}`} />
        <div className="min-w-0 flex-1">
          <p className="text-sm font-medium text-[var(--shell-text)]">{issue.title}</p>
          <div className="mt-1.5 flex flex-wrap items-center gap-2">
            <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${severityBg}`}>
              {severityLabel}
            </span>
            <span className="rounded-md border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
              {SOURCE_LABELS[issue.source]}
            </span>
            <span className="rounded-md border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
              {STATUS_LABELS[issue.status]}
            </span>
            {issue.rule && (
              <span className="text-[10px] text-[var(--shell-text-muted)]">{issue.rule}</span>
            )}
          </div>
        </div>
        <ChevronDown className={`mt-1 h-4 w-4 shrink-0 text-[var(--shell-text-muted)] transition-transform ${expanded ? "" : "-rotate-90"}`} />
      </button>

      {expanded && (
        <div className="space-y-3 border-t border-[var(--shell-border)] p-4">
          {issue.detail && (
            <p className="text-sm leading-relaxed text-[var(--shell-text-muted)]">{issue.detail}</p>
          )}
          {issue.file && (
            <div className="text-xs text-[var(--shell-text-muted)]">
              <span className="font-medium text-[var(--shell-text)]">File:</span> {issue.file}
            </div>
          )}
          {issue.affectedPages && issue.affectedPages.length > 0 && (
            <div>
              <span className="text-xs font-medium text-[var(--shell-text)]">Affected pages:</span>
              <div className="mt-1 space-y-0.5">
                {issue.affectedPages.slice(0, 5).map((p) => (
                  <div key={p} className="truncate text-xs text-[var(--shell-text-muted)]">{p}</div>
                ))}
                {issue.affectedPages.length > 5 && (
                  <div className="text-xs text-[var(--shell-text-muted)]">+{issue.affectedPages.length - 5} more</div>
                )}
              </div>
            </div>
          )}
          {issue.suggestion && (
            <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2.5">
              <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Suggestion</div>
              <p className="text-sm leading-relaxed text-[var(--shell-text)]">{issue.suggestion}</p>
            </div>
          )}
          {boardId && (
            <div className="flex flex-wrap items-center justify-end gap-2 pt-1">
              {issue.status !== "ignored" && issue.status !== "resolved" && (
                <button
                  type="button"
                  onClick={() => onStatusChange(issue.id, "ignored")}
                  className="rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text-muted)] transition-colors hover:border-[var(--shell-text)] hover:text-[var(--shell-text)]"
                >
                  Ignore
                </button>
              )}
              {(issue.status === "ignored" || issue.status === "resolved") && (
                <button
                  type="button"
                  onClick={() => onStatusChange(issue.id, "open")}
                  className="rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text-muted)] transition-colors hover:border-[var(--shell-text)] hover:text-[var(--shell-text)]"
                >
                  Reopen
                </button>
              )}
              {issue.status === "action-created" ? (
                <Link
                  to={`/board/${boardId}/workspace/actions/recommended?fromInsight=${issue.id}`}
                  className="rounded-lg border border-[var(--shell-accent)] bg-[var(--shell-accent)]/10 px-3 py-1.5 text-xs font-medium text-[var(--shell-accent)] transition-colors hover:bg-[var(--shell-accent)]/15"
                >
                  View action
                </Link>
              ) : (
                <button
                  type="button"
                  onClick={() => onCreateAction(issue.id)}
                  disabled={creating}
                  className="rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text-muted)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
                >
                  {creating ? "Creating..." : "Create action"}
                </button>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function FilterChip({ label, active, onClick, color }: {
  label: string;
  active: boolean;
  onClick: () => void;
  color?: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
        active
          ? "bg-[var(--shell-accent)]/15 text-[var(--shell-accent)]"
          : `bg-[var(--shell-panel-soft)] ${color ?? "text-[var(--shell-text-muted)]"} hover:text-[var(--shell-text)]`
      }`}
    >
      {label}
    </button>
  );
}
