import { getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runTrackingDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // 1. actions/v3/actions
  try {
    const snap = await getDocs(query(paths.v3Actions(boardId), fbLimit(20)));
    results.push({ id: "trk-actions", label: "actions/v3/actions", status: snap.docs.length > 0 ? "pass" : "fail", detail: `${snap.docs.length}개 문서` });
  } catch (err: any) {
    results.push({ id: "trk-actions", label: "actions/v3/actions", status: "fail", detail: err.message });
  }

  // 2. raw/v1/benchmark_daily (snapshots for trend)
  try {
    const snap = await getDocs(query(paths.rawBenchmarkDaily(boardId), fbLimit(20)));
    results.push({ id: "trk-bench", label: "raw/v1/benchmark_daily", status: snap.docs.length > 0 ? "pass" : "warn", detail: `${snap.docs.length}개 문서` });
  } catch (err: any) {
    results.push({ id: "trk-bench", label: "raw/v1/benchmark_daily", status: "fail", detail: err.message });
  }

  // 3. reports/v3/weekly
  try {
    const snap = await getDocs(query(paths.v3WeeklyReports(boardId), fbLimit(5)));
    if (snap.docs.length === 0) {
      results.push({ id: "trk-weekly", label: "reports/v3/weekly", status: "fail", detail: "주간 리포트 없음" });
    } else {
      const latest = snap.docs[0].data() as any;
      results.push({ id: "trk-weekly", label: "reports/v3/weekly", status: "pass", detail: `${snap.docs.length}개 (latest weekId: ${latest?.weekId ?? "N/A"})` });
    }
  } catch (err: any) {
    results.push({ id: "trk-weekly", label: "reports/v3/weekly", status: "fail", detail: err.message });
  }

  return results;
};
