import { createContext, useContext } from 'react';
import { CACHE_KEYS, CacheKey, TTL_CONFIGS } from './localCache/cacheConfig';

export { CACHE_KEYS, TTL_CONFIGS } from './localCache/cacheConfig';
export type { CacheKey } from './localCache/cacheConfig';

export interface CacheEntry<T = any> {
  value: T;
  timestamp: number;
  ttl: number | null;
}

export interface CacheStatus {
  key: string;
  hasMemoryCache: boolean;
  hasStorageCache: boolean;
  isExpired: boolean;
  ageMs?: number;
  ttl?: number | null;
}

export interface LocalCacheContextValue {
  getString: (key: CacheKey) => Promise<string | null>;
  setString: (key: CacheKey, value: string, customTTL?: number | null) => Promise<void>;
  getNumber: (key: CacheKey) => Promise<number | null>;
  setNumber: (key: CacheKey, value: number, customTTL?: number | null) => Promise<void>;
  getBoolean: (key: CacheKey) => Promise<boolean | null>;
  setBoolean: (key: CacheKey, value: boolean, customTTL?: number | null) => Promise<void>;
  getObject: <T = any>(key: CacheKey) => Promise<T | null>;
  setObject: <T = any>(key: CacheKey, value: T, customTTL?: number | null) => Promise<void>;
  remove: (key: CacheKey) => Promise<void>;
  clearAll: () => Promise<void>;
  isExpired: (key: CacheKey) => Promise<boolean>;
  getCacheStatus: () => Promise<CacheStatus[]>;
  printCacheDebug: () => Promise<void>;
}

export const LocalCacheContext = createContext<LocalCacheContextValue | undefined>(undefined);

export const useLocalCache = () => {
  const ctx = useContext(LocalCacheContext);
  if (!ctx) throw new Error('useLocalCache must be used within a LocalCacheProvider');
  return ctx;
};

export const getCacheKeyForStorage = (key: CacheKey): string => key;

// ============================
// Web storage adapter (localStorage wrapped in async API)
// - Falls back to in-memory only when localStorage is unavailable (SSR/private mode)
// ============================
const webStorage = {
  getItem: async (key: string): Promise<string | null> => {
    try {
      if (typeof window === 'undefined' || !window.localStorage) return null;
      return window.localStorage.getItem(key);
    } catch {
      return null;
    }
  },
  setItem: async (key: string, value: string): Promise<void> => {
    try {
      if (typeof window === 'undefined' || !window.localStorage) return;
      window.localStorage.setItem(key, value);
    } catch {
      // quota / disabled — ignore, memory cache still works
    }
  },
  removeItem: async (key: string): Promise<void> => {
    try {
      if (typeof window === 'undefined' || !window.localStorage) return;
      window.localStorage.removeItem(key);
    } catch {
      // ignore
    }
  },
  multiRemove: async (keys: string[]): Promise<void> => {
    try {
      if (typeof window === 'undefined' || !window.localStorage) return;
      keys.forEach((k) => window.localStorage.removeItem(k));
    } catch {
      // ignore
    }
  },
};

const isExpiredBy = (entry: CacheEntry): boolean => {
  if (entry.ttl === null) return false;
  return Date.now() - entry.timestamp >= entry.ttl;
};

export const CacheEngine = (() => {
  const memory = new Map<CacheKey, CacheEntry>();

  const resolveTTL = (key: CacheKey, customTTL?: number | null): number | null => {
    return customTTL !== undefined ? customTTL : TTL_CONFIGS[key];
  };

  const getEntryFromMemory = (key: CacheKey): CacheEntry | undefined => {
    const entry = memory.get(key);
    if (!entry) return undefined;

    if (isExpiredBy(entry)) {
      memory.delete(key);
      return undefined;
    }
    return entry;
  };

  const readEntryFromStorage = async (key: CacheKey): Promise<CacheEntry | null> => {
    try {
      const jsonStr = await webStorage.getItem(key);
      if (!jsonStr) return null;

      const entry: CacheEntry = JSON.parse(jsonStr);

      if (isExpiredBy(entry)) {
        await webStorage.removeItem(key);
        memory.delete(key);
        return null;
      }

      memory.set(key, entry);
      return entry;
    } catch (error) {
      console.error(`Error reading from storage [${key}]:`, error);
      return null;
    }
  };

  const writeEntryToStorage = async (key: CacheKey, entry: CacheEntry) => {
    await webStorage.setItem(key, JSON.stringify(entry));
    memory.set(key, entry);
  };

  const getValue = async <T,>(key: CacheKey): Promise<T | null> => {
    const memEntry = getEntryFromMemory(key);
    if (memEntry) return memEntry.value as T;

    const stEntry = await readEntryFromStorage(key);
    if (!stEntry) return null;

    return stEntry.value as T;
  };

  const setValue = async (key: CacheKey, value: any, customTTL?: number | null): Promise<void> => {
    const ttl = resolveTTL(key, customTTL);
    const entry: CacheEntry = { value, timestamp: Date.now(), ttl };
    try {
      await writeEntryToStorage(key, entry);
    } catch (error) {
      console.error(`Error writing to storage [${key}]:`, error);
      throw error;
    }
  };

  const remove = async (key: CacheKey): Promise<void> => {
    try {
      memory.delete(key);
      await webStorage.removeItem(key);
    } catch (error) {
      console.error(`Error removing cache [${key}]:`, error);
    }
  };

  const clearAll = async (): Promise<void> => {
    try {
      memory.clear();
      const allKeys = Object.values(CACHE_KEYS);
      await webStorage.multiRemove(allKeys);
    } catch (error) {
      console.error('Error clearing all cache:', error);
    }
  };

  const isExpired = async (key: CacheKey): Promise<boolean> => {
    const memEntry = memory.get(key);
    if (memEntry) return isExpiredBy(memEntry);

    try {
      const jsonStr = await webStorage.getItem(key);
      if (!jsonStr) return true;
      const entry: CacheEntry = JSON.parse(jsonStr);
      return isExpiredBy(entry);
    } catch (error) {
      console.error(`Error checking expiration [${key}]:`, error);
      return true;
    }
  };

  const getCacheStatus = async (): Promise<CacheStatus[]> => {
    const statuses: CacheStatus[] = [];
    for (const key of Object.values(CACHE_KEYS)) {
      const memEntry = memory.get(key);
      const hasMemoryCache = memEntry !== undefined && !isExpiredBy(memEntry);

      let hasStorageCache = false;
      let isExpiredFlag = false;
      let ageMs: number | undefined;
      let ttl: number | null | undefined;

      try {
        const jsonStr = await webStorage.getItem(key);
        if (jsonStr) {
          hasStorageCache = true;
          const entry: CacheEntry = JSON.parse(jsonStr);
          isExpiredFlag = isExpiredBy(entry);
          ageMs = Date.now() - entry.timestamp;
          ttl = entry.ttl;
        }
      } catch (error) {
        console.error(`Error checking cache status for ${key}:`, error);
      }

      statuses.push({
        key,
        hasMemoryCache,
        hasStorageCache,
        isExpired: isExpiredFlag,
        ageMs,
        ttl,
      });
    }
    return statuses;
  };

  const printCacheDebug = async (): Promise<void> => {
    const statuses = await getCacheStatus();
    const rows = statuses
      .filter((s) => s.hasMemoryCache || s.hasStorageCache)
      .map((s) => ({
        key: s.key,
        memory: s.hasMemoryCache,
        storage: s.hasStorageCache,
        expired: s.isExpired,
        age: s.ageMs ? `${Math.round(s.ageMs / 1000 / 60)} mins ago` : 'N/A',
        ttl:
          s.ttl === null
            ? 'permanent'
            : s.ttl
            ? `${Math.round(s.ttl / 1000 / 60)} mins`
            : 'N/A',
      }));
    console.table(rows);
  };

  return {
    getValue,
    setValue,
    remove,
    clearAll,
    isExpired,
    getCacheStatus,
    printCacheDebug,
  };
})();

export { LocalCache, LocalCacheProvider } from './localCache/LocalCacheProvider';
