import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { User, onAuthStateChanged, signInWithPopup, signInWithEmailAndPassword, signOut as firebaseSignOut } from 'firebase/auth';
import { onSnapshot } from 'firebase/firestore';
import { auth, googleProvider } from '../config/firebase';
import { paths } from '../db/paths';
import { createOrUpdateUser, isUserAdmin, resolveUserRole, UserDoc, UserRole } from '../db/users';
import { LocalCache } from './LocalCacheContext';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  userDoc: UserDoc | null;
  role: UserRole;
  isAdmin: boolean;
  isApproved: boolean;
  signInWithGoogle: () => Promise<void>;
  signInWithEmail: (email: string, password: string) => Promise<void>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider = ({ children }: AuthProviderProps) => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [userDoc, setUserDoc] = useState<UserDoc | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [userDocReady, setUserDocReady] = useState(false);
  const [adminDocReady, setAdminDocReady] = useState(false);

  useEffect(() => {
    let unsubUser: (() => void) | null = null;
    let cancelled = false;

    const cleanupSubs = () => {
      if (unsubUser) { unsubUser(); unsubUser = null; }
    };

    const unsubscribe = onAuthStateChanged(auth, (nextUser) => {
      setUser(nextUser);
      cleanupSubs();

      if (!nextUser || !nextUser.email) {
        setUserDoc(null);
        setIsAdmin(false);
        setUserDocReady(true);
        setAdminDocReady(true);
        setAuthLoading(false);
        return;
      }

      setUserDocReady(false);
      setAdminDocReady(false);

      const sessionUid = nextUser.uid;

      (async () => {
        try {
          await createOrUpdateUser(
            nextUser.uid,
            nextUser.email!,
            nextUser.displayName || undefined,
            nextUser.photoURL || undefined,
          );
        } catch (error) {
          console.error('Error saving user to database:', error);
        }

        unsubUser = onSnapshot(
          paths.user(sessionUid),
          (snap) => {
            setUserDoc(snap.exists() ? (snap.data() as UserDoc) : null);
            setUserDocReady(true);
          },
          (error) => {
            console.error('Error subscribing to user doc:', error);
            setUserDoc(null);
            setUserDocReady(true);
          },
        );

        try {
          const admin = await isUserAdmin(sessionUid);
          if (auth.currentUser?.uid === sessionUid && !cancelled) {
            setIsAdmin(admin);
          }
        } catch (error) {
          console.error('Error checking admin status:', error);
          if (auth.currentUser?.uid === sessionUid && !cancelled) {
            setIsAdmin(false);
          }
        } finally {
          if (auth.currentUser?.uid === sessionUid && !cancelled) {
            setAdminDocReady(true);
          }
        }

        setAuthLoading(false);
      })();
    });

    return () => {
      cancelled = true;
      cleanupSubs();
      unsubscribe();
    };
  }, []);

  const signInWithGoogle = async () => {
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (error) {
      console.error('Error signing in with Google:', error);
      throw error;
    }
  };

  const signInWithEmail = async (email: string, password: string) => {
    try {
      await signInWithEmailAndPassword(auth, email, password);
    } catch (error) {
      console.error('Error signing in with email:', error);
      throw error;
    }
  };

  const signOut = async () => {
    try {
      await firebaseSignOut(auth);
      await LocalCache.clearAll();
    } catch (error) {
      console.error('Error signing out:', error);
      throw error;
    }
  };

  const role = resolveUserRole(userDoc);
  const isApproved = isAdmin || role === 'member';
  const loading = authLoading || (!!user && (!userDocReady || !adminDocReady));

  const value = {
    user,
    loading,
    userDoc,
    role,
    isAdmin,
    isApproved,
    signInWithGoogle,
    signInWithEmail,
    signOut,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
