import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import {
  AlertTriangle, Check, FileText, Lightbulb, Monitor, Search, Shield, Star, Wrench, X,
} from "lucide-react";
import { listSeoAudits, getSummary, subscribeBoard, subscribeInsights } from "../../../db/boards";
import type { Board, InsightDoc } from "../../../db/collections";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";

// ── Types ──────────────────────────────────────────────────

interface Violation {
  rule: string;
  file: string;
  severity: "error" | "warning";
  message: string;
  suggestion?: string;
}

interface SeoCheck {
  rule: string;
  label?: string;
  status: "pass" | "warn" | "fail";
  message?: string;
  affectedPages?: string[];
}

interface HostVariantCheck {
  host: string;
  reachable: boolean;
  status: number | null;
  finalHost: string | null;
}

interface SeoAuditData {
  seoScore: number;
  /** @deprecated legacy field; use seoScore. Read path keeps fallback for existing docs. */
  score?: number;
  geoScore: number;
  errors: number;
  warnings: number;
  totalViolations: number;
  violations: Violation[];
  checks: SeoCheck[];
  geoChecks: Array<{ rule: string; label?: string; status: "pass" | "warn" | "fail"; message?: string; score?: number }>;
  categories: Record<string, { errors: number; warnings: number }>;
  siteChecks?: Record<string, unknown> & {
    hostVariants?: { apex: HostVariantCheck; www: HostVariantCheck } | null;
  };
}

type SubTab = "seo" | "tech" | "geo-readiness";

// ── Rule labels ────────────────────────────────────────────

const RULE_LABELS: Record<string, string> = {
  "geo-missing-source-citations": "Source Citations Missing",
  "geo-missing-expert-quotes": "No Expert Quotes",
  "geo-low-citation-density": "Low Citation Density",
  "geo-missing-author": "Author Info Missing",
  "geo-author-not-person": "Author Not a Person",
  "geo-passive-voice-excess": "Excessive Passive Voice",
  "geo-sentence-too-long": "Sentence Length Exceeded",
  "geo-weak-lead-sentences": "Weak Lead Sentences",
  "content-too-short": "Content Too Short",
  "geo-no-question-headings": "No Question Headings",
  "geo-missing-faq-section": "FAQ Section Missing",
  "schema-org-missing": "No Structured Data",
  "geo-missing-table": "No Data Tables",
  "geo-missing-lists": "No Lists",
  "geo-low-internal-links": "Low Internal Links",
  "geo-missing-tldr": "No TL;DR",
  "geo-missing-summary-section": "Summary Section Missing",
  "geo-llms-discovery": "AI Crawler Discoverability",
  "geo-answer-depth-coverage": "Answer Depth Coverage",
  "geo-question-answer-coverage": "Q&A Structure Coverage",
  "geo-evidence-citation-coverage": "Evidence & Trust Signals",
  "geo-entity-schema-coverage": "Entity Schema Coverage",
  "geo-authority-signal-coverage": "Authority Signals",
  "geo-freshness-coverage": "Freshness Signals",
};

// ── Component ──────────────────────────────────────────────

export function WebsiteHealthInsight() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [audit, setAudit] = useState<SeoAuditData | null>(null);
  const [contentDoc, setContentDoc] = useState<Record<string, unknown> | null>(null);
  const [insightCards, setInsightCards] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);
  const [subTab, setSubTab] = useState<SubTab>("seo");

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubInsights = subscribeInsights(id, setInsightCards, {
      source: "seo",
    });
    Promise.all([
      listSeoAudits(id, 1),
      getSummary(id, "content-quality").catch(() => null),
    ]).then(([audits, cDoc]) => {
      if (audits[0]) setAudit(audits[0] as unknown as SeoAuditData);
      setContentDoc(cDoc);
      setLoading(false);
    });
    return () => {
      unsubBoard();
      unsubInsights();
    };
  }, [id]);

  const openInsightCards = useMemo(
    () => insightCards.filter((i) => i.status !== "resolved" && i.status !== "ignored"),
    [insightCards],
  );

  // ── Derived: GEO Readiness ──

  const siteFiles = board?.siteInfo?.siteFiles;
  const aiCrawlers = board?.siteInfo?.aiCrawlers;

  const geoReadiness = useMemo(() => {
    const items: Array<{ label: string; ok: boolean; detail: string }> = [];
    if (siteFiles) {
      items.push({
        label: "robots.txt",
        ok: siteFiles.robots?.exists ?? false,
        detail: siteFiles.robots?.exists ? (siteFiles.robots.needsImprovement ? "Exists but needs improvement" : "Present and valid") : "Missing",
      });
      items.push({
        label: "sitemap.xml",
        ok: siteFiles.sitemap?.exists ?? false,
        detail: siteFiles.sitemap?.exists ? (siteFiles.sitemap.hasLastmod ? "Valid with lastmod dates" : "Present but missing lastmod") : "Missing",
      });
      items.push({
        label: "llms.txt",
        ok: siteFiles.llms?.exists ?? false,
        detail: siteFiles.llms?.exists ? "Present for AI crawlers" : "Missing - AI crawlers cannot discover structured content",
      });
      items.push({
        label: "RSS feed",
        ok: siteFiles.rss?.exists ?? false,
        detail: siteFiles.rss?.exists ? "Present for content freshness signals" : "Missing",
      });
    }
    if (aiCrawlers?.crawlers) {
      const blocked = aiCrawlers.crawlers.filter((c) => c.status === "blocked");
      items.push({
        label: "AI Crawler Access",
        ok: blocked.length === 0,
        detail: blocked.length > 0 ? `${blocked.length} AI crawler${blocked.length !== 1 ? "s" : ""} blocked: ${blocked.map((c) => c.name).join(", ")}` : "All AI crawlers allowed",
      });
    }
    const hv = audit?.siteChecks?.hostVariants;
    if (hv) {
      const { apex, www } = hv;
      const statusText = (c: HostVariantCheck) =>
        c.reachable
          ? `${c.host} reachable (status ${c.status ?? "?"}${c.finalHost && c.finalHost !== c.host ? `, redirects to ${c.finalHost}` : ""})`
          : `${c.host} not responding${c.status ? ` (status ${c.status})` : ""}`;
      items.push({ label: `Apex host (${apex.host})`, ok: apex.reachable, detail: statusText(apex) });
      items.push({ label: `WWW host (${www.host})`, ok: www.reachable, detail: statusText(www) });
      if (apex.reachable && www.reachable && apex.finalHost && www.finalHost && apex.finalHost !== www.finalHost) {
        items.push({
          label: "www ↔ non-www canonical redirect",
          ok: false,
          detail: `Both hosts respond but resolve to different canonical hosts (apex → ${apex.finalHost}, www → ${www.finalHost}). Add a 301 from one to the other.`,
        });
      }
    }
    return items;
  }, [siteFiles, aiCrawlers, audit]);

  // ── Derived: Diagnosis ──

  const diagnosis = useMemo(() => {
    const items: Array<{ severity: "high" | "medium" | "low"; title: string; detail: string }> = [];

    if (audit) {
      if (audit.errors > 0) {
        items.push({
          severity: "high",
          title: `${audit.errors} SEO error${audit.errors !== 1 ? "s" : ""} found`,
          detail: "Critical issues that may impact search engine indexing and ranking.",
        });
      }
      if ((audit.seoScore ?? audit.score ?? 0) < 50) {
        items.push({
          severity: "high",
          title: `Low SEO score: ${(audit.seoScore ?? audit.score ?? 0)}/100`,
          detail: "Score below 50 indicates significant SEO issues requiring immediate attention.",
        });
      }
      if (audit.geoScore < 40) {
        items.push({
          severity: "medium",
          title: `Low GEO score: ${audit.geoScore}/100`,
          detail: "Content is not well-optimized for AI search engines.",
        });
      }
    }

    if (siteFiles) {
      if (!siteFiles.llms?.exists) {
        items.push({
          severity: "medium",
          title: "llms.txt not found",
          detail: "AI crawlers use llms.txt to discover structured content. Adding one can improve AI visibility.",
        });
      }
      if (!siteFiles.sitemap?.exists) {
        items.push({
          severity: "medium",
          title: "Sitemap not found",
          detail: "A sitemap.xml is essential for search engine crawling.",
        });
      }
    }

    if (!audit && !siteFiles) {
      items.push({
        severity: "medium",
        title: "No website health data available",
        detail: "Run a full analysis to get SEO, GEO, and technical health data.",
      });
    }

    return items;
  }, [audit, siteFiles]);

  // ── Derived: Generated Insights ──

  const insights = useMemo(() => {
    const result: Array<{ severity: "high" | "medium" | "low"; title: string; explanation: string }> = [];

    if (audit?.categories) {
      const worst = Object.entries(audit.categories).sort((a, b) => (b[1].errors + b[1].warnings) - (a[1].errors + a[1].warnings))[0];
      if (worst && (worst[1].errors + worst[1].warnings) > 3) {
        result.push({
          severity: "medium",
          title: `"${worst[0]}" has the most issues`,
          explanation: `${worst[1].errors} errors and ${worst[1].warnings} warnings. Focus improvements here for the biggest impact.`,
        });
      }
    }

    if (audit?.violations) {
      const errorViolations = audit.violations.filter((v) => v.severity === "error");
      const withSuggestions = errorViolations.filter((v) => v.suggestion);
      if (withSuggestions.length > 0) {
        result.push({
          severity: "low",
          title: `${withSuggestions.length} critical issues have auto-fix suggestions`,
          explanation: "Review the Technical Checks tab for specific fix recommendations.",
        });
      }
    }

    if (geoReadiness.length > 0) {
      const failCount = geoReadiness.filter((i) => !i.ok).length;
      if (failCount >= 3) {
        result.push({
          severity: "high",
          title: `${failCount}/${geoReadiness.length} GEO readiness checks failing`,
          explanation: "Multiple missing technical prerequisites for AI search visibility.",
        });
      }
    }

    return result;
  }, [audit, geoReadiness]);

  // ── Derived: Data Quality ──

  const dataQuality = useMemo(() => {
    const hasAudit = !!audit;
    const hasBoard = !!board;
    const hasContent = !!contentDoc;
    const count = [hasAudit, hasBoard, hasContent].filter(Boolean).length;
    const score = Math.round((count / 3) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes: string[] = [];
    if (!hasAudit) notes.push("No SEO/GEO audit data");
    if (!hasBoard) notes.push("Board data not loaded");
    if (!hasContent) notes.push("No content analysis available");
    return { score, status, notes };
  }, [audit, board, contentDoc]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  const seoScore = audit?.seoScore ?? audit?.score ?? 0;
  const geoScore = audit?.geoScore ?? 0;
  const errorCount = audit?.errors ?? 0;
  const warnCount = audit?.warnings ?? 0;

  return (
    <div className="space-y-6">
      {/* Summary Metrics */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Search} label="SEO Score" value={String(seoScore)} color={seoScore >= 70 ? "text-emerald-600" : seoScore >= 40 ? "text-amber-500" : "text-rose-500"} />
        <MetricCard icon={Star} label="GEO Score" value={String(geoScore)} color={geoScore >= 70 ? "text-emerald-600" : geoScore >= 40 ? "text-amber-500" : "text-rose-500"} />
        <MetricCard icon={X} label="Errors" value={String(errorCount)} color="text-rose-500" />
        <MetricCard icon={AlertTriangle} label="Warnings" value={String(warnCount)} color="text-amber-500" />
      </div>

      {/* Data Quality */}
      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {openInsightCards.length > 0 && (
        <InsightSection title="Open Issues" icon={AlertTriangle} count={openInsightCards.length} defaultOpen>
          <div className="space-y-2">
            {openInsightCards.slice(0, 15).map((ins) => (
              <div key={ins.id} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{ins.title}</p>
                  <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                    ins.severity === "critical" ? "bg-rose-500/10 text-rose-500"
                      : ins.severity === "warning" ? "bg-amber-500/10 text-amber-500"
                      : "bg-blue-400/10 text-blue-500"
                  }`}>
                    {ins.severity}
                  </span>
                </div>
                {ins.summary && (
                  <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{ins.summary}</p>
                )}
                {ins.suggestion && (
                  <p className="mt-1 text-xs text-[var(--shell-text)]">{ins.suggestion}</p>
                )}
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {/* Raw Data: Sub-tabs */}
      <InsightSection title="Detailed Checks" icon={Monitor} defaultOpen>
        <div className="flex gap-1 border-b border-[var(--shell-border)]">
          {([
            { key: "seo" as SubTab, label: "SEO Checks" },
            { key: "tech" as SubTab, label: "Technical Violations" },
            { key: "geo-readiness" as SubTab, label: "GEO Readiness" },
          ]).map((t) => (
            <button
              key={t.key}
              onClick={() => setSubTab(t.key)}
              className={`border-b-2 px-4 py-2.5 text-xs font-medium transition-colors ${
                subTab === t.key
                  ? "border-[var(--shell-accent)] text-[var(--shell-accent)]"
                  : "border-transparent text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
        <div className="mt-4">
          {subTab === "seo" && <SeoChecksPanel audit={audit} />}
          {subTab === "tech" && <TechViolationsPanel audit={audit} />}
          {subTab === "geo-readiness" && <GeoReadinessPanel items={geoReadiness} />}
        </div>
      </InsightSection>

      {/* Raw Data: Site Checks */}
      {audit?.siteChecks && (
        <InsightSection title="Site Checks" icon={Shield} count={Object.keys(audit.siteChecks).length} defaultOpen>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {Object.entries(audit.siteChecks)
              .filter(([key]) => key !== "hostVariants")
              .map(([key, val]) => (
                <div key={key} className="flex items-center gap-2.5 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                  <span className={`inline-flex h-2.5 w-2.5 rounded-full ${val ? "bg-emerald-500" : "bg-rose-500"}`} />
                  <span className="text-sm text-[var(--shell-text)]">{key.replace(/^has/, "")}</span>
                </div>
              ))}
          </div>
          {audit.siteChecks.hostVariants && (
            <div className="mt-3 grid gap-3 sm:grid-cols-2">
              {(["apex", "www"] as const).map((k) => {
                const v = audit.siteChecks!.hostVariants![k];
                return (
                  <div key={k} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                    <div className="flex items-center gap-2.5">
                      <span className={`inline-flex h-2.5 w-2.5 rounded-full ${v.reachable ? "bg-emerald-500" : "bg-rose-500"}`} />
                      <span className="text-sm font-medium text-[var(--shell-text)]">{k === "apex" ? "non-www" : "www"} — {v.host}</span>
                    </div>
                    <p className="mt-1 pl-5 text-xs text-[var(--shell-text-muted)]">
                      {v.reachable
                        ? `status ${v.status ?? "?"}${v.finalHost && v.finalHost !== v.host ? ` → ${v.finalHost}` : ""}`
                        : `not responding${v.status ? ` (status ${v.status})` : ""}`}
                    </p>
                  </div>
                );
              })}
            </div>
          )}
        </InsightSection>
      )}

      {/* Raw Data: Category Breakdown */}
      {audit?.categories && Object.keys(audit.categories).length > 0 && (
        <InsightSection title="Category Breakdown" icon={FileText} count={Object.keys(audit.categories).length} defaultOpen={false}>
          <div className="space-y-2">
            {Object.entries(audit.categories).map(([cat, counts]) => (
              <div key={cat} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <span className="text-sm text-[var(--shell-text)]">{cat}</span>
                <div className="flex items-center gap-3 text-xs">
                  <span className="text-rose-500">{counts.errors} errors</span>
                  <span className="text-amber-500">{counts.warnings} warnings</span>
                  <span className="text-[var(--shell-text-muted)]">Total {counts.errors + counts.warnings}</span>
                </div>
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {/* Diagnosis */}
      <InsightSection title="Diagnosis" icon={AlertTriangle} count={diagnosis.length} defaultOpen={diagnosis.length > 0}>
        {diagnosis.length > 0 ? (
          <div className="space-y-2">
            {diagnosis.map((item, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={item.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No diagnostic issues found</p>
        )}
      </InsightSection>

      {/* Generated Insights */}
      <InsightSection title="Generated Insights" icon={Lightbulb} count={insights.length} defaultOpen={false}>
        {insights.length > 0 ? (
          <div className="space-y-2">
            {insights.map((insight, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={insight.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{insight.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{insight.explanation}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No insights generated yet. Audit data will produce insights here.</p>
        )}
      </InsightSection>
    </div>
  );
}

// ── Sub-tab Panels ─────────────────────────────────────────

function SeoChecksPanel({ audit }: { audit: SeoAuditData | null }) {
  const [expandedRule, setExpandedRule] = useState<string | null>(null);

  if (!audit || !audit.checks || audit.checks.length === 0) {
    return <EmptyState icon={Search} title="No SEO checks" description="분석을 실행하면 SEO 진단 결과를 볼 수 있습니다" />;
  }

  const checks = audit.checks;
  const passCount = checks.filter((c) => c.status === "pass").length;
  const warnCount = checks.filter((c) => c.status === "warn").length;
  const failCount = checks.filter((c) => c.status === "fail").length;

  return (
    <div className="space-y-3">
      <div className="flex gap-3 text-xs">
        <span className="text-emerald-600">{passCount} passed</span>
        <span className="text-amber-500">{warnCount} warnings</span>
        <span className="text-rose-500">{failCount} issues</span>
      </div>

      <div className="space-y-2">
        {checks.map((check) => {
          const expanded = expandedRule === check.rule;
          return (
            <div key={check.rule} className="overflow-hidden rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
              <button
                type="button"
                onClick={() => setExpandedRule(expanded ? null : check.rule)}
                className="flex w-full items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-[var(--shell-panel-soft)]"
              >
                <span className={`inline-block h-2 w-2 shrink-0 rounded-full ${
                  check.status === "pass" ? "bg-emerald-500" : check.status === "warn" ? "bg-amber-500" : "bg-rose-500"
                }`} />
                <span className="flex-1 text-sm text-[var(--shell-text)]">{check.label || check.rule}</span>
                <span className={`text-[11px] uppercase tracking-wider ${
                  check.status === "pass" ? "text-emerald-600" : check.status === "warn" ? "text-amber-500" : "text-rose-500"
                }`}>{check.status}</span>
              </button>
              {expanded && check.message && (
                <div className="border-t border-[var(--shell-border)] px-4 py-3 text-xs leading-relaxed text-[var(--shell-text-muted)]">
                  {check.message}
                  {check.affectedPages && check.affectedPages.length > 0 && (
                    <div className="mt-2">
                      <span className="font-medium text-[var(--shell-text)]">Affected pages:</span>
                      {check.affectedPages.slice(0, 5).map((p) => (
                        <div key={p} className="mt-0.5 truncate">{p}</div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function TechViolationsPanel({ audit }: { audit: SeoAuditData | null }) {
  const violations = audit?.violations ?? [];

  if (violations.length === 0) {
    return <EmptyState icon={Check} title="No violations found" description="모든 기술 항목이 통과되었습니다" />;
  }

  return (
    <div className="space-y-2">
      {violations.map((v, i) => (
        <div key={`${v.rule}-${i}`} className="overflow-hidden rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <span className={`inline-block h-2.5 w-2.5 rounded-full ${v.severity === "error" ? "bg-rose-500" : "bg-amber-500"}`} />
              <span className="text-sm font-medium text-[var(--shell-text)]">{RULE_LABELS[v.rule] || v.rule}</span>
            </div>
            <span className={`rounded-md px-2 py-0.5 text-[10px] font-medium ${
              v.severity === "error" ? "bg-rose-500/10 text-rose-500" : "bg-amber-500/10 text-amber-500"
            }`}>{v.severity === "error" ? "Critical" : "Warning"}</span>
          </div>
          <p className="mt-2 text-xs text-[var(--shell-text-muted)]">{v.message}</p>
          {v.suggestion && (
            <div className="mt-2 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2.5">
              <div className="mb-0.5 text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Suggestion</div>
              <p className="text-xs text-[var(--shell-text)]">{v.suggestion}</p>
            </div>
          )}
          {v.file && <p className="mt-2 truncate text-[10px] text-[var(--shell-text-muted)]">{v.file}</p>}
        </div>
      ))}
    </div>
  );
}

function GeoReadinessPanel({ items }: { items: Array<{ label: string; ok: boolean; detail: string }> }) {
  if (items.length === 0) {
    return <EmptyState icon={Wrench} title="No GEO readiness data" description="보드의 사이트 정보가 아직 없습니다. 분석을 실행하면 AI 대응 준비도를 점검합니다." />;
  }

  return (
    <div className="space-y-2">
      {items.map((item) => (
        <div key={item.label} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
          {item.ok
            ? <Check className="mt-0.5 h-4 w-4 shrink-0 text-emerald-600" />
            : <X className="mt-0.5 h-4 w-4 shrink-0 text-rose-500" />}
          <div className="min-w-0 flex-1">
            <p className="text-sm font-medium text-[var(--shell-text)]">{item.label}</p>
            <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
          </div>
        </div>
      ))}
    </div>
  );
}

// ── Shared sub-components ──────────────────────────────────

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}
