import type {
  ExposureData,
  DiagnosisData,
  ImprovementData,
  TrackingData,
  ReportData,
  WebsiteData,
} from "./types";

export function toExposureData(raw: {
  latest: { run: Record<string, unknown> | null; analysis: any | null };
  runs: any[];
  brand: any | null;
  snapshots: any[];
}): ExposureData {
  const analysis = raw.latest.analysis;
  const run = raw.latest.run;

  const engineBreakdown = analysis?.engineBreakdown ?? {};
  const gptInfo = engineBreakdown.gpt ?? engineBreakdown.chatgpt ?? {};
  const geminiInfo = engineBreakdown.gemini ?? {};

  const gptSamples = Number(gptInfo.samples ?? gptInfo.totalQuestions ?? 0);
  const geminiSamples = Number(geminiInfo.samples ?? geminiInfo.totalQuestions ?? 0);
  const gptRate = Number(gptInfo.mentionRate ?? 0);
  const geminiRate = Number(geminiInfo.mentionRate ?? 0);

  const competitorBreakdown = Array.isArray(analysis?.competitorBreakdown)
    ? analysis.competitorBreakdown.map((c: any) => ({
        name: String(c.name ?? ""),
        mentionCount: Number(c.mentionCount ?? 0),
        mentionRate: Number(c.mentionRate ?? 0),
      }))
    : [];

  const sentimentBreakdown = analysis?.sentimentBreakdown ?? { positive: 0, neutral: 0, negative: 0 };

  const queryBreakdown = Array.isArray(analysis?.queryBreakdown)
    ? analysis.queryBreakdown.map((q: any) => ({
        queryIndex: Number(q.queryIndex ?? 0),
        queryText: String(q.queryText ?? ""),
        category: q.category ?? undefined,
        gptRate: Number(q.gptRate ?? 0),
        geminiRate: Number(q.geminiRate ?? 0),
        mentionRate: Number(q.mentionRate ?? 0),
        avgMentionPosition: q.avgMentionPosition ?? null,
      }))
    : [];

  const trendPoints = raw.snapshots
    .sort((a, b) => (a.capturedAt ?? "").localeCompare(b.capturedAt ?? ""))
    .map((s: any) => {
      const eb = Array.isArray(s.engineBreakdown) ? s.engineBreakdown : [];
      const gptSnap = eb.find((e: any) => e.engine === "gpt" || e.engine === "chatgpt");
      const geminiSnap = eb.find((e: any) => e.engine === "gemini");
      return {
        date: String(s.capturedAt ?? ""),
        runId: String(s.id ?? ""),
        brandRate: Number(s.mentionRate ?? s.metrics?.mentionRate ?? 0),
        gptRate: Number(gptSnap?.mentionRate ?? 0),
        geminiRate: Number(geminiSnap?.mentionRate ?? 0),
      };
    });

  const completedAt = run?.completedAt;
  const measuredAt = completedAt
    ? (typeof completedAt === "string" ? completedAt : new Date().toISOString())
    : new Date().toISOString();

  const dates = trendPoints.map((t) => t.date).filter(Boolean).sort();
  const periodStart = dates[0] ?? undefined;
  const periodEnd = dates[dates.length - 1] ?? undefined;

  return {
    geoScore: Number(analysis?.geoScore ?? 0),
    brandMentionRate: Number(analysis?.brandMentionRate ?? 0),
    engineBreakdown: {
      gpt: { rate: gptRate, total: gptSamples, mentioned: Math.round(gptSamples * gptRate / 100) },
      gemini: { rate: geminiRate, total: geminiSamples, mentioned: Math.round(geminiSamples * geminiRate / 100) },
    },
    competitorBreakdown,
    sentimentBreakdown: {
      positive: Number(sentimentBreakdown.positive ?? 0),
      neutral: Number(sentimentBreakdown.neutral ?? 0),
      negative: Number(sentimentBreakdown.negative ?? 0),
    },
    trendPoints,
    queryBreakdown,
    measuredAt,
    periodStart,
    periodEnd,
    totalCalls: gptSamples + geminiSamples,
  };
}

export function toDiagnosisData(raw: {
  latest: { run: Record<string, unknown> | null; analysis: any | null };
  results: Record<string, unknown>[];
  runs: any[];
  runId?: string;
}): DiagnosisData {
  const analysis = raw.latest.analysis;
  const queryBreakdown: any[] = analysis?.queryBreakdown ?? [];

  const queries = queryBreakdown.map((q: any) => ({
    queryIndex: Number(q.queryIndex ?? 0),
    queryText: String(q.queryText ?? ""),
    category: String(q.category ?? ""),
    gptRate: Number(q.gptRate ?? 0),
    geminiRate: Number(q.geminiRate ?? 0),
    mentionRate: Number(q.mentionRate ?? 0),
    rank: q.avgMentionPosition != null ? Number(q.avgMentionPosition) : null,
  }));

  const rawAnswers = raw.results.map((r: any) => ({
    queryIndex: Number(r.queryIndex ?? 0),
    queryText: String(r.queryText ?? ""),
    engine: (r.engine === "gemini" ? "gemini" : "gpt") as "gpt" | "gemini",
    answerText: String(r.answerText ?? ""),
    brandMentioned: Boolean(r.brandMentioned),
    mentionPosition: Number(r.mentionPosition ?? 0),
    sentiment: (r.sentiment ?? "neutral") as "positive" | "neutral" | "negative",
  }));

  const categoryGaps = buildCategoryGaps(queryBreakdown);

  const diagnosticCards = buildDiagnosticCards(categoryGaps, queries);

  return { queries, rawAnswers, categoryGaps, diagnosticCards };
}

function buildCategoryGaps(queryBreakdown: any[]) {
  const categoryMap = new Map<string, { total: number; notExposed: number; label: string }>();
  const labelMap: Record<string, string> = {
    DISCOVER: "탐색",
    CONSIDER: "비교\u00B7검토",
    DECIDE: "선택",
    ADVOCATE: "추천\u00B7확산",
  };

  for (const q of queryBreakdown) {
    const cat = String(q.category ?? "OTHER");
    if (!categoryMap.has(cat)) {
      categoryMap.set(cat, { total: 0, notExposed: 0, label: labelMap[cat] ?? cat });
    }
    const entry = categoryMap.get(cat)!;
    entry.total++;
    if (Number(q.mentionRate ?? 0) === 0) entry.notExposed++;
  }

  return Array.from(categoryMap.entries())
    .map(([category, { total, notExposed, label }]) => ({
      category,
      categoryLabel: label,
      notExposedCount: notExposed,
      totalCount: total,
      gap: total > 0 ? (notExposed / total) * 100 : 0,
    }))
    .sort((a, b) => b.gap - a.gap);
}

function buildDiagnosticCards(
  categoryGaps: { category: string; categoryLabel: string; notExposedCount: number; totalCount: number; gap: number }[],
  queries: { mentionRate: number }[],
) {
  const totalNotExposed = queries.filter((q) => q.mentionRate === 0).length;
  const worstGap = categoryGaps[0];

  const cards: { type: "status" | "problem" | "focus"; title: string; description: string }[] = [
    {
      type: "status",
      title: `${totalNotExposed}개 질문 미노출`,
      description: `${queries.length}개 질문 중 ${totalNotExposed}개에서 브랜드가 언급되지 않았습니다.`,
    },
  ];

  if (worstGap && worstGap.gap > 0) {
    cards.push({
      type: "problem",
      title: `${worstGap.categoryLabel} 단계 공백`,
      description: `${worstGap.categoryLabel} 의도 질문에서 브랜드가 후보군에 포함되지 않고 있습니다.`,
    });
  }

  cards.push({
    type: "focus",
    title: "근거 콘텐츠 보강",
    description: "비교\u00B7판단 기준이 되는 근거 콘텐츠가 필요합니다.",
  });

  return cards;
}

export function toImprovementData(raw: {
  recommendations: any[];
  groups: any;
  counts: any;
  aiSearch: any | null;
  plan: any | null;
}): ImprovementData {
  const aiSearch = raw.aiSearch;
  const plan = raw.plan;

  const diagnosisBanner = aiSearch?.diagnosisBanner ?? plan?.diagnosisBanner ?? {
    headline: "",
    gapSummary: "",
  };

  const tasks = (plan?.tasks ?? raw.recommendations).map((t: any) => ({
    id: String(t.id ?? ""),
    priority: (t.priority ?? "P2") as "P1" | "P2" | "P3",
    title: String(t.title ?? ""),
    description: String(t.description ?? ""),
    category: (t.category ?? "other") as any,
    impactScore: Number(t.impactScore ?? 0),
    effortScore: Number(t.effortScore ?? 0),
    expectedDelta: t.expectedDelta ?? undefined,
    relatedQueries: t.relatedQueries ?? undefined,
  }));

  const candidates = Array.isArray(plan?.candidates)
    ? plan.candidates.map((c: any) => ({
        id: String(c.id ?? ""),
        title: String(c.title ?? ""),
        type: String(c.type ?? ""),
        targetQuery: String(c.targetQuery ?? ""),
      }))
    : [];

  const timeline = Array.isArray(plan?.timeline)
    ? plan.timeline.map((t: any) => ({
        weekLabel: String(t.weekLabel ?? ""),
        tasks: Array.isArray(t.tasks) ? t.tasks.map(String) : [],
      }))
    : [];

  return { diagnosisBanner, tasks, candidates, timeline };
}

export function toTrackingData(raw: {
  actions: any;
  completedRuns: any[];
  weeklyReport: any | null;
  perRunAnalyses?: Record<string, Record<string, unknown>>;
  perRunResults?: Record<string, Record<string, unknown>[]>;
}): TrackingData {
  const runs: any[] = raw.completedRuns ?? [];

  const rounds = runs.map((run: any) => {
    const analysis = raw.perRunAnalyses?.[run.id];
    const eb = (analysis?.engineBreakdown ?? {}) as Record<string, any>;
    const gptInfo = eb.gpt ?? eb.chatgpt ?? {};
    const geminiInfo = eb.gemini ?? {};

    const brandRate = Number(analysis?.brandMentionRate ?? 0);
    const gptRate = Number(gptInfo.mentionRate ?? gptInfo.rate ?? 0);
    const geminiRate = Number(geminiInfo.mentionRate ?? geminiInfo.rate ?? 0);
    const totalCalls = Number(run.totalItems ?? run.totalCalls ?? 0);

    const completedAt = run.completedAt;
    const date = completedAt instanceof Date
      ? completedAt.toISOString()
      : typeof completedAt === "string" ? completedAt : "";

    return {
      runId: String(run.id ?? ""),
      date,
      brandRate,
      gptRate,
      geminiRate,
      totalCalls,
    };
  });

  const actionList = raw.actions?.actions ?? [];
  const executionItems = actionList.map((a: any) => {
    const statusMap: Record<string, string> = {
      in_progress: "진행 중",
      planned: "작성 필요",
      completed: "검토 필요",
    };
    return {
      title: String(a.title ?? ""),
      status: (statusMap[a.status] ?? "대기") as any,
      category: String(a.category ?? ""),
    };
  });

  const changeCriteria = buildChangeCriteria(rounds);

  const queryRoundTable = buildQueryRoundTable(rounds, raw.perRunResults);

  return { rounds, queryRoundTable, executionItems, changeCriteria };
}

function buildChangeCriteria(rounds: { runId: string; brandRate: number; gptRate: number; geminiRate: number }[]) {
  if (rounds.length < 2) {
    return [
      { metric: "자사 언급률 (통합)", before: 0, after: rounds[0]?.brandRate ?? 0, delta: rounds[0]?.brandRate ?? 0 },
      { metric: "ChatGPT 노출률", before: 0, after: rounds[0]?.gptRate ?? 0, delta: rounds[0]?.gptRate ?? 0 },
      { metric: "Gemini 노출률", before: 0, after: rounds[0]?.geminiRate ?? 0, delta: rounds[0]?.geminiRate ?? 0 },
    ];
  }
  const first = rounds[0];
  const last = rounds[rounds.length - 1];
  return [
    { metric: "자사 언급률 (통합)", before: first.brandRate, after: last.brandRate, delta: last.brandRate - first.brandRate },
    { metric: "ChatGPT 노출률", before: first.gptRate, after: last.gptRate, delta: last.gptRate - first.gptRate },
    { metric: "Gemini 노출률", before: first.geminiRate, after: last.geminiRate, delta: last.geminiRate - first.geminiRate },
    { metric: "노출 질문 수", before: 0, after: 0, delta: 0 },
  ];
}

function buildQueryRoundTable(
  rounds: { runId: string; date: string }[],
  perRunResults?: Record<string, Record<string, unknown>[]>,
) {
  if (!perRunResults || Object.keys(perRunResults).length === 0) {
    return [] as { queryText: string; rates: { runId: string; rate: number }[] }[];
  }

  const runOrder = rounds.map((r) => r.runId).filter((rid) => rid in perRunResults);

  const queryMap = new Map<string, Map<string, { mentioned: number; total: number }>>();

  for (const runId of runOrder) {
    const results = perRunResults[runId];
    if (!results) continue;
    for (const r of results) {
      const queryText = String(r.queryText ?? "");
      if (!queryText) continue;
      if (!queryMap.has(queryText)) queryMap.set(queryText, new Map());
      const runMap = queryMap.get(queryText)!;
      if (!runMap.has(runId)) runMap.set(runId, { mentioned: 0, total: 0 });
      const entry = runMap.get(runId)!;
      entry.total++;
      if (r.brandMentioned) entry.mentioned++;
    }
  }

  return Array.from(queryMap.entries()).map(([queryText, runMap]) => ({
    queryText,
    rates: runOrder
      .filter((rid) => runMap.has(rid))
      .map((rid) => {
        const { mentioned, total } = runMap.get(rid)!;
        return { runId: rid, rate: total > 0 ? Math.round((mentioned / total) * 100) : 0 };
      }),
  }));
}

export function toReportData(raw: {
  exposure: Parameters<typeof toExposureData>[0];
  diagnosis: Parameters<typeof toDiagnosisData>[0];
  improvement: Parameters<typeof toImprovementData>[0];
  tracking: Parameters<typeof toTrackingData>[0];
}): ReportData {
  const exposure = toExposureData(raw.exposure);
  const diagnosis = toDiagnosisData(raw.diagnosis);
  const improvement = toImprovementData(raw.improvement);
  const tracking = toTrackingData(raw.tracking);

  const availableRounds = tracking.rounds.map((r, i) => ({
    runId: r.runId,
    date: r.date,
    label: `${i + 1}차 측정`,
  }));

  const selectedRunId = availableRounds.length > 0
    ? availableRounds[availableRounds.length - 1].runId
    : "";

  return { availableRounds, selectedRunId, exposure, diagnosis, improvement, tracking };
}

export function toWebsiteData(raw: unknown): WebsiteData | null {
  if (!raw) return null;
  const r = raw as any;
  return {
    verdict: r.verdict ?? {},
    lighthouse: { categories: Array.isArray(r.lighthouse?.categories) ? r.lighthouse.categories : [] },
    coreWebVitals: { metrics: Array.isArray(r.coreWebVitals?.metrics) ? r.coreWebVitals.metrics : [] },
    seoAnalysis: r.seoAnalysis ?? undefined,
    geoAnalysis: r.geoAnalysis ?? undefined,
    priorityFixes: Array.isArray(r.priorityFixes) ? r.priorityFixes : [],
    analysisModels: Array.isArray(r.analysisModels) ? r.analysisModels : undefined,
  };
}
