import { useQuery } from "@tanstack/react-query";
import { useParams } from "react-router-dom";
import { fetchRunsRaw } from "./dataHub/api";

interface RunRow {
  id: string;
  status: string;
  completedAt?: unknown;
  createdAt?: unknown;
  triggerType?: string;
  queriesCount?: number;
  totalCalls?: number;
}

const fmt = (s: unknown) => { try { return new Date(s as string).toISOString().slice(0, 10).replace(/-/g, "."); } catch { return "-"; } };
const STATUS: Record<string, string> = { done: "완료", failed: "실패", running: "측정 중", analyzing: "분석 중", pending: "대기" };
const statusColor = (s: string) => s === "done" ? "text-emerald-400" : s === "failed" ? "text-rose-400" : "text-amber-400";

export function V4ReportExtra() {
  const { id } = useParams();
  const runsQ = useQuery({ queryKey: ["v3-runs-50", id], queryFn: () => fetchRunsRaw(id!, 50), enabled: !!id });
  const runs = (runsQ.data?.runs || []) as unknown as RunRow[];

  const downloadExcel = async (_runId: string) => {
    alert("엑셀 다운로드는 현재 Firestore 환경에서 지원되지 않습니다. CSV 다운로드를 사용해주세요.");
  };

  return (
    <section className="space-y-4">
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">측정 일자별 리포트</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">측정 회차(일자)별로 엑셀 보고서를 내려받을 수 있습니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">측정 일자별로 보고서를 받을 수 있나요?</span>
          <span className="text-[11px] text-[var(--shell-text-soft)]">{runs.length}건</span>
        </div>

        {runs.length > 0 ? (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                  <th className="px-4 py-3">측정 일자</th>
                  <th className="px-4 py-3">유형</th>
                  <th className="px-4 py-3">상태</th>
                  <th className="px-4 py-3 text-right">질문 / 답변</th>
                  <th className="px-4 py-3 text-right">다운로드</th>
                </tr>
              </thead>
              <tbody>
                {runs.map((r, i) => (
                  <tr key={r.id} className="border-b border-[var(--shell-border)]">
                    <td className="px-4 py-2.5 text-[var(--shell-text)]">
                      {fmt(r.completedAt || r.createdAt)}
                      {i === 0 && <span className="ml-1.5 rounded-full bg-[var(--shell-accent-soft)] px-1.5 py-0.5 text-[9px] font-bold text-[var(--shell-accent)]">최신</span>}
                    </td>
                    <td className="px-4 py-2.5 text-[var(--shell-text-muted)]">{r.triggerType === "scheduled" ? "자동" : "수동"}</td>
                    <td className={`px-4 py-2.5 font-semibold ${statusColor(r.status)}`}>{STATUS[r.status] || r.status}</td>
                    <td className="px-4 py-2.5 text-right text-[var(--shell-text-muted)]">{r.queriesCount ?? "-"} / {r.totalCalls ?? "-"}</td>
                    <td className="px-4 py-2.5 text-right">
                      {r.status === "done" ? (
                        <button
                          type="button"
                          onClick={() => downloadExcel(r.id)}
                          className="rounded-full bg-[var(--shell-accent-soft)] px-2.5 py-1 text-[10px] font-bold text-[var(--shell-accent)] hover:bg-[var(--shell-accent-soft)] transition-colors"
                        >
                          엑셀
                        </button>
                      ) : (
                        <span className="text-[11px] text-[var(--shell-text-soft)]">-</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="px-5 py-8 text-center text-xs text-[var(--shell-text-soft)]">측정 회차가 아직 없습니다.</div>
        )}
      </article>
    </section>
  );
}
