import { useParams } from "react-router-dom";
import { useImprovement } from "./dataHub";
import { V4TrackRecommendations } from "./V4TrackRecommendations";
import { HeaderV4DiagnosticButton } from "./V4DiagnosticPanel";
import { runImprovementDiagnostics } from "./diagnostics/improvementDiagnostics";

const priorityMeta: Record<string, { badge: string; border: string }> = {
  P1: { badge: "bg-rose-500/20 text-rose-400", border: "border-rose-400/20" },
  P2: { badge: "bg-amber-500/20 text-amber-400", border: "border-amber-400/20" },
  P3: { badge: "bg-sky-500/20 text-sky-400", border: "border-sky-400/20" },
};

const timelineDotColor = (i: number) => {
  if (i === 0) return "bg-emerald-400";
  if (i === 2) return "bg-amber-400";
  if (i === 3) return "bg-fuchsia-400";
  return "bg-[var(--shell-accent)]";
};

export function PortalV4ImprovementPlan() {
  const { id } = useParams();
  const { data, isLoading } = useImprovement(id || "");

  if (isLoading || !data) {
    return <div className="flex h-64 items-center justify-center text-gray-500">로딩 중...</div>;
  }

  return (
    <>
      {id && <HeaderV4DiagnosticButton boardId={id} title="V4 Improvement 진단" runner={runImprovementDiagnostics} />}
      <div className="mx-auto max-w-5xl space-y-6 p-6">
      {/* Topbar */}
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div>
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-accent)]">실행·개선 과제</div>
          <h1 className="mt-1 text-xl font-extrabold text-[var(--shell-text)]">AI 검색결과 개선 방향</h1>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            진단 결과를 바탕으로 AI가 자사를 추천 후보로 포함할 수 있도록 콘텐츠 구조와 실행 과제를 정리합니다.
          </p>
        </div>
        <div className="flex flex-col items-end gap-1 text-right">
          <div className="text-xs text-[var(--shell-text-soft)]">측정 기간 2025.05.15 – 2025.06.26</div>
        </div>
      </div>

      {/* 핵심 진단 배너 */}
      <article className="rounded-xl border border-[var(--shell-accent)]/20 bg-[var(--shell-accent-soft)] p-5">
        <div className="mb-2 text-[11px] font-bold text-[var(--shell-accent)]">핵심 진단</div>
        <h2 className="text-sm font-bold text-[var(--shell-text)]">{data.diagnosisBanner.headline}</h2>
        <p className="mt-2 text-xs leading-relaxed text-[var(--shell-text-muted)]">{data.diagnosisBanner.gapSummary}</p>
        <div className="mt-3 flex flex-wrap gap-2">
          {data.tasks.slice(0, 3).map((task) => {
            const colors = [
              "border border-sky-400/50 bg-sky-500/15 text-sky-300 shell-badge-sky",
              "border border-emerald-400/50 bg-emerald-500/15 text-emerald-300 shell-badge-emerald",
              "border border-fuchsia-400/50 bg-fuchsia-500/15 text-fuchsia-300 shell-badge-fuchsia",
            ];
            const idx = data.tasks.indexOf(task);
            return (
              <span key={task.id} className={`rounded-full px-2.5 py-0.5 text-[10px] font-bold ${colors[idx % colors.length]}`}>
                {task.title.split(" ").slice(0, 3).join(" ")}
              </span>
            );
          })}
        </div>
      </article>

      {/* 우선 개선 과제 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">우선 개선 과제</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">노출 공백이 크고 구매 의도가 높은 순서로 정렬했습니다.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-1 lg:grid-cols-3">
        {data.tasks.map((task, i) => {
          const meta = priorityMeta[task.priority] || priorityMeta.P3;
          return (
            <article key={task.id} className={`rounded-xl border ${meta.border} bg-[var(--shell-panel)] p-5`}>
              <div className="mb-3">
                <span className={`inline-block rounded px-2 py-0.5 text-[10px] font-bold ${meta.badge}`}>
                  {i + 1}순위 · {task.priority === "P1" ? "긴급" : "중요"}
                </span>
                <h3 className="mt-2 text-sm font-bold text-[var(--shell-text)]">{task.title}</h3>
              </div>
              <div className="space-y-3">
                <div>
                  <span className="text-[10px] font-semibold text-[var(--shell-text-soft)]">진단 근거</span>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{task.description}</p>
                </div>
                {task.relatedQueries && task.relatedQueries.length > 0 && (
                  <div>
                    <span className="text-[10px] font-semibold text-[var(--shell-text-soft)]">대상 질문</span>
                    <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{task.relatedQueries.join(", ")}</p>
                  </div>
                )}
                {task.expectedDelta && (
                  <div>
                    <span className="text-[10px] font-semibold text-[var(--shell-text-soft)]">예상 효과</span>
                    <p className="mt-0.5 text-xs text-emerald-400 font-semibold">{task.expectedDelta}%p</p>
                  </div>
                )}
              </div>
            </article>
          );
        })}
      </div>

      {/* 콘텐츠 구조화 과제 상세 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">콘텐츠 구조화 과제 상세</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">AI 답변에 활용되기 쉬운 순서로 정리합니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">우선 실행 과제는 무엇인가요?</span>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                <th className="px-4 py-3">우선순위</th>
                <th className="px-4 py-3">개선 과제</th>
                <th className="px-4 py-3">실행 내용</th>
                <th className="px-4 py-3">산출물 유형</th>
                <th className="px-4 py-3">상태</th>
              </tr>
            </thead>
            <tbody>
              {data.tasks.map((task, i) => (
                <tr key={task.id} className={`border-b border-[var(--shell-border)] ${i === 0 ? "bg-rose-500/5" : ""}`}>
                  <td className="px-4 py-3">
                    <span className="rounded bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[10px] font-bold text-[var(--shell-accent)]">{i + 1}순위</span>
                  </td>
                  <td className="px-4 py-3 font-medium text-[var(--shell-text)]">{task.title}</td>
                  <td className="max-w-[200px] px-4 py-3 text-[var(--shell-text-muted)]">{task.description}</td>
                  <td className="px-4 py-3 text-[var(--shell-text-muted)]">{task.category}</td>
                  <td className="px-4 py-3">
                    <span className="rounded-full border border-rose-400/30 px-2 py-0.5 text-[10px] font-bold text-rose-400">작성 필요</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </article>

      {/* 첫 산출물 선정 기준 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">첫 산출물 선정 기준</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">노출 공백·구매 의도·경쟁사 언급 여부·제품 연결 가능성을 기준으로 정합니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">첫 산출물은 어떻게 정하나요?</span>
        </div>
        <div className="p-5">
          <p className="text-xs leading-relaxed text-[var(--shell-text-muted)] mb-4">
            첫 제작 콘텐츠는 임의로 정하지 않고, 질문별 노출 공백·구매 의도·경쟁사 언급 여부·자사 제품과의 연결 가능성을 함께 보고 확정합니다.
          </p>
          <div className="grid gap-5 md:grid-cols-2">
            <ul className="space-y-1.5 text-xs text-[var(--shell-text-muted)]">
              <li>- 자사 브랜드 언급률이 낮거나 없는 질문</li>
              <li>- 구매 검토 의도가 높은 질문</li>
              <li>- 경쟁 브랜드는 언급되지만 자사는 빠지는 질문</li>
              <li>- 자사 제품의 강점과 자연스럽게 연결 가능한 질문</li>
              <li>- 하나의 콘텐츠로 여러 질문에 대응할 수 있는 질문</li>
            </ul>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                    <th className="px-3 py-2">후보 콘텐츠</th>
                    <th className="px-3 py-2">우선 검토 이유</th>
                  </tr>
                </thead>
                <tbody>
                  {data.candidates.map((c) => (
                    <tr key={c.id} className="border-b border-[var(--shell-border)]">
                      <td className="px-3 py-2 text-[var(--shell-text)]">{c.title}</td>
                      <td className="px-3 py-2 text-[var(--shell-text-muted)]">{c.targetQuery}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </article>

      {/* 실행 로드맵 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">실행 로드맵</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">과제별 예상 실행 순서와 다음 측정 목표입니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">언제까지, 무엇을 해야 하나요?</span>
        </div>
        <div className="p-5">
          <div className="relative space-y-0">
            {data.timeline.map((week, i) => (
              <div key={week.weekLabel} className="relative flex gap-4 pb-6">
                {i < data.timeline.length - 1 && (
                  <div className="absolute left-[7px] top-4 h-full w-px bg-[var(--shell-border)]" />
                )}
                <div className={`relative z-10 mt-1 h-3.5 w-3.5 shrink-0 rounded-full ${timelineDotColor(i)}`} />
                <div>
                  <div className="text-[11px] font-bold text-[var(--shell-text-soft)] mb-1">{week.weekLabel}</div>
                  <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
                    <ul className="space-y-1">
                      {week.tasks.map((t) => (
                        <li key={t} className="text-xs text-[var(--shell-text)]">{t}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </article>

      {/* 검토할 추천 */}
      <V4TrackRecommendations />
    </div>
    </>
  );
}
